func:
// récupère le port série à utiliser
    msg.payload = {
    "serialport": global.get("jkbms_path"),
    "serialbaud": 115200,
    "databits": 8,
    "parity": "none",
    "stopbits": 1,
    "enabled": true
    }

    node.send(msg)

// Récupération des données du payload
const data = msg.payload;

// Conserver les options brutes pour les autres composants.
if (data && typeof data === "object") {
    global.set("addon_options", data);
}

// Fonction pour traiter les champs contenant ":"
function processAddressPortFields(data) {
    const processedData = { ...data }; // Copie de l'objet original

    // Liste des champs à traiter (ceux qui peuvent contenir adresse:port)
    const fieldsToProcess = [
        { field: 'gateway_ip_port', addressField: 'gateway_ip', portField: 'gateway_port' },
        { field: 'mqttadresse_port', addressField: 'mqttadresse', portField: 'mqttport' },
        { field: 'cloud_broker_adress_port', addressField: 'cloud_broker_adress', portField: 'cloud_broker_port' }
    ];

    fieldsToProcess.forEach(config => {
        if (processedData[config.field] && typeof processedData[config.field] === 'string') {
            const value = processedData[config.field];

            // Vérifier si le champ contient ":"
            if (value.includes(':')) {
                const lastColonIndex = value.lastIndexOf(':'); // Utilise le dernier ":" pour gérer les IPv6
                const address = value.substring(0, lastColonIndex);
                const port = value.substring(lastColonIndex + 1);

                // Ajouter les champs séparés
                processedData[config.addressField] = address;
                processedData[config.portField] = parseInt(port, 10);

                node.log(`Champ '${config.field}' traité: ${address}:${port}`);
            }

            // Supprimer le champ original avec "_port" 
            delete processedData[config.field];
        }
    });

    return processedData;
}

// Extraction et stockage des variables globales
try {
    // Traitement préalable des champs avec ":"
    const processedData = processAddressPortFields(data);

    // SmartPhoton JK-BMS Multi-Pack v1.x: no Legacy single-bus runtime.

    if (processedData.communication_debug !== undefined) {
        global.set("communication_debug", processedData.communication_debug);
        node.log("Variable globale 'communication_debug' = " + processedData.communication_debug);
    }

    if (processedData.bms_broadcasting !== undefined) {
        global.set("bms_broadcasting", processedData.bms_broadcasting);
        node.log("Variable globale 'bms_broadcasting' = " + processedData.bms_broadcasting);
    }

    // =========================================================
    // MULTI-PACK TRANSPORTS - TCP / SERIAL-USB
    // Up to five independent JK-BMS RS485 buses / battery packs.
    // Broadcasting already supports mixed TCP/Serial transports.
    // v4.2.90 extends the same transport definitions to Active Polling.
    // =========================================================
    function parseTcpEndpoint(value) {
        const raw = String(value || "").trim();
        if (!raw) return null;

        let host = "";
        let portText = "";

        // IPv6 entre crochets : [2001:db8::1]:5021
        if (raw.startsWith("[")) {
            const m = raw.match(/^\[([^\]]+)\]:(\d+)$/);
            if (!m) return null;
            host = m[1].trim();
            portText = m[2];
        } else {
            // IPv4 / hostname : host:port
            const pos = raw.lastIndexOf(":");
            if (pos <= 0 || pos >= raw.length - 1) return null;
            host = raw.substring(0, pos).trim();
            portText = raw.substring(pos + 1).trim();
        }

        const port = Number(portText);
        if (!host || !Number.isInteger(port) || port < 1 || port > 65535) {
            return null;
        }

        return { host, port };
    }

    function normalizePackId(value) {
        const id = String(value || "").trim().toLowerCase();
        return id;
    }

    const multiPackRequested = true; // Multi-Pack-only add-on
    const activePollingRequested = processedData.multi_pack_active_polling === true;
    global.set("jkbmsActiveRequested", activePollingRequested);
    const rawPacks = Array.isArray(processedData.multi_pack_packs)
        ? processedData.multi_pack_packs
        : [];

    // IDs techniques stables supportés par l'architecture v4.2.
    const SUPPORTED_PACK_IDS = ["pack_1", "pack_2", "pack_3", "pack_4", "pack_5"];
    const MAX_MULTI_PACK = SUPPORTED_PACK_IDS.length;

    // Five independent transport slots are available.
    const TRANSPORT_READY_PACK_IDS = [
        "pack_1",
        "pack_2",
        "pack_3",
        "pack_4",
        "pack_5"
    ];

    const packDefs = {};
    const packIds = [];
    const configErrors = [];
    const configWarnings = [];
    const usedIds = new Set();
    const usedEndpoints = new Map();
    const usedSerialPaths = new Map();

    if (rawPacks.length > MAX_MULTI_PACK) {
        configErrors.push(
            `Multi-Pack: ${rawPacks.length} packs configurés. Maximum supporté: ${MAX_MULTI_PACK}.`
        );
    }

    // ---------------------------------------------------------
    // Pré-analyse des ID explicitement configurés.
    // Older Multi-Pack configurations may not have an explicit
    // stable "id" field; positional fallback remains supported.
    // ---------------------------------------------------------
    const entries = rawPacks.slice(0, MAX_MULTI_PACK).map((entry, index) => {
        const explicitId = normalizePackId(entry && entry.id);

        return {
            entry: entry || {},
            index,
            explicitId,
            resolvedId: null
        };
    });

    // 1) Valider/réserver les ID explicitement saisis.
    for (const item of entries) {
        if (!item.explicitId) continue;

        if (!SUPPORTED_PACK_IDS.includes(item.explicitId)) {
            configErrors.push(
                `Multi-Pack: ID "${item.explicitId}" non supporté. ` +
                `Valeurs autorisées: ${SUPPORTED_PACK_IDS.join(", ")}.`
            );
            continue;
        }

        if (usedIds.has(item.explicitId)) {
            configErrors.push(
                `Multi-Pack: ID dupliqué "${item.explicitId}". Chaque pack doit avoir un ID unique.`
            );
            continue;
        }

        item.resolvedId = item.explicitId;
        usedIds.add(item.explicitId);
    }

    // 2) Migration douce des anciennes listes sans ID.
    //    - si un seul ID reste libre, on l'attribue automatiquement;
    //    - si tous les ID sont absents, on reprend l'ordre historique.
    const availableIds = () =>
        SUPPORTED_PACK_IDS.filter(id => !usedIds.has(id));

    for (const item of entries) {
        if (item.resolvedId || item.explicitId) continue;

        const remaining = availableIds();
        let fallbackId = null;

        if (remaining.length === 1) {
            fallbackId = remaining[0];
        } else {
            const positionalId = `pack_${item.index + 1}`;
            fallbackId = remaining.includes(positionalId)
                ? positionalId
                : remaining[0];
        }

        if (!fallbackId) {
            configErrors.push(
                `Multi-Pack: impossible d'attribuer automatiquement un ID au pack #${item.index + 1}.`
            );
            continue;
        }

        item.resolvedId = fallbackId;
        usedIds.add(fallbackId);

        configWarnings.push(
            `${fallbackId}: configuration héritée sans champ "id". ` +
            `Ajoute l'ID stable dans la configuration pour rendre le pack indépendant de l'ordre de la liste.`
        );
    }

    // 3) Construire les définitions par ID, indépendamment de l'ordre.
    //
    // Compatibilité v4.2.57:
    // - transport absent + gateway_ip_port valide => TCP, inchangé.
    //
    // v4.2.64:
    // - pack_1 à pack_5 peuvent utiliser transport=serial (alias usb/rs485);
    // - path / serial_path / usb_path / jkbms_path du pack est prioritaire;
    // - un seul pack peut hériter implicitement du jkbms_path Legacy;
    // - priorité d'héritage: pack_1, puis pack_2, pack_3, pack_4, pack_5;
    // - les cinq slots Multi-Pack sont désormais indépendamment TCP ou série.
    function normalizePackTransport(value) {
        const s = String(value || "").trim().toLowerCase();
        if (!s) return null;
        if (["serial", "usb", "rs485"].includes(s)) return "serial";
        if (["tcp", "gateway", "tcpip", "tcp/ip"].includes(s)) return "tcp";
        return "invalid";
    }

    // Multi-Pack-only: every serial pack must declare its own explicit path.
    // No inheritance from the historical Legacy jkbms_path is allowed.
    const legacySerialFallbackPath = "";

    // Déterminer l'usage prévu de pack_1 indépendamment de l'ordre de la liste.
    // Cela évite que le fallback série de pack_2 dépende de la position des lignes.
    const pack1Item = entries.find(item => item.resolvedId === "pack_1");
    const pack2Item = entries.find(item => item.resolvedId === "pack_2");
    const pack3Item = entries.find(item => item.resolvedId === "pack_3");
    const pack4Item = entries.find(item => item.resolvedId === "pack_4");

    let pack1ClaimsSerial = false;
    let pack2ClaimsSerial = false;
    let pack3ClaimsSerial = false;
    let pack4ClaimsSerial = false;

    if (pack1Item) {
        const p1 = pack1Item.entry || {};
        const p1Transport = normalizePackTransport(p1.transport);
        const p1Endpoint = String(p1.gateway_ip_port || "").trim();
        const p1ExplicitSerialPath = String(
            p1.path ||
            p1.serial_path ||
            p1.usb_path ||
            p1.jkbms_path ||
            ""
        ).trim();

        if (p1Transport === "serial") {
            pack1ClaimsSerial = true;
        } else if (p1Transport === "tcp") {
            pack1ClaimsSerial = false;
        } else if (!p1Transport) {
            pack1ClaimsSerial =
                !p1Endpoint &&
                !!(p1ExplicitSerialPath || legacySerialFallbackPath);
        }
    }

    if (pack2Item) {
        const p2 = pack2Item.entry || {};
        const p2Transport = normalizePackTransport(p2.transport);
        const p2Endpoint = String(p2.gateway_ip_port || "").trim();
        const p2ExplicitSerialPath = String(
            p2.path ||
            p2.serial_path ||
            p2.usb_path ||
            p2.jkbms_path ||
            ""
        ).trim();

        if (p2Transport === "serial") {
            pack2ClaimsSerial = true;
        } else if (p2Transport === "tcp") {
            pack2ClaimsSerial = false;
        } else if (!p2Transport) {
            pack2ClaimsSerial =
                !p2Endpoint &&
                !!(
                    p2ExplicitSerialPath ||
                    (!pack1ClaimsSerial && legacySerialFallbackPath)
                );
        }
    }

    if (pack3Item) {
        const p3 = pack3Item.entry || {};
        const p3Transport = normalizePackTransport(p3.transport);
        const p3Endpoint = String(p3.gateway_ip_port || "").trim();
        const p3ExplicitSerialPath = String(
            p3.path ||
            p3.serial_path ||
            p3.usb_path ||
            p3.jkbms_path ||
            ""
        ).trim();

        if (p3Transport === "serial") {
            pack3ClaimsSerial = true;
        } else if (p3Transport === "tcp") {
            pack3ClaimsSerial = false;
        } else if (!p3Transport) {
            pack3ClaimsSerial =
                !p3Endpoint &&
                !!(
                    p3ExplicitSerialPath ||
                    (
                        !pack1ClaimsSerial &&
                        !pack2ClaimsSerial &&
                        legacySerialFallbackPath
                    )
                );
        }
    }

    if (pack4Item) {
        const p4 = pack4Item.entry || {};
        const p4Transport = normalizePackTransport(p4.transport);
        const p4Endpoint = String(p4.gateway_ip_port || "").trim();
        const p4ExplicitSerialPath = String(
            p4.path ||
            p4.serial_path ||
            p4.usb_path ||
            p4.jkbms_path ||
            ""
        ).trim();

        if (p4Transport === "serial") {
            pack4ClaimsSerial = true;
        } else if (p4Transport === "tcp") {
            pack4ClaimsSerial = false;
        } else if (!p4Transport) {
            pack4ClaimsSerial =
                !p4Endpoint &&
                !!(
                    p4ExplicitSerialPath ||
                    (
                        !pack1ClaimsSerial &&
                        !pack2ClaimsSerial &&
                        !pack3ClaimsSerial &&
                        legacySerialFallbackPath
                    )
                );
        }
    }

    for (const item of entries) {
        const entry = item.entry;
        const packId = item.resolvedId;

        if (!packId) continue;

        const slotMatch = packId.match(/^pack_(\d+)$/);
        const slot = slotMatch ? Number(slotMatch[1]) : (item.index + 1);

        const packNameRaw = String(entry.name || "").trim();
        const packName = packNameRaw || `Pack ${slot}`;

        const endpointText = String(entry.gateway_ip_port || "").trim();
        const explicitSerialPath = String(
            entry.path ||
            entry.serial_path ||
            entry.usb_path ||
            entry.jkbms_path ||
            ""
        ).trim();

        const legacySerialPath = legacySerialFallbackPath;

        const pack2MayInheritLegacySerial =
            packId === "pack_2" &&
            pack1ClaimsSerial === false;

        const pack3MayInheritLegacySerial =
            packId === "pack_3" &&
            pack1ClaimsSerial === false &&
            pack2ClaimsSerial === false;

        const pack4MayInheritLegacySerial =
            packId === "pack_4" &&
            pack1ClaimsSerial === false &&
            pack2ClaimsSerial === false &&
            pack3ClaimsSerial === false;

        const pack5MayInheritLegacySerial =
            packId === "pack_5" &&
            pack1ClaimsSerial === false &&
            pack2ClaimsSerial === false &&
            pack3ClaimsSerial === false &&
            pack4ClaimsSerial === false;

        let transport = normalizePackTransport(entry.transport);

        // Migration douce USB -> Multi-Pack:
        // le premier slot sans endpoint TCP peut reprendre jkbms_path,
        // à condition qu'aucun slot précédent ne revendique déjà ce port.
        if (!transport) {
            const serialCapablePack =
                ["pack_1", "pack_2", "pack_3", "pack_4", "pack_5"].includes(packId);

            let inheritedSerialCandidate = "";
            if (packId === "pack_1") inheritedSerialCandidate = legacySerialPath;
            else if (pack2MayInheritLegacySerial) inheritedSerialCandidate = legacySerialPath;
            else if (pack3MayInheritLegacySerial) inheritedSerialCandidate = legacySerialPath;
            else if (pack4MayInheritLegacySerial) inheritedSerialCandidate = legacySerialPath;
            else if (pack5MayInheritLegacySerial) inheritedSerialCandidate = legacySerialPath;

            const serialCandidate =
                explicitSerialPath ||
                inheritedSerialCandidate;

            if (
                serialCapablePack &&
                !endpointText &&
                serialCandidate
            ) {
                transport = "serial";
            } else {
                transport = "tcp";
            }
        }

        if (transport === "invalid") {
            configErrors.push(
                `${packId}: transport invalide (${String(entry.transport || "")}). ` +
                `Valeurs supportées: tcp ou serial.`
            );
            continue;
        }

        if (transport === "serial") {
            if (!["pack_1", "pack_2", "pack_3", "pack_4", "pack_5"].includes(packId)) {
                configErrors.push(
                    `${packId}: transport serial non supporté.`
                );
                continue;
            }

            const inheritedLegacySerial =
                packId === "pack_1" ||
                pack2MayInheritLegacySerial ||
                pack3MayInheritLegacySerial ||
                pack4MayInheritLegacySerial ||
                pack5MayInheritLegacySerial;

            const serialPath =
                explicitSerialPath ||
                (inheritedLegacySerial ? legacySerialPath : "");

            if (
                packId === "pack_2" &&
                !explicitSerialPath &&
                pack2MayInheritLegacySerial &&
                serialPath
            ) {
                configWarnings.push(
                    `${packId}: chemin série hérité de jkbms_path (${serialPath}) ` +
                    `car pack_1 utilise TCP.`
                );
            }

            if (
                packId === "pack_3" &&
                !explicitSerialPath &&
                pack3MayInheritLegacySerial &&
                serialPath
            ) {
                configWarnings.push(
                    `${packId}: chemin série hérité de jkbms_path (${serialPath}) ` +
                    `car pack_1 et pack_2 utilisent TCP.`
                );
            }

            if (
                packId === "pack_4" &&
                !explicitSerialPath &&
                pack4MayInheritLegacySerial &&
                serialPath
            ) {
                configWarnings.push(
                    `${packId}: chemin série hérité de jkbms_path (${serialPath}) ` +
                    `car pack_1, pack_2 et pack_3 utilisent TCP.`
                );
            }

            if (
                packId === "pack_5" &&
                !explicitSerialPath &&
                pack5MayInheritLegacySerial &&
                serialPath
            ) {
                configWarnings.push(
                    `${packId}: chemin série hérité de jkbms_path (${serialPath}) ` +
                    `car pack_1, pack_2, pack_3 et pack_4 utilisent TCP.`
                );
            }

            if (!serialPath) {
                configErrors.push(
                    `${packId}: chemin série manquant ` +
                    `(path/serial_path/usb_path/jkbms_path).`
                );
                continue;
            }

            const serialKey = serialPath.toLowerCase();
            if (usedSerialPaths.has(serialKey)) {
                configErrors.push(
                    `${packId}: port série ${serialPath} déjà utilisé par ` +
                    `${usedSerialPaths.get(serialKey)}. ` +
                    `Chaque pack série doit utiliser un bus USB/RS485 indépendant.`
                );
                continue;
            }
            usedSerialPaths.set(serialKey, packId);

            packDefs[packId] = {
                id: packId,
                slot,
                source_index: item.index + 1,
                explicit_id: !!item.explicitId,
                name: packName,
                transport: "serial",
                path: serialPath,
                host: null,
                port: null,
                gateway_ip_port: null,
                bus_id: `rs485_${packId}`
            };

            continue;
        }

        const endpoint = parseTcpEndpoint(endpointText);

        if (!endpoint) {
            configErrors.push(
                `${packId}: gateway_ip_port invalide (${endpointText})`
            );
            continue;
        }

        const endpointKey = `${endpoint.host.toLowerCase()}:${endpoint.port}`;
        if (usedEndpoints.has(endpointKey)) {
            configErrors.push(
                `${packId}: endpoint TCP ${endpoint.host}:${endpoint.port} déjà utilisé par ${usedEndpoints.get(endpointKey)}.`
            );
            continue;
        }
        usedEndpoints.set(endpointKey, packId);

        packDefs[packId] = {
            id: packId,
            slot,
            source_index: item.index + 1,
            explicit_id: !!item.explicitId,
            name: packName,
            transport: "tcp",
            path: null,
            host: endpoint.host,
            port: endpoint.port,
            gateway_ip_port: `${endpoint.host}:${endpoint.port}`,
            bus_id: `tcp_${endpoint.port}`
        };
    }

    // Noms identiques autorisés, mais avertissement pour éviter la confusion.
    const namesSeen = new Map();
    for (const id of SUPPORTED_PACK_IDS) {
        const p = packDefs[id];
        if (!p) continue;
        const nameKey = p.name.trim().toLowerCase();
        if (!nameKey) continue;

        if (namesSeen.has(nameKey)) {
            configWarnings.push(
                `${id}: le nom "${p.name}" est aussi utilisé par ${namesSeen.get(nameKey)}. ` +
                `Les ID restent uniques, mais des noms différents sont recommandés.`
            );
        } else {
            namesSeen.set(nameKey, id);
        }
    }

    // Ordre interne déterministe : toujours pack_1, pack_2, pack_3, pack_4, pack_5,
    // même si l'utilisateur réordonne les lignes dans l'interface HA.
    for (const id of SUPPORTED_PACK_IDS) {
        if (packDefs[id]) packIds.push(id);
    }

    // v4.2.98: Active Polling accepts the same per-pack transports as Broadcasting:
    // TCP gateway or direct Serial/USB RS485, including mixed installations.
    //
    // BMS addressing:
    // - empty / omitted / "auto" => automatic discovery of addresses 1..15
    // - "1,2,3"                 => manual/expert mode, preserved for compatibility
    //
    // IMPORTANT: this block belongs only to Multi-Pack Active Polling.
    // Legacy addressing and Legacy communication are intentionally untouched.
    let activePollingValid = activePollingRequested && multiPackRequested &&
        global.get("bms_broadcasting") === false && processedData.CAN_bus_usage !== true;
    if (activePollingRequested) {
        if (!activePollingValid) {
            configErrors.push("Active Polling exige bms_broadcasting=false et CAN_bus_usage=false");
        }

        for (const def of Object.values(packDefs)) {
            const sourceItem = entries.find(item => item.resolvedId === def.id);
            const raw = sourceItem ? sourceItem.entry : {};
            const text = String(raw.bms_addresses ?? "").trim();
            const autoDiscovery = text === "" || /^auto$/i.test(text);
            const validText = /^\d+(\s*,\s*\d+)*$/.test(text);
            const addresses = validText
                ? text.split(",").map(v => Number(v.trim()))
                : [];

            if (!autoDiscovery && (
                !validText ||
                addresses.some(a => !Number.isInteger(a) || a < 0 || a > 15) ||
                new Set(addresses).size !== addresses.length
            )) {
                configErrors.push(`${def.id}: bms_addresses invalide. Laisser vide / utiliser "auto", ou saisir une liste 0..15 (exemple 0,2)`);
                activePollingValid = false;
            }

            if (!["tcp", "serial"].includes(def.transport)) {
                configErrors.push(`${def.id}: transport Active Polling non supporté (${def.transport})`);
                activePollingValid = false;
            }

            if (def.transport === "serial") {
                def.baudRate = 115200;
            }

            def.bms_discovery = autoDiscovery ? "auto" : "manual";
            def.bms_addresses = autoDiscovery ? [] : addresses;

            if (autoDiscovery) {
                node.log(`${def.id}: Active Polling BMS auto-discovery enabled (scan addresses 0..15)`);
            } else {
                node.log(`${def.id}: Active Polling manual BMS addresses = ${addresses.join(",")}`);
            }
        }
    }
    const multiPackPrerequisites = activePollingRequested ? activePollingValid :
        global.get("bms_broadcasting") === true;

    const pack1Valid = !!packDefs.pack_1;
    const fatalConfigError = configErrors.length > 0;

    const multiPackEnabled =
        multiPackRequested &&
        multiPackPrerequisites &&
        pack1Valid &&
        !fatalConfigError;

    // Distinguer les packs configurés des packs dont le transport
    // physique est disponible dans cette version du flow.
    const configuredPackIds = [...packIds];
    const activeTransportPackIds = configuredPackIds.filter(
        id => TRANSPORT_READY_PACK_IDS.includes(id)
    );
    const pendingTransportPackIds = configuredPackIds.filter(
        id => !TRANSPORT_READY_PACK_IDS.includes(id)
    );

    const allIdsExplicit =
        entries.length > 0 &&
        entries.every(item => !!item.explicitId && !!item.resolvedId);

    const identityMode = allIdsExplicit
        ? "stable_ids"
        : "legacy_position_fallback";

    global.set("multi_pack_requested", multiPackRequested);
    global.set("multi_pack_enabled", multiPackEnabled);
    global.set("jkbms_active_polling_enabled", activePollingRequested && multiPackEnabled);
    if (activePollingRequested && !multiPackEnabled) node.error("Active Polling configuration invalide : transports existants bloqués, aucun retour automatique en Legacy");

    // Generic Multi-Pack runtime globals.
    global.set("multi_pack_max", MAX_MULTI_PACK);
    global.set("multi_pack_supported_ids", SUPPORTED_PACK_IDS);
    global.set("multi_pack_transport_ready_ids", TRANSPORT_READY_PACK_IDS);
    global.set("multi_pack_identity_mode", identityMode);

    // ---------------------------------------------------------
    // RUNTIME PACK IDENTITY
    //
    // Step 13A: même le mode Legacy possède désormais une identité
    // interne stable "pack_1". Cette identité reste strictement interne:
    // elle ne modifie ni les topics MQTT Legacy, ni les unique_id HA,
    // ni les noms d'entités, ni les clés de discovery historiques.
    // ---------------------------------------------------------
    // Transport runtime unique et explicite.
    // En Multi-Pack, global.use_gateway continue de piloter uniquement
    // le transport historique de pack_1:
    // - pack_1 TCP    => true
    // - pack_1 serial => false
    // Pack 2 à Pack 5 possèdent chacun leur propre transport
    // TCP ou série indépendant.
    const multiPackPrimaryDef = multiPackEnabled
        ? (packDefs.pack_1 || null)
        : null;

    const multiPackPrimaryTransport =
        multiPackPrimaryDef && multiPackPrimaryDef.transport === "serial"
            ? "serial"
            : "tcp";

    const activeTransportModes = multiPackEnabled
        ? new Set(
            activeTransportPackIds
                .map(id => packDefs[id] && packDefs[id].transport)
                .filter(Boolean)
        )
        : new Set();

    const runtimeTransportMode = multiPackEnabled
        ? (
            activeTransportModes.size > 1
                ? "multi_pack_mixed"
                : (
                    multiPackPrimaryTransport === "serial"
                        ? "multi_pack_serial"
                        : "multi_pack_tcp"
                )
        )
        : "multi_pack_invalid";

    global.set("jkbms_transport_mode", runtimeTransportMode);

    // Compatibility alias still used by the historical Pack 1 Broadcasting
    // transport nodes. It now reflects Pack 1 only; there is no Legacy fallback.
    global.set(
        "use_gateway",
        multiPackEnabled && multiPackPrimaryTransport === "tcp"
    );

    const runtimePackDefs = multiPackEnabled ? packDefs : {};

    // Conserver séparément la configuration Multi-Pack saisie, même lorsque
    // Multi-Pack est OFF. jkbms_pack_defs représente désormais les packs
    // réellement utilisés par le runtime.
    global.set("jkbms_pack_defs_configured", packDefs);
    global.set("jkbms_pack_defs", runtimePackDefs);
    global.set("jkbms_pack_ids_configured", configuredPackIds);
    global.set(
        "jkbms_pack_ids",
        multiPackEnabled ? activeTransportPackIds : []
    );
    global.set("jkbms_runtime_primary_pack_id", "pack_1");
    global.set(
        "jkbms_runtime_identity_mode",
        multiPackEnabled ? "multi_pack_stable_ids" : "multi_pack_invalid"
    );
    global.set("jkbms_public_topic_mode", "multi_pack_prefixed");
    global.set("multi_pack_pending_transport_ids", pendingTransportPackIds);

    // Compatibility alias retained for older persisted contexts.
    global.set("multi_pack_max_v1", MAX_MULTI_PACK);

    global.set("multi_pack_config_errors", configErrors);
    global.set("multi_pack_config_warnings", configWarnings);

    // Réutiliser le transport historique de Pack 1.
    // - TCP: client TCP broadcasting existant.
    // - serial: port USB/RS485 dynamique existant via Setup USB Port.
    // Les deux chemins convergent ensuite vers le même framer Broadcast.
    if (multiPackEnabled && packDefs.pack_1) {
        const primaryDef = packDefs.pack_1;

        if (primaryDef.transport === "serial") {
            global.set("jkbms_path", primaryDef.path);
            global.set("gateway_ip", null);
            global.set("gateway_port", null);
        } else {
            global.set("gateway_ip", primaryDef.host);
            global.set("gateway_port", primaryDef.port);
        }
    }

    if (multiPackRequested && !multiPackEnabled) {
        const reasons = [];
        if (activePollingRequested) {
            if (global.get("bms_broadcasting") !== false) reasons.push("Active Polling exige bms_broadcasting=false");
            if (processedData.CAN_bus_usage === true) reasons.push("Active Polling exige CAN_bus_usage=false");
        } else if (global.get("bms_broadcasting") !== true) {
            reasons.push("Broadcasting Multi-Pack exige bms_broadcasting=true");
        }
        if (!pack1Valid) {
            reasons.push("pack_1 transport invalide ou absent");
        }
        if (fatalConfigError) {
            reasons.push("erreur(s) de configuration Multi-Pack");
        }

        node.warn(
            "Multi-Pack demandé mais non activé: " +
            reasons.join(", ")
        );
    }

    if (multiPackRequested && configErrors.length > 0) {
        configErrors.forEach(e => node.warn("Multi-Pack ERROR: " + e));
    }

    if (multiPackRequested && configWarnings.length > 0) {
        configWarnings.forEach(e => node.warn("Multi-Pack WARNING: " + e));
    }

    if (multiPackEnabled && pendingTransportPackIds.length > 0) {
        node.warn(
            "Multi-Pack: transport non disponible pour " +
