    if (multiPackEnabled) {
        global.set("jkbms_runtime_mode", "multi_pack");

        const transportSummary = configuredPackIds.map(id => {
            const def = packDefs[id];
            if (!def) return `${id}=unavailable`;

            if (def.transport === "serial") {
                return `${id}=serial ${def.path}`;
            }

            return `${id}=tcp ${def.host}:${def.port}`;
        }).join(" | ");

        node.log(
            `Transport runtime: ${runtimeTransportMode} -> ${transportSummary}`
        );

        node.warn(
            `Multi-Pack ACTIVE [${identityMode}] -> ` +
            configuredPackIds.map(id => {
                const p = packDefs[id];
                const endpoint = p.transport === "serial"
                    ? `serial ${p.path}`
