function sanitizeIds(values) {
    return [...new Set(
        (Array.isArray(values) ? values : [])
            .map(Number)
            .filter(id => Number.isInteger(id) && id >= 0 && id <= 15)
    )].sort((a, b) => a - b);
}

function armActivePollingSetupRediscovery() {
    if (global.get("multi_pack_enabled") !== true ||
        global.get("jkbms_active_polling_enabled") !== true) {
        return 0;
    }

    let packIds = global.get("jkbms_pack_ids");
    if (!Array.isArray(packIds) || packIds.length === 0) {
        packIds = ["pack_1"];
    }

    const defs = global.get("jkbms_pack_defs") || {};
    let armed = 0;

    for (const packId of packIds) {
        const def = defs[packId] || {};
        // Manual IDs are authoritative. With auto discovery, the configured
        // list is empty: reuse only recently observed addresses after MQTT
        // reconnection, including BMS_0. Legacy/Broadcasting never call here.
        let ids = sanitizeIds(def.bms_addresses);
        if (ids.length === 0 && def.bms_discovery === 'auto') {
            const registry = flow.get(`broadcast_bms_registry_${packId}`) || {};
            const maxAge = Number(registry.window_ms) > 0 ? Number(registry.window_ms) : 120000;
            const seen = registry.seen || {};
            const now = Date.now();
            ids = sanitizeIds(Object.entries(seen)
                .filter(([id, ts]) => Number.isFinite(Number(ts)) && now - Number(ts) <= maxAge)
                .map(([id]) => id));
        }

        for (const id of ids) {
            // Different Node-RED tab: use global flags. The SETUP discovery
            // node consumes and clears each individual flag after use.
            global.set(`forceSetupRepublish_${packId}_BMS_${id}`, true);
            armed++;
        }
    }

    return armed;
}

// Très important : tester "disconnected" AVANT "connected".
