// =========================================================

const PUBLIC_KEY_PEM = `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEANx4f2OpAbYfWEAGc87l4qX7Hf2nyJCih8nljqLBoMzA=
-----END PUBLIC KEY-----`;

// Produit attendu pour ce module
const EXPECTED_PRODUCT = "smartphoton-jkbms";
const EXPECTED_SYSTEM = "jkbms_rs485";
const EXPECTED_TIER = "premium";

const premiumKey = normStr(global.get("premium.key"));
const installId = normStr(global.get("premium.install_id"));

// =========================================================
// FEATURE / ENTITLEMENT MODEL
//
// One evolving Premium bundle:
// - all core monitoring features stay free;
// - Multi-BMS and Multi-Pack stay free;
// - a valid Premium tier unlocks every CURRENT premium feature;
// - old Premium licences automatically gain future premium features
//   added to this catalog, without requiring feature flags in the key.
// payload.features is retained as licence metadata only.
// =========================================================
const FEATURE_CATALOG = Object.freeze({
    mqtt_core: "free",
    ha_discovery: "free",
    multi_bms: "free",
    multi_pack: "free",
    health_basic: "free",

    dashboard_premium: "premium",
    multi_pack_diagnostics: "premium",
    csv_export: "premium",
    cycles_soh: "premium",
    cell_details: "premium",
    advanced_info: "premium"
});

function featuresForAccess(premiumActive) {
    const out = {};
    for (const [feature, access] of Object.entries(FEATURE_CATALOG)) {
        out[feature] = access === "free" || premiumActive === true;
    }
    return out;
}

const freeFeatures = featuresForAccess(false);

let premiumActive = false;
let premiumStatus = "missing_key";
let premiumTier = null;
let premiumPayload = null;
let premiumFeatures = { ...freeFeatures };
let licenseFeatures = {};
let licenseId = null;
let keyId = null;
let customer = null;
let issuedAt = null;
let expiresAt = null;

function verifySpv2License(license) {
    const raw = String(license || "").trim();
    const parts = raw.split(".");

    if (parts.length !== 3 || parts[0] !== "SPV2") {
        throw new Error("invalid_format");
    }

    const payloadB64 = parts[1];
    const signature = b64urlToBuffer(parts[2]);

    const ok = crypto.verify(
        null,
        Buffer.from(payloadB64, "utf8"),
        PUBLIC_KEY_PEM,
        signature
    );

    if (!ok) {
        throw new Error("invalid_signature");
    }

    return safeJsonParseBuffer(b64urlToBuffer(payloadB64));
}

function isExpiredDateOnly(expires) {
    const s = normStr(expires);
    if (!s) return false;

    // La VM utilise normalement YYYY-MM-DD.
    // On considère la licence valide jusqu'à la fin de cette date en UTC.
    let limit;
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) {
        limit = new Date(s + "T23:59:59.999Z");
    } else {
        limit = new Date(s);
    }

    if (Number.isNaN(limit.getTime())) {
        throw new Error("invalid_expiration");
    }

    return Date.now() > limit.getTime();
}

try {
    if (!crypto || typeof crypto.verify !== "function") {
        premiumStatus = "crypto_missing";
    } else if (isBlankPublicKey(PUBLIC_KEY_PEM)) {
        premiumStatus = "public_key_not_configured";
    } else if (!installId) {
        premiumStatus = "missing_install_id";
    } else if (!premiumKey) {
        premiumStatus = "missing_key";
    } else {
        const payload = verifySpv2License(premiumKey);

        if (Number(payload.v) !== 2) {
            premiumStatus = "invalid_payload_version";
        } else if (payload.iss !== "SmartPhoton") {
            premiumStatus = "invalid_issuer";
        } else if (payload.product !== EXPECTED_PRODUCT) {
            premiumStatus = "invalid_product";
        } else if (payload.system !== EXPECTED_SYSTEM) {
            premiumStatus = "invalid_system";
        } else if (payload.tier !== EXPECTED_TIER) {
            premiumStatus = "invalid_tier";
        } else if (normStr(payload.install_id) !== installId) {
            premiumStatus = "install_id_mismatch";
        } else if (isExpiredDateOnly(payload.expires_at)) {
            premiumStatus = "expired";
        } else {
            premiumActive = true;
            premiumStatus = "valid";
            premiumTier = payload.tier || EXPECTED_TIER;
            premiumPayload = payload;

            // The licence is tier-based, not feature-purchase based.
            // A valid Premium licence receives the complete current bundle.
            // Keep payload.features only for diagnostics / server metadata.
            licenseFeatures =
                payload.features && typeof payload.features === "object"
                    ? { ...payload.features }
                    : {};
            premiumFeatures = featuresForAccess(true);

            licenseId = payload.license_id || null;
            keyId = payload.key_id || null;
            customer = payload.customer || null;
            issuedAt = payload.issued_at || null;
            expiresAt = payload.expires_at || null;

            global.set("premium.last_valid", Date.now());
        }
    }
} catch (err) {
    premiumStatus = err.message || "invalid_license";
}

// =========================================================
// PREMIUM RUNTIME PROFILE
//
// Important:
// - entitlement = ce que la licence autorise
// - applicability = ce qui est utilisable dans le runtime courant
//
// Le dashboard Premium historique est Legacy uniquement.
// Le Multi-Pack reste Free, mais une licence Premium valide
// prépare l'accès aux futures fonctions Premium Multi-Pack.
// =========================================================

const runtimeModeRaw = String(
    global.get("jkbms_runtime_mode") || "legacy"
).trim().toLowerCase();

const runtimeMode =
    runtimeModeRaw === "multi_pack"
        ? "multi_pack"
        : "legacy";

const legacyDashboardApplicable =
    runtimeMode === "legacy";

const multiPackPremiumAvailable =
    runtimeMode === "multi_pack" &&
    premiumActive === true;

global.set("premium.runtime_mode", runtimeMode);
global.set(
    "premium.legacy_dashboard_applicable",
    legacyDashboardApplicable
);
global.set(
    "premium.multi_pack_premium_available",
    multiPackPremiumAvailable
);

// Variables globales historiques conservées
global.set("premium.active", premiumActive);
global.set("premium.status", premiumStatus);
global.set("premium.tier", premiumTier);

// Canonical entitlement state used by all feature gates.
global.set("premium.features", premiumFeatures);
global.set("premium.feature_catalog", FEATURE_CATALOG);
global.set("premium.free_features", freeFeatures);
global.set("premium.license_features", licenseFeatures);
global.set("premium.bundle", premiumActive ? "premium" : "free");
global.set("premium.bundle_version", 1);

// Nouvelles infos utiles
global.set("premium.payload", premiumPayload);
global.set("premium.license_id", licenseId);
global.set("premium.key_id", keyId);
global.set("premium.customer", customer);
global.set("premium.issued_at", issuedAt);
global.set("premium.expires_at", expiresAt);

// Compatibilité avec les noeuds qui lisent global.get("premium")
const premiumState = {
    install_id: installId || null,
    active: premiumActive,
    status: premiumActive ? "active" : premiumStatus,
    validation_status: premiumStatus,
    tier: premiumTier,
    license_id: licenseId,
    key_id: keyId,
    customer,
    issued_at: issuedAt,
    expires_at: expiresAt,
    bundle: premiumActive ? "premium" : "free",
    bundle_version: 1,
    runtime_mode: runtimeMode,
    legacy_dashboard_applicable: legacyDashboardApplicable,
    multi_pack_premium_available: multiPackPremiumAvailable,
    features: premiumFeatures,
    license_features: licenseFeatures
};

global.set("premium", premiumState);

node.warn("JK PREMIUM STATE SPV2 -> " + JSON.stringify({
    install_id: premiumState.install_id,
    active: premiumState.active,
    status: premiumState.status,
    validation_status: premiumState.validation_status,
    tier: premiumState.tier,
//    license_id: premiumState.license_id,
    key_id: premiumState.key_id,
    bundle: premiumState.bundle,
    runtime_mode: premiumState.runtime_mode,
    legacy_dashboard_applicable: premiumState.legacy_dashboard_applicable,
    multi_pack_premium_available: premiumState.multi_pack_premium_available,
    features: premiumState.features
}));

if (premiumActive) {
    node.status({
        fill: "green",
        shape: "dot",
        text: "premium valid SPV2"
    });
} else {
    node.status({
        fill: premiumStatus === "missing_key" ? "grey" : "yellow",
        shape: "ring",
        text: premiumStatus
    });
}

msg.payload = { premium: premiumState };
return msg;

// TCP/Gateway mode: keep the shared serial configuration stopped.
msg.payload = { enabled: false };
return msg;

// =========== BMS DATA PROCESSING - STABLE HA DISCOVERY VERSION ===========

// 0. Récupération adresse BMS et conversion en "master" si nécessaire
let bmsAdresse = msg.bms_numero;
let slaveIdStr;

if (typeof bmsAdresse === "string" && bmsAdresse.toLowerCase() === "master") {
    slaveIdStr = "master";
} else if (!isNaN(Number(bmsAdresse))) {
    if (Number(bmsAdresse) === 0) {
        slaveIdStr = (global.get("multi_pack_enabled") === true && global.get("jkbms_active_polling_enabled") === true) ? "0" : "master";
    } else {
        slaveIdStr = String(Number(bmsAdresse));
    }
} else {
    slaveIdStr = "master";
}

var payload = msg.payload || {};

// ------------------------------------------------------------------
// MQTT / HA identity : legacy strict ou Multi-Pack.
const multiPack = global.get("multi_pack_enabled") === true;
const packId = msg.pack_id || "pack_1";
const packName = msg.pack_name || "Pack 1";
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");

var baseTopic = multiPack
    ? `jkbms/${packId}/BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

var sensorDiscoveryPrefix = "homeassistant/sensor";
var binaryDiscoveryPrefix = "homeassistant/binary_sensor";

var deviceName = multiPack
    ? `${packName} - BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

var deviceID = multiPack
    ? `${packSafe}_BMS_${slaveIdStr}_device`
    : `BMS_${slaveIdStr}_device`;

// Legacy historique : bms_2_bms_<entity>
// Multi-Pack : pack_1_bms_2_<entity>
var entityPrefix = multiPack
    ? `${packSafe}_bms_${slaveIdStr}`
    : `${baseTopic.toLowerCase()}_bms`;

var topics = {};
var discoveryMsgs = [];

const discoveryKey = multiPack
    ? `discoverySent_BMS_${packId}_${slaveIdStr}`
    : `discoverySent_BMS_${slaveIdStr}`;

// v4.2.48 - Discovery schema revision.
// Forces one complete DATA rediscovery once after this upgrade so Home Assistant
// receives the new display recommendation for Courant_total_A.
// Raw/internal current remains unchanged at full precision.
const DISCOVERY_SCHEMA_REV = 2;
const discoverySchemaKey = multiPack
    ? `discoverySchemaRev_BMS_${packId}_${slaveIdStr}`
    : `discoverySchemaRev_BMS_${slaveIdStr}`;
const discoverySchemaCurrent = Number(flow.get(discoverySchemaKey)) || 0;
let discoveryAlreadySent =
    (flow.get(discoveryKey) || false) &&
    discoverySchemaCurrent >= DISCOVERY_SCHEMA_REV;

const discoveredKeysStore = multiPack
    ? `discoveredKeys_BMS_${packId}_${slaveIdStr}`
    : `discoveredKeys_BMS_${slaveIdStr}`;

let previousDiscoveredKeys = flow.get(discoveredKeysStore) || [];

// ------------------------------------------------------------------
// 1. Traitement des tensions de cellules
const cellCountKey = multiPack
    ? `jk_cell_count_${packId}_BMS_${slaveIdStr}`
    : `jk_cell_count_BMS_${slaveIdStr}`;

let cellCount = Number(flow.get(cellCountKey)) || 16;
cellCount = Math.max(1, Math.min(cellCount, 16));
payload["cell_count_used_N"] = cellCount;

var cellVoltages = [];
var cellKeys = [];

for (let i = 1; i <= cellCount; i++) {
    let key = `Cell_${i}_volt_V`;
    let voltage = Number(payload[key]);
    if (Number.isFinite(voltage) && voltage > 0) {
        cellVoltages.push(voltage);
        cellKeys.push(key);
    }
}

if (cellVoltages.length > 0) {
    var cellAvgVolt = cellVoltages.reduce((sum, v) => sum + v, 0) / cellVoltages.length;
    var cellMaxVolt = Math.max(...cellVoltages);
    var cellMinVolt = Math.min(...cellVoltages);
    var cellDeltaVolt = cellMaxVolt - cellMinVolt;

    var maxVoltIndex = cellKeys[cellVoltages.indexOf(cellMaxVolt)].match(/Cell_(\d+)/)[1];
    var minVoltIndex = cellKeys[cellVoltages.indexOf(cellMinVolt)].match(/Cell_(\d+)/)[1];

    payload["cell_voltage_average_V"]    = parseFloat(cellAvgVolt.toFixed(3));
    payload["cell_voltage_delta_V"]      = parseFloat(cellDeltaVolt.toFixed(3));
    payload["cell_voltage_max_number_N"] = parseInt(maxVoltIndex);
    payload["cell_voltage_min_number_N"] = parseInt(minVoltIndex);
    payload["cell_voltage_min_value_V"]  = parseFloat(cellMinVolt.toFixed(3));
    payload["cell_voltage_max_value_V"]  = parseFloat(cellMaxVolt.toFixed(3));
} else {
    payload["cell_voltage_average_V"]    = 0;
    payload["cell_voltage_delta_V"]      = 0;
    payload["cell_voltage_max_number_N"] = 0;
    payload["cell_voltage_min_number_N"] = 0;
    payload["cell_voltage_min_value_V"]  = 0;
    payload["cell_voltage_max_value_V"]  = 0;
}

// ------------------------------------------------------------------
// 2. Formatage de Total_runtime_S
if (payload["Total_runtime_S"] !== undefined) {
    var totalSeconds = parseInt(payload["Total_runtime_S"]);
    if (!isNaN(totalSeconds)) {
        var days = Math.floor(totalSeconds / 86400);
        var remainingSeconds = totalSeconds % 86400;
        var hours = Math.floor(remainingSeconds / 3600);
        var minutes = Math.floor((remainingSeconds % 3600) / 60);
        payload["Total_runtime_formatted_T"] = `${days}D${hours}H${minutes}M`;
    }
}

// ------------------------------------------------------------------
// 3. charge_status_N → texte lisible
if (payload["charge_status_N"] !== undefined) {
    var v = parseInt(payload["charge_status_N"]);
    var txt = "Unknown";
    switch (v) {
        case 0:
        case 0x00:
            txt = "Bulk";
            break;
        case 1:
        case 0x01:
            txt = "Absorption";
            break;
        case 2:
        case 0x02:
            txt = "Float";
            break;
    }
    payload["charge_status_text_S"] = txt;
}

// ------------------------------------------------------------------
// 4. Formatage charge_status_time_S
if (payload["charge_status_time_S"] !== undefined) {
    var s = parseInt(payload["charge_status_time_S"]);
    if (!isNaN(s)) {
        var days = Math.floor(s / 86400);
        var rem = s % 86400;
        var hours = Math.floor(rem / 3600);
        var minutes = Math.floor((rem % 3600) / 60);
        var seconds = rem % 60;

        if (days > 0)
            payload["charge_status_time_formatted_T"] = `${days}D${hours}H${minutes}M`;
        else if (hours > 0)
            payload["charge_status_time_formatted_T"] = `${hours}H${minutes}M${seconds}S`;
        else if (minutes > 0)
            payload["charge_status_time_formatted_T"] = `${minutes}M${seconds}S`;
        else
            payload["charge_status_time_formatted_T"] = `${seconds}S`;
    }
}

// ------------------------------------------------------------------
// 5. Formatage Heating_B
if (payload["Heating_B"] !== undefined) {
    var heatingStatus = parseInt(payload["Heating_B"]);
    var heatingTxt = heatingStatus === 1 ? "ON" : "OFF";
    payload["Heating_status_text_S"] = heatingTxt;
}

// ------------------------------------------------------------------
// DEV64 - DRY1 / DRY2 read-only live state.
// Real JK-PB validation (2026-10-05): byte 281 bitmask
//   0x02 = DRY1 active, 0x04 = DRY2 active, 0x06 = both active.
// These are state bits only; they are never written by this flow.
if (payload["Dry_status_N"] !== undefined) {
    const dryStatus = Number(payload["Dry_status_N"]) & 0xFF;
    payload["dry_contact_1_B"] = (dryStatus & 0x02) !== 0 ? 1 : 0;
    payload["dry_contact_2_B"] = (dryStatus & 0x04) !== 0 ? 1 : 0;
    delete payload["Dry_status_N"];
}

// ------------------------------------------------------------------
// 6. Préparation topics + clés discovery
const allowedSuffixes = ["_V", "_A", "_W", "_T", "_Ah", "_R", "_P", "_S", "_B", "_N"];
let currentDiscoveredKeys = [];

for (var key in payload) {
    var hasValidSuffix = allowedSuffixes.some(s => key.endsWith(s));
    if (!hasValidSuffix) continue;

    var cleanKey = key.replace(/_[A-Z]+$/, "");
    currentDiscoveredKeys.push(cleanKey);

    var sensorTopic = `${baseTopic}/${cleanKey}`;
    topics[sensorTopic] = payload[key];
}

// Republie le discovery si nouvelles clés
let newKeys = currentDiscoveredKeys.filter(k => !previousDiscoveredKeys.includes(k));
let shouldSendDiscovery = !discoveryAlreadySent || newKeys.length > 0;

// ------------------------------------------------------------------
// 7. Génération discovery
for (var key in payload) {
    var hasValidSuffix = allowedSuffixes.some(s => key.endsWith(s));
    if (!hasValidSuffix) continue;

    var cleanKey = key.replace(/_[A-Z]+$/, "");
    var sensorTopic = `${baseTopic}/${cleanKey}`;

    if (!shouldSendDiscovery) continue;
    if (discoveryAlreadySent && !newKeys.includes(cleanKey)) continue;

    // Booléens -> binary_sensor
    if (key.endsWith("_B")) {
        var binaryConfigTopic = `${binaryDiscoveryPrefix}/${deviceID}_${cleanKey}/config`;

        var binaryConfigPayload = {
            name: cleanKey,
            unique_id: `${deviceID}_bms_${cleanKey}_v4`,
            state_topic: sensorTopic,
            payload_on: "1",
            payload_off: "0",
            device: {
                identifiers: [deviceID],
                name: deviceName,
                manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026",
                model: "JK-BMS - RS485",
                sw_version: "3.5"
            },
            icon: "mdi:toggle-switch"
        };

        if (key === "Heating_B") {
            binaryConfigPayload.icon = "mdi:heating-coil";
        } else if (key === "Switch_Charge_B") {
            binaryConfigPayload.icon = "mdi:battery-charging";
        } else if (key === "Switch_Decharge_B") {
            binaryConfigPayload.icon = "mdi:battery-minus";
        } else if (key === "Balance_Action_B" || key === "Switch_Balance_B") {
            binaryConfigPayload.icon = "mdi:battery-sync";
        } else if (key === "dry_contact_1_B") {
            binaryConfigPayload.name = "Dry Contact 1";
            binaryConfigPayload.icon = "mdi:electric-switch";
        } else if (key === "dry_contact_2_B") {
            binaryConfigPayload.name = "Dry Contact 2";
            binaryConfigPayload.icon = "mdi:electric-switch";
        }

        // Force l'entity_id HA stable pour les binary_sensor data broadcasting
        binaryConfigPayload.object_id = `${entityPrefix}_${cleanKey}`;
        binaryConfigPayload.default_entity_id = `binary_sensor.${binaryConfigPayload.object_id}`;

        discoveryMsgs.push({
            topic: `${binaryDiscoveryPrefix}/${binaryConfigPayload.object_id}/config`,
            payload: JSON.stringify(binaryConfigPayload),
            retain: true
        });

        continue;
    }

    // Capteurs standards
    var configTopic = `${sensorDiscoveryPrefix}/${deviceID}_${cleanKey}/config`;

    var configPayload = {
        name: cleanKey,
        unique_id: `${deviceID}_bms_${cleanKey}_v4`,
        state_topic: sensorTopic,
        unit_of_measurement: "",
        entity_category: "diagnostic",
        device: {
            identifiers: [deviceID],
            name: deviceName,
            manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026",
            model: "JK-BMS - RS485",
            sw_version: "3.5"
        }
    };

    if (key.endsWith("_V")) {
        configPayload.unit_of_measurement = "V";
        configPayload.device_class = "voltage";

        if (
            /^Cell_\d+_volt_V$/.test(key) ||
            key === "cell_voltage_average_V" ||
            key === "cell_voltage_delta_V" ||
            key === "cell_voltage_min_value_V" ||
            key === "cell_voltage_max_value_V"
        ) {
            configPayload.suggested_display_precision = 3;
        } else {
            configPayload.suggested_display_precision = 2;
        }
    }
    else if (key.endsWith("_Ah")) {
        configPayload.unit_of_measurement = "Ah";
    }
    else if (key.endsWith("_A")) {
        configPayload.unit_of_measurement = "A";
        configPayload.device_class = "current";
        configPayload.suggested_display_precision = key === "Courant_total_A" ? 1 : 3;
    }
    else if (key.endsWith("_W")) {
        configPayload.unit_of_measurement = "W";
        configPayload.device_class = "power";
        configPayload.suggested_display_precision = 0;
    }
    else if (key.endsWith("_R")) {
        configPayload.unit_of_measurement = "Ω";
        configPayload.suggested_display_precision = 3;
    }
    else if (key.endsWith("_P")) {
        configPayload.unit_of_measurement = "%";
        configPayload.suggested_display_precision = 0;

        if (key.startsWith("SOC") || key.startsWith("SOH")) {
            configPayload.device_class = "battery";
        }
    }
    else if (key.endsWith("_T")) {
        if (key === "Total_runtime_formatted_T" || key === "charge_status_time_formatted_T") {
            configPayload.unit_of_measurement = "";
            configPayload.icon = "mdi:clock-time-eight-outline";
            delete configPayload.device_class;
        } else {
            configPayload.unit_of_measurement = "°C";
            configPayload.device_class = "temperature";
            configPayload.suggested_display_precision = 1;
        }
    }
    else if (key.endsWith("_S")) {
        configPayload.unit_of_measurement = "";
        delete configPayload.device_class;

        if (key === "charge_status_text_S") {
            configPayload.icon = "mdi:battery-charging";
        } else if (key === "Heating_status_text_S") {
            configPayload.icon = "mdi:heating-coil";
        } else {
            configPayload.icon = "mdi:text";
        }
    }
    else if (key.endsWith("_N")) {
        // IMPORTANT : index → pas une mesure
        delete configPayload.unit_of_measurement;
        delete configPayload.device_class;

        configPayload.icon = "mdi:counter";
    }

    // Force l'entity_id HA stable pour les sensor data broadcasting
    configPayload.object_id = `${entityPrefix}_${cleanKey}`;
    configPayload.default_entity_id = `sensor.${configPayload.object_id}`;

    discoveryMsgs.push({
        topic: `${sensorDiscoveryPrefix}/${configPayload.object_id}/config`,
        payload: JSON.stringify(configPayload),
        retain: true
    });
}

// ------------------------------------------------------------------
// 8. Sortie + protection Recorder (change-only)
//
// En Multi-Pack broadcasting uniquement :
// - première valeur -> publiée
// - valeur strictement identique -> supprimée
// - valeur différente -> publiée immédiatement
// - lors d'un Discovery (re)publié, tous les états courants sont forcés une fois
//
// Les governors Recorder Multi-Pack sont appliqués plus bas de façon ciblée.
// Le mode Legacy reste strictement inchangé.
var outputMsgs = [];

if (shouldSendDiscovery) {
    outputMsgs = discoveryMsgs;
    flow.set(discoveryKey, true);
    flow.set(discoverySchemaKey, DISCOVERY_SCHEMA_REV);
    flow.set(discoveredKeysStore, currentDiscoveredKeys);

    if (!discoveryAlreadySent) {
        node.warn(`✓ Discovery envoyé pour BMS ${slaveIdStr} (${discoveryMsgs.length} sensors)`);
    } else {
        node.warn(`✓ Discovery complémentaire envoyé pour BMS ${slaveIdStr} (${discoveryMsgs.length} new sensors)`);
    }
} else {
    node.debug(`Discovery déjà envoyé pour BMS ${slaveIdStr}`);
}

const changeOnlyEnabled =
    multiPack &&
    global.get("bms_broadcasting") === true;

const lastPublishedKey =
    `mqtt_last_data_${packId}_BMS_${slaveIdStr}`;

let lastPublished = changeOnlyEnabled
    ? (flow.get(lastPublishedKey) || {})
    : {};

const publishStatsKey = `mqtt_data_stats_${packId}`;
let publishStats = flow.get(publishStatsKey) || {
    candidates_30s: 0,
    published_30s: 0,
    suppressed_30s: 0,
    throttled_30s: 0,
    deadband_held_30s: 0,
    deadband_published_30s: 0,
    midband_held_30s: 0,
    midband_published_30s: 0,
    forced_30s: 0,
    candidates_total: 0,
    published_total: 0,
    suppressed_total: 0,
    throttled_total: 0,
    deadband_held_total: 0,
    deadband_published_total: 0,
    midband_held_total: 0,
    midband_published_total: 0,
    forced_total: 0
};

// Step 12F: les profils détaillés 30 s sont retirés du chemin production.
// Les compteurs compacts restent disponibles dans JKBMS Health.
// L'observateur brut 15 min reste séparé sur MQTT retained, hors HA Discovery.

function mqttComparableValue(value) {
    if (value === null) return "null";

    if (Buffer.isBuffer(value)) {
        return `buffer:${value.toString("hex")}`;
    }

    if (typeof value === "object") {
        try {
            return `json:${JSON.stringify(value)}`;
        } catch (e) {
            return `object:${String(value)}`;
        }
    }

    // MQTT transporte finalement une représentation scalaire.
    // String() évite de republier inutilement 1 puis "1".
    return `scalar:${String(value)}`;
}

function metricNameFromTopic(topic) {
    const parts = String(topic || "").split("/").filter(Boolean);
    return parts.length ? parts[parts.length - 1] : String(topic || "");
}


// ------------------------------------------------------------------
// Step 12B - governor temporel ciblé
// Step 12D - targeted Recorder tuning based on real 15-minute observations.
// charge_status_time is a running counter, not an event. Publishing it every
// broadcast frame gives Recorder almost no additional operational value.
const temporalGovernorIntervalsMs = {
    // Step 13I-C4 : runtime brut + formate, au plus toutes les 5 minutes.
    "Total_runtime": 300000,
    "Total_runtime_formatted": 300000,

    // Cycle_Capacite_Ah est gere par le governor adaptatif Step 13I-C4.
    // Capacite_restante_Ah est geree par le governor adaptatif Step 13I-C2.
    "charge_status_time": 30000,
    "charge_status_time_formatted": 30000
};

const lastPublishTsKey =
    `mqtt_last_publish_ts_${packId}_BMS_${slaveIdStr}`;

let lastPublishTs = changeOnlyEnabled
    ? (flow.get(lastPublishTsKey) || {})
    : {};

function temporalIntervalMsForTopic(topic) {
    const metric = metricNameFromTopic(topic);

    // Step 13I-C4 : les numeros de cellule min/max n'ont pas besoin de suivre
    // chaque permutation entre deux cellules quasi identiques. En regime
    // normal on les limite a 120 s. Si le delta cellules devient >= 50 mV,
    // on repasse automatiquement a 30 s pour conserver un suivi diagnostique
    // plus fin sans rendre l'index lui-meme temps reel.
    if (
        metric === "cell_voltage_min_number" ||
        metric === "cell_voltage_max_number"
    ) {
        const cellDelta = Number(payload["cell_voltage_delta_V"]);
        return Number.isFinite(cellDelta) && cellDelta >= 0.050
            ? 30000
            : 120000;
    }

    return Number(temporalGovernorIntervalsMs[metric] || 0);
}

function temporalCanPublish(topic, nowMs, forcePublish) {
    if (forcePublish) return true;

    const intervalMs = temporalIntervalMsForTopic(topic);
    if (intervalMs <= 0) return true;

    const previousTs = Number(lastPublishTs[topic] || 0);
    if (previousTs <= 0) return true;

    return (nowMs - previousTs) >= intervalMs;
}

// ------------------------------------------------------------------
// Step 13I-C1 - governor adaptatif Courant / Puissance
//
// Objectif : réduire les écritures Recorder des deux mesures les plus
// dynamiques sans masquer les transitions réellement utiles.
//
// Courant_total :
//   - petite variation       -> au plus toutes les 10 s
//   - démarrage / arrêt      -> immédiat (seuil 0,10 A)
//   - changement de signe   -> immédiat
//   - variation importante  -> immédiat : >= max(1 A, 5 % de la valeur publiée)
//
// Puissance_Totale :
//   - petite variation       -> au plus toutes les 15 s
//   - démarrage / arrêt      -> immédiat (seuil 10 W)
//   - variation importante  -> immédiat : >= max(100 W, 5 % de la valeur publiée)
//
// La comparaison se fait toujours avec la DERNIERE VALEUR REELLEMENT
// publiée. L'observateur analogique brut 15 min est alimenté AVANT ce filtre.
const electricalGovernorPolicies = {
    "Courant_total": {
        min_interval_ms: 10000,
        active_threshold: 0.10,
        immediate_abs_delta: 1.0,
        immediate_relative: 0.05,
        sign_change: true
    },
    "Puissance_Totale": {
        min_interval_ms: 15000,
        active_threshold: 10.0,
        immediate_abs_delta: 100.0,
        immediate_relative: 0.05,
        sign_change: true
    }
};

function electricalGovernorDecision(topic, value, nowMs, forcePublish) {
    const metric = metricNameFromTopic(topic);
    const policy = electricalGovernorPolicies[metric];

    if (!policy) {
        return { governed: false, allow: true, reason: "not_governed" };
    }

    if (forcePublish) {
        return { governed: true, allow: true, reason: "forced" };
    }

    const current = Number(value);
    const previous = Number(lastPublishedNumeric[topic]);

    if (!Number.isFinite(current)) {
        return { governed: true, allow: true, reason: "non_numeric_fallback" };
    }

    if (!Number.isFinite(previous)) {
        return { governed: true, allow: true, reason: "first_value" };
    }

    const previousTs = Number(lastPublishTs[topic] || 0);
    const elapsedMs = previousTs > 0
        ? (nowMs - previousTs)
        : Number.POSITIVE_INFINITY;

    const absCurrent = Math.abs(current);
    const absPrevious = Math.abs(previous);
    const absDelta = Math.abs(current - previous);
    const activeThreshold = Number(policy.active_threshold || 0);

    const wasActive = absPrevious >= activeThreshold;
    const isActive = absCurrent >= activeThreshold;

    // Passage repos <-> activité : ne jamais attendre le timer.
    if (wasActive !== isActive) {
        return {
            governed: true,
            allow: true,
            reason: "activity_transition",
            abs_delta: absDelta
        };
    }

    // Changement charge <-> décharge. On exige que les deux valeurs soient
    // significativement hors de la zone zéro pour éviter les oscillations.
    if (policy.sign_change === true && wasActive && isActive) {
        const signChanged =
            (previous > 0 && current < 0) ||
            (previous < 0 && current > 0);

        if (signChanged) {
            return {
                governed: true,
                allow: true,
                reason: "sign_change",
                abs_delta: absDelta
            };
        }
    }

    // Une variation réellement importante reste instantanée. Le seuil
    // relatif croît avec la puissance / le courant réellement publié.
    const immediateThreshold = Math.max(
        Number(policy.immediate_abs_delta || 0),
        absPrevious * Number(policy.immediate_relative || 0)
    );

    if (absDelta + 1e-12 >= immediateThreshold) {
        return {
            governed: true,
            allow: true,
            reason: "immediate_delta",
            abs_delta: absDelta,
            threshold: immediateThreshold
        };
    }

    if (elapsedMs >= Number(policy.min_interval_ms || 0)) {
        return {
            governed: true,
            allow: true,
            reason: "interval_elapsed",
            abs_delta: absDelta
        };
    }

    return {
        governed: true,
        allow: false,
        reason: "small_change_throttled",
        abs_delta: absDelta,
        threshold: immediateThreshold
    };
}

// ------------------------------------------------------------------
// Step 13I-C2 - governor adaptatif mesures derivees / pack
//
// Capacite_restante_Ah :
//   - petite variation      -> au plus toutes les 60 s
//   - variation >= 1 Ah     -> immediate
//
// Tension_Totale_volt :
