// ------------------------------------------------------------------
// Step 12C / 12D / 12E + Step 13I-C3 - governor hybride tensions cellules
//
// Step 13I-C3 ne modifie QUE Cell_1_volt ... Cell_16_volt et adapte leur
// cadence a l'activite de balancing REELLE du BMS.
//
// Balancing INACTIF :
//   delta < 2 mV       -> retenu, refresh au plus toutes les 60 s
//   2 mV <= delta < 10 mV -> au plus une publication toutes les 60 s
//   delta >= 10 mV     -> publication immediate
//
// Balancing ACTIF :
//   delta < 2 mV       -> retenu, refresh au plus toutes les 30 s
//   2 mV <= delta < 5 mV -> au plus une publication toutes les 15 s
//   delta >= 5 mV      -> publication immediate
//
// Le balancing est considere actif si Balance_Action_B est vrai/1 OU si
// abs(Balance_courant_A) > 0,001 A. Ceci reprend la logique validee dans
// Step 13H et evite de dependre du seul bit Balance_Action_B.
//
// Les politiques cell_voltage_average, min/max et delta restent celles deja
// validees. La comparaison se fait toujours avec la DERNIERE VALEUR
// REELLEMENT PUBLIEE : un mouvement retenu qui s'accumule peut donc devenir
// immediat des qu'il franchit le seuil correspondant.
const cellVoltageDeadbandV = 0.002;
const cellVoltageImmediateV = 0.005;
const cellVoltageMidbandMinIntervalMs = 5000;

function isCurrentBmsBalancingActive() {
    const action = payload["Balance_Action_B"];
    const actionActive =
        action === true ||
        action === 1 ||
        String(action).toLowerCase() === "true" ||
        String(action) === "1";

    const balanceCurrent = Number(payload["Balance_courant_A"]);
    const currentActive =
        Number.isFinite(balanceCurrent) &&
        Math.abs(balanceCurrent) > 0.001;

    return actionActive || currentActive;
}

function cellVoltagePolicyForMetric(metric) {
    if (/^Cell_(?:[1-9]|1[0-6])_volt$/.test(metric)) {
        if (isCurrentBmsBalancingActive()) {
            return {
                deadband_v: 0.002,
                immediate_v: 0.005,
                midband_min_interval_ms: 15000,
                max_interval_ms: 30000,
                c3_balancing_active: true
            };
        }

        return {
            deadband_v: 0.002,
            immediate_v: 0.010,
            midband_min_interval_ms: 60000,
            max_interval_ms: 60000,
            c3_balancing_active: false
        };
    }

    if (metric === "cell_voltage_average") {
        // Step 13I-C4 : moyenne cellule, refresh normal 60 s mais toute
        // variation >= 5 mV reste immediate. Les variations plus faibles
        // s'accumulent par rapport a la derniere valeur reellement publiee.
        return {
            deadband_v: 0.005,
            immediate_v: 0.005,
            midband_min_interval_ms: 60000,
            max_interval_ms: 60000
        };
    }

    if (
        metric === "cell_voltage_min_value" ||
        metric === "cell_voltage_max_value"
    ) {
        // Step 13I-C2 : rafraichissement normal 30 s, mais >= 5 mV immediat.
        return {
            deadband_v: 0.005,
            immediate_v: 0.005,
            midband_min_interval_ms: 30000,
            max_interval_ms: 30000
        };
    }

    if (metric === "cell_voltage_delta") {
        // Step 13I-C2 : rafraichissement normal 30 s, variation >= 5 mV
        // immediate, ainsi que franchissement de seuils diagnostiques utiles.
        return {
            deadband_v: 0.005,
            immediate_v: 0.005,
            midband_min_interval_ms: 30000,
            max_interval_ms: 30000,
            threshold_crossings_v: [0.010, 0.020, 0.050, 0.100]
        };
    }

    return null;
}

const lastPublishedNumericKey =
    `mqtt_last_numeric_${packId}_BMS_${slaveIdStr}`;

let lastPublishedNumeric = changeOnlyEnabled
    ? (flow.get(lastPublishedNumericKey) || {})
    : {};

function cellVoltageDecision(topic, value, nowMs, forcePublish) {
    const metric = metricNameFromTopic(topic);
    const policy = cellVoltagePolicyForMetric(metric);

    if (!policy) {
        return {
            governed: false,
            allow: true,
            reason: "not_cell_voltage"
        };
    }

    // Discovery : published value must also seed the numeric reference.
    if (forcePublish) {
        return {
            governed: true,
            allow: true,
            reason: "forced"
        };
    }

    const current = Number(value);
    const previous = Number(lastPublishedNumeric[topic]);

    if (!Number.isFinite(current)) {
        return {
            governed: true,
            allow: true,
            reason: "non_numeric_fallback"
        };
    }

    if (!Number.isFinite(previous)) {
        return {
            governed: true,
            allow: true,
            reason: "first_value"
        };
    }

    const delta = Math.abs(current - previous);
    const previousTs = Number(lastPublishTs[topic] || 0);
    const elapsedMs = previousTs > 0
        ? (nowMs - previousTs)
        : Number.POSITIVE_INFINITY;

    // Step 13I-C2 : pour le delta cellules, publier immediatement lorsqu'un
    // seuil diagnostique significatif est franchi dans un sens ou l'autre,
    // meme si la variation instantanee reste inferieure a 5 mV.
    if (Array.isArray(policy.threshold_crossings_v)) {
        for (const threshold of policy.threshold_crossings_v) {
            const crossedUp = previous < threshold && current >= threshold;
            const crossedDown = previous >= threshold && current < threshold;

            if (crossedUp || crossedDown) {
                return {
                    governed: true,
                    allow: true,
                    reason: "threshold_crossing",
                    delta_v: delta,
                    threshold_v: threshold
                };
            }
        }
    }

    // Niveau 3 : changement réellement important -> immediat selon policy.
    if (delta + 1e-12 >= policy.immediate_v) {
        return {
            governed: true,
            allow: true,
            reason: "immediate_threshold",
            delta_v: delta
        };
    }

    // Niveau 2 : entre deadband et seuil immediat -> limiter la cadence.
    if (delta + 1e-12 >= policy.deadband_v) {
        if (elapsedMs >= policy.midband_min_interval_ms) {
            return {
                governed: true,
                allow: true,
                reason: "midband_interval",
                delta_v: delta
            };
        }

        return {
            governed: true,
            allow: false,
            reason: "midband_throttled",
            delta_v: delta
        };
    }

    // Niveau 1 : sous deadband -> bruit/faible mouvement, refresh periodique.
    if (
        previousTs > 0 &&
        elapsedMs >= policy.max_interval_ms
    ) {
        return {
            governed: true,
            allow: true,
            reason: "max_interval",
            delta_v: delta
        };
    }

    return {
        governed: true,
        allow: false,
        reason: "inside_deadband",
        delta_v: delta
    };
}

// ------------------------------------------------------------------
// Step 12F - observateur analogique BRUT 15 minutes, avant filtres MQTT
//
// Les profils détaillés 30 s ont été retirés de JKBMS Health et ne sont plus
// calculés en production. L'observateur 15 min reste disponible pour les
// diagnostics profonds : son rapport détaillé est publié sur un topic MQTT
// retained NON découvert par Home Assistant.
//
// IMPORTANT : aucune décision de publication DATA n'est prise ici.
const analogRawLastKey =
    `mqtt_analog_raw_last_${packId}_BMS_${slaveIdStr}`;

let analogRawLast = changeOnlyEnabled
    ? (flow.get(analogRawLastKey) || {})
    : {};

const rawObserver15mKey = `mqtt_raw_observer_15m_${packId}`;
const RAW_OBSERVER_WINDOW_MS = 15 * 60 * 1000;

let rawObserver15m = changeOnlyEnabled
    ? (flow.get(rawObserver15mKey) || {})
    : {};

function freshRawObserverWindow(startTs) {
    return {
        window_start_ts: startTs,
        metrics: {},
        bms_seen: {},
        last_complete_ts: null,
        last_complete_start_ts: null,
        last_complete_end_ts: null,
        last_complete_bms_seen: []
    };
}

if (changeOnlyEnabled) {
    if (!Number(rawObserver15m.window_start_ts)) {
        rawObserver15m = freshRawObserverWindow(Date.now());
    }
    if (!rawObserver15m.metrics || typeof rawObserver15m.metrics !== "object") {
        rawObserver15m.metrics = {};
    }
    if (!rawObserver15m.bms_seen || typeof rawObserver15m.bms_seen !== "object") {
        rawObserver15m.bms_seen = {};
    }
}

function analogProfileMetric(metric) {
    // Toutes les cellules sont agrégées dans une seule distribution afin de
    // mesurer le bruit mV sans multiplier la taille des diagnostics par 16.
    if (/^Cell_(?:[1-9]|1[0-6])_volt$/.test(metric)) {
        return "Cell_voltage_all";
    }
    return metric;
}

function analogProfileDefinition(metric) {
    if (metric === "Puissance_Totale") {
        return {
            unit: "W",
            bounds: [1, 5, 10, 25, 50, 100, 250, 500, 1000]
        };
    }

    if (metric === "Courant_total" || metric === "Balance_courant") {
        return {
            unit: "A",
            bounds: [0.01, 0.05, 0.10, 0.25, 0.50, 1.0, 2.0, 5.0]
        };
    }

    if (metric === "Tension_Totale_volt") {
        return {
            unit: "V",
            bounds: [0.01, 0.02, 0.05, 0.10, 0.20, 0.50, 1.0]
        };
    }

    if (
        metric === "Cell_voltage_all" ||
        metric === "cell_voltage_average" ||
        metric === "cell_voltage_delta" ||
        metric === "cell_voltage_min_value" ||
        metric === "cell_voltage_max_value"
    ) {
        return {
            unit: "V",
            // Seuils explicitement centrés sur la question du deadband 2 mV.
            bounds: [0.001, 0.002, 0.003, 0.005, 0.010, 0.020, 0.050]
        };
    }

    if (
        metric === "Mos_temp" ||
        /^Sonde_\d+_temp$/.test(metric)
    ) {
        return {
            unit: "°C",
            bounds: [0.1, 0.2, 0.5, 1.0, 2.0, 5.0]
        };
    }

    return null;
}

function ensureRawMetricProfile(container, metric, definition) {
    if (!container[metric]) {
        container[metric] = {
            unit: definition.unit,
            pairs: 0,
            unchanged: 0,
            changed: 0,
            sum_abs_delta: 0,
            max_abs_delta: 0,
            bins: new Array(definition.bounds.length + 1).fill(0)
        };
    }
    return container[metric];
}

function updateRawMetricProfile(profile, definition, absDelta) {
    profile.pairs += 1;

    if (absDelta <= 1e-12) {
        profile.unchanged += 1;
        return;
    }

    profile.changed += 1;
    profile.sum_abs_delta += absDelta;

    if (absDelta > profile.max_abs_delta) {
        profile.max_abs_delta = absDelta;
    }

    let binIndex = definition.bounds.length;
    for (let i = 0; i < definition.bounds.length; i++) {
        if (absDelta <= definition.bounds[i] + 1e-12) {
            binIndex = i;
            break;
        }
    }
    profile.bins[binIndex] += 1;
}

function buildRawObserverReport(raw, startTs, endTs, bmsSeen) {
    const result = {};

    for (const [metric, profile] of Object.entries(raw || {})) {
        const definition = analogProfileDefinition(metric);
        if (!definition) continue;

        const pairs = Number(profile.pairs || 0);
        const unchanged = Number(profile.unchanged || 0);
        const changed = Number(profile.changed || 0);
        const rawBins = Array.isArray(profile.bins) ? profile.bins : [];
        const bins = [];

        for (let i = 0; i < definition.bounds.length; i++) {
            const count = Number(rawBins[i] || 0);
            bins.push({
                le: definition.bounds[i],
                count,
                share_of_changes: changed > 0
                    ? Number((count / changed).toFixed(4))
                    : 0
            });
        }

        const gtCount = Number(rawBins[definition.bounds.length] || 0);
        bins.push({
            gt: definition.bounds[definition.bounds.length - 1],
            count: gtCount,
            share_of_changes: changed > 0
                ? Number((gtCount / changed).toFixed(4))
                : 0
        });

        result[metric] = {
            unit: profile.unit || definition.unit,
            pairs,
            unchanged,
            changed,
            changed_share: pairs > 0
                ? Number((changed / pairs).toFixed(4))
                : 0,
            mean_abs_delta_changed: changed > 0
                ? Number((Number(profile.sum_abs_delta || 0) / changed).toFixed(6))
                : 0,
            max_abs_delta: Number(Number(profile.max_abs_delta || 0).toFixed(6)),
            bins
        };
    }

    return {
        step: "12F",
        profile_basis: "consecutive_raw_data_values_before_mqtt_filters",
        window_s: Number(((endTs - startTs) / 1000).toFixed(1)),
        window_start_ts: startTs,
        window_end_ts: endTs,
        pack_id: packId,
        pack_name: packName,
        bms_seen: Object.keys(bmsSeen || {}).sort((a, b) => {
            if (a === "master") return -1;
            if (b === "master") return 1;
            return Number(a) - Number(b);
        }),
        metrics: result
    };
}

function rollRawObserverIfNeeded(nowMs) {
    if (!changeOnlyEnabled) return;

    const startTs = Number(rawObserver15m.window_start_ts || nowMs);
    if ((nowMs - startTs) < RAW_OBSERVER_WINDOW_MS) return;

    const report = buildRawObserverReport(
        rawObserver15m.metrics || {},
        startTs,
        nowMs,
        rawObserver15m.bms_seen || {}
    );

    // Topic volontairement hors Home Assistant Discovery / Recorder.
    outputMsgs.push({
        topic: `jkbms/${packId}/diagnostics/raw_observer_15m`,
        payload: JSON.stringify(report),
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: msg.bus_id || "bus_1"
    });

    rawObserver15m = {
        window_start_ts: nowMs,
        metrics: {},
        bms_seen: {},
        last_complete_ts: nowMs,
        last_complete_start_ts: startTs,
        last_complete_end_ts: nowMs,
        last_complete_bms_seen: report.bms_seen
    };
}

function profileAnalogRawCandidate(topic, value) {
    if (!changeOnlyEnabled) return;

    const metric = metricNameFromTopic(topic);
    const profileMetric = analogProfileMetric(metric);
    const definition = analogProfileDefinition(profileMetric);

    if (!definition) return;

    const current = Number(value);
    if (!Number.isFinite(current)) return;

    const previous = Number(analogRawLast[topic]);

    // Toujours mémoriser la valeur brute la plus récente, indépendamment des
    // filtres MQTT et des fenêtres statistiques.
    analogRawLast[topic] = current;

    const nowMs = Date.now();
    rollRawObserverIfNeeded(nowMs);
    rawObserver15m.bms_seen[slaveIdStr] = true;

    if (!Number.isFinite(previous)) return;

    const absDelta = Math.abs(current - previous);

    // Step 12F : uniquement la fenêtre longue 15 min, hors Recorder.
    const longProfile = ensureRawMetricProfile(
        rawObserver15m.metrics,
        profileMetric,
        definition
    );
    updateRawMetricProfile(longProfile, definition, absDelta);
}

for (var t in topics) {
    const value = topics[t];

    // Step 12F : alimenter uniquement l'observateur brut 15 min hors HA.
    profileAnalogRawCandidate(t, value);

    if (!changeOnlyEnabled) {
        // Compatibilité Legacy stricte : comportement historique.
        outputMsgs.push({
            topic: t,
            payload: value,
            pack_id: packId,
            pack_name: packName,
            bus_id: msg.bus_id || "bus_1"
        });
        continue;
    }

    publishStats.candidates_30s += 1;
    publishStats.candidates_total += 1;

    const comparable = mqttComparableValue(value);
    const alreadyKnown = Object.prototype.hasOwnProperty.call(lastPublished, t);
    const unchanged = alreadyKnown && lastPublished[t] === comparable;

    // Lors d'un Discovery (re)publié, forcer aussi les états actuels.
    const forcePublish = shouldSendDiscovery;
    const changed = !unchanged;
    const nowMs = Date.now();

    if (!changed && !forcePublish) {
        // Step 12A : doublon exact.
        publishStats.suppressed_30s += 1;
        publishStats.suppressed_total += 1;
        continue;
    }

    // Step 12C : filtre hybride pour tensions cellules uniquement.
    const cellDecision = cellVoltageDecision(
        t,
        value,
        nowMs,
        forcePublish
    );

    if (changed && cellDecision.governed && !cellDecision.allow) {
        // lastPublished reste la dernière valeur réellement publiée.
        if (cellDecision.reason === "midband_throttled") {
            publishStats.midband_held_30s =
                Number(publishStats.midband_held_30s || 0) + 1;
            publishStats.midband_held_total =
                Number(publishStats.midband_held_total || 0) + 1;
        } else {
            publishStats.deadband_held_30s =
                Number(publishStats.deadband_held_30s || 0) + 1;
            publishStats.deadband_held_total =
                Number(publishStats.deadband_held_total || 0) + 1;
        }
        continue;
    }

    // Step 13I-C1 : governor courant / puissance uniquement.
    const electricalDecision = electricalGovernorDecision(
        t,
        value,
        nowMs,
        forcePublish
    );

    if (changed && electricalDecision.governed && !electricalDecision.allow) {
        // Ne pas avancer lastPublished / lastPublishedNumeric : la prochaine
        // trame reste comparée à la dernière valeur réellement envoyée.
        publishStats.throttled_30s =
            Number(publishStats.throttled_30s || 0) + 1;
        publishStats.throttled_total =
            Number(publishStats.throttled_total || 0) + 1;
        continue;
    }

    // Step 13I-C2 : capacite restante + tension pack.
    const c2DerivedDecision = c2DerivedGovernorDecision(
        t,
        value,
        nowMs,
        forcePublish
    );

    if (changed && c2DerivedDecision.governed && !c2DerivedDecision.allow) {
        publishStats.throttled_30s =
            Number(publishStats.throttled_30s || 0) + 1;
        publishStats.throttled_total =
            Number(publishStats.throttled_total || 0) + 1;
        continue;
    }

    // Step 13I-C4 : cycle capacity cumulatif.
    const c4DerivedDecision = c4DerivedGovernorDecision(
        t,
        value,
        nowMs,
        forcePublish
    );

    if (changed && c4DerivedDecision.governed && !c4DerivedDecision.allow) {
        publishStats.throttled_30s =
            Number(publishStats.throttled_30s || 0) + 1;
        publishStats.throttled_total =
            Number(publishStats.throttled_total || 0) + 1;
        continue;
    }

    const temporalAllowed = temporalCanPublish(t, nowMs, forcePublish);

    if (changed && !temporalAllowed) {
        // Step 12B : vraie variation, intervalle minimal non écoulé.
        // lastPublished reste la dernière valeur réellement publiée afin
        // de publier la valeur la plus récente dès que l'intervalle expire.
        publishStats.throttled_30s =
            Number(publishStats.throttled_30s || 0) + 1;
        publishStats.throttled_total =
            Number(publishStats.throttled_total || 0) + 1;
        continue;
    }

    outputMsgs.push({
        topic: t,
        payload: value,
        pack_id: packId,
        pack_name: packName,
        bus_id: msg.bus_id || "bus_1"
    });

    lastPublished[t] = comparable;
    lastPublishTs[t] = nowMs;

    if (
        (cellDecision && cellDecision.governed) ||
        (electricalDecision && electricalDecision.governed) ||
        (c2DerivedDecision && c2DerivedDecision.governed) ||
        (c4DerivedDecision && c4DerivedDecision.governed)
    ) {
        const numericValue = Number(value);

        if (Number.isFinite(numericValue)) {
            lastPublishedNumeric[t] = numericValue;
        }
    }

    if (cellDecision && cellDecision.governed) {
        if (cellDecision.reason === "max_interval") {
            publishStats.deadband_published_30s =
                Number(publishStats.deadband_published_30s || 0) + 1;
            publishStats.deadband_published_total =
                Number(publishStats.deadband_published_total || 0) + 1;
        } else if (cellDecision.reason === "midband_interval") {
            publishStats.midband_published_30s =
                Number(publishStats.midband_published_30s || 0) + 1;
            publishStats.midband_published_total =
                Number(publishStats.midband_published_total || 0) + 1;
        }
    }

    publishStats.published_30s += 1;
    publishStats.published_total += 1;

    if (forcePublish && unchanged) {
        publishStats.forced_30s += 1;
        publishStats.forced_total += 1;
    }
}

if (changeOnlyEnabled) {
    flow.set(lastPublishedKey, lastPublished);
    flow.set(lastPublishTsKey, lastPublishTs);
    flow.set(lastPublishedNumericKey, lastPublishedNumeric);
    flow.set(analogRawLastKey, analogRawLast);
    flow.set(rawObserver15mKey, rawObserver15m);
    flow.set(publishStatsKey, publishStats);
}

return [outputMsgs];

// ========== SETUP TO MQTT - v4.2.80 LEGACY/BROADCASTING SAFE ==========
// Buts :
// - Publier au premier passage
// - Republier si une valeur change
// - Republier si forçage demandé
// - Recréer les entités HA si elles ont disparu
// - Supporter l'apparition de nouvelles clés sans bloquer

// -----------------------------------------------------------------
// 1) Identification du BMS
// -----------------------------------------------------------------
let bmsAdresse = Number(msg.bms_numero);
let slaveIdStr = (bmsAdresse === 0) ? "master" : String(bmsAdresse);

if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    node.warn(`Setup To MQTT ignoré: payload invalide pour BMS ${slaveIdStr}`);
    return null;
}

const payload = msg.payload;

// -----------------------------------------------------------------
// MQTT / HA identity : legacy strict ou Multi-Pack.
const multiPack = global.get("multi_pack_enabled") === true;
const packId = msg.pack_id || "pack_1";
const packName = msg.pack_name || "Pack 1";
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");

const baseTopic = multiPack
    ? `jkbms/${packId}/BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

const discoveryPrefix = "homeassistant";

const deviceName = multiPack
    ? `${packName} - BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

const deviceID = multiPack
    ? `${packSafe}_BMS_${slaveIdStr}_device`
    : `${baseTopic}_device`;

const entityPrefix = multiPack
    ? `${packSafe}_bms_${slaveIdStr}`
    : baseTopic.toLowerCase();

// -----------------------------------------------------------------
// 2) Clés de contexte
// -----------------------------------------------------------------
const setupSentKey = multiPack
    ? `setupSent_${packId}_BMS_${slaveIdStr}`
    : `setupSent_BMS_${slaveIdStr}`;

const lastSetupKey = multiPack
    ? `lastSetup_${packId}_BMS_${slaveIdStr}`
    : `lastSetup_BMS_${slaveIdStr}`;

const forceKeyFlow = multiPack
    ? `forceSetupRepublish_${packId}_BMS_${slaveIdStr}`
    : `forceSetupRepublish_BMS_${slaveIdStr}`;

const forceAllKeyFlow = multiPack
    ? `forceSetupRepublishAll_${packId}`
    : "forceSetupRepublishAll";

let setupAlreadySent = !!flow.get(setupSentKey);
let lastSetup = flow.get(lastSetupKey) || {};

const forceRepublish =
    msg.force_setup_republish === true ||
    flow.get(forceKeyFlow) === true ||
    flow.get(forceAllKeyFlow) === true ||
    global.get(forceKeyFlow) === true ||
    global.get(forceAllKeyFlow) === true;

// -----------------------------------------------------------------
// 3) Helpers
// -----------------------------------------------------------------
function formatBoolean(value) {
    if (typeof value === "boolean") {
        return value ? "True" : "False";
    }
    if (typeof value === "string") {
        const lowerVal = value.toLowerCase();
        if (lowerVal === "true") return "True";
        if (lowerVal === "false") return "False";
    }
    return value;
}

function normalizeValue(value) {
    if (typeof value === "boolean") {
        return value ? "True" : "False";
    }
    if (typeof value === "number") {
        // évite les faux changements 3.5 vs 3.500000
        return Number(value.toFixed(6));
    }
    if (typeof value === "string") {
        const lowerVal = value.toLowerCase();
        if (lowerVal === "true") return "True";
        if (lowerVal === "false") return "False";
        const asNum = Number(value);
        if (!Number.isNaN(asNum) && value.trim() !== "") {
            return Number(asNum.toFixed(6));
        }
        return value.trim();
    }
    return value;
}

function inferMeta(key) {
    // Quelques cas spécifiques conservés volontairement
    const custom = {
        max_charge_current_A: { unit: "A", min: 0, max: 600, step: 1 },
        max_discharge_current_S: { unit: "A", min: 0, max: 600, step: 1 }, // clé historique conservée
        max_balance_current_A: { unit: "A", min: 0, max: 10, step: 0.1 },
        total_battery_capacity_Ah: { unit: "Ah", min: 1, max: 2000, step: 1 },
        short_circuit_protection_delay_S: { unit: "s", min: 0, max: 5000, step: 1 },
        charge_overcurrent_protection_delay_S: { unit: "s", min: 0, max: 600, step: 1 },
        discharge_overcurrent_protection_delay_S: { unit: "s", min: 0, max: 600, step: 1 },
        charge_overcurrent_protection_recovery_time_S: { unit: "s", min: 0, max: 3600, step: 1 },
        discharge_overcurrent_protection_recovery_time_S: { unit: "s", min: 0, max: 3600, step: 1 },
        short_circuit_protection_recovery_time_S: { unit: "s", min: 0, max: 600, step: 1 },
        cell_count_N: { min: 1, max: 32, step: 1 },
        Device_address_N: { min: 0, max: 255, step: 1 }
    };

    if (custom[key]) return custom[key];

    if (key.endsWith("_V"))  return { unit: "V",  step: 0.001 };
    if (key.endsWith("_A"))  return { unit: "A",  step: 0.1 };
    if (key.endsWith("_Ah")) return { unit: "Ah", step: 1 };
    if (key.endsWith("_T"))  return { unit: "°C", step: 1 };
    if (key.endsWith("_S"))  return { unit: "s",  step: 1 };
    if (key.endsWith("_R"))  return { step: 0.001 };
    if (key.endsWith("_N"))  return { step: 1 };

    return {};
}

function createConfigPayload(key) {
    const cleanKey = key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "").toLowerCase();
    const entityType = key.endsWith("_B") ? "switch" : "number";
    const objectKey = key === "Device_address_N" ? "bms_device_address" : `bms_${cleanKey}`;

    const configPayload = {
        name: key === "Device_address_N" ? "BMS device address" : `BMS ${key.replace(/_[A-Z]+$/, "").replace(/_/g, " ")}`,
        unique_id: key === "Device_address_N" ? `${deviceID}_bms_device_address_v4` : `${deviceID}_bms_${cleanKey}_v4`,
        object_id: `${entityPrefix}_${objectKey}`,
        default_entity_id: `${entityType}.${entityPrefix}_${objectKey}`,
        state_topic: `${baseTopic}/control/${cleanKey}/state`,
        command_topic: `${baseTopic}/control/${cleanKey}/set`,
        entity_category: "config",
        device: {
            identifiers: [deviceID],
            name: deviceName,
            manufacturer: "Smartphoton-JK-BMS / ©JLM 2025-2026",
            model: payload.BMS_A || "JK-BMS - RS485 - Ip Gateway",
            sw_version: "3.5"
        }
    };

    if (entityType === "switch") {
        configPayload.payload_on = "True";
        configPayload.payload_off = "False";
        configPayload.state_on = "True";
        configPayload.state_off = "False";
        configPayload.icon = "mdi:toggle-switch";
    } else {
        configPayload.mode = "box";
        const meta = inferMeta(key);
        if (meta.unit !== undefined) configPayload.unit_of_measurement = meta.unit;
        if (meta.min !== undefined) configPayload.min = meta.min;
        if (meta.max !== undefined) configPayload.max = meta.max;
        if (meta.step !== undefined) configPayload.step = meta.step;
    }

    const configTopic = `${discoveryPrefix}/${entityType}/${deviceID}/${configPayload.object_id}/config`;

    return {
        topic: configTopic,
        payload: JSON.stringify(configPayload),
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: msg.bus_id || "bus_1"
    };
}

function createActivePollingSensorCleanupMessage(key) {
    // v4.2.80 - Symmetric migration Active Polling -> Multi-Pack Broadcasting.
    // Active Polling publishes SETUP values as read-only sensors using the same
    // device/object identity. Remove that retained sensor discovery before
    // restoring the historical number/switch entity.
    if (!multiPack) return null;

    const cleanKey = key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "").toLowerCase();
    const objectKey = key === "Device_address_N" ? "bms_device_address" : `bms_${cleanKey}`;
    const objectId = `${entityPrefix}_${objectKey}`;

    return {
        topic: `${discoveryPrefix}/sensor/${deviceID}/${objectId}/config`,
        payload: "",
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: msg.bus_id || "bus_1"
    };
}

function createActivePollingControlCleanupMessages() {
    if (!multiPack) return [];
    const controls = [
        "display_always_on_switch",
        "heating_switch",
        "charging_switch",
        "discharging_switch",
        "balance_switch",
        "smart_sleep_switch",
        "disable_pcl_module_switch",
        "timed_stored_data_switch",
        "charging_floating_mode"
    ];
    const cleanup = [];
    for (const control of controls) {
        const stableId = `${packId}_bms_${slaveIdStr}_${control}_active_polling`;
        // Pre-dev25 discovery topic.
        cleanup.push({
            topic: `${discoveryPrefix}/switch/${stableId}/config`,
            payload: "",
            retain: true,
            pack_id: packId,
            pack_name: packName,
            bus_id: msg.bus_id || "bus_1"
        });
        // dev25 deterministic-ID discovery topic.
        cleanup.push({
            topic: `${discoveryPrefix}/switch/${stableId}_v2/config`,
            payload: "",
            retain: true,
            pack_id: packId,
            pack_name: packName,
            bus_id: msg.bus_id || "bus_1"
        });
    }
    return cleanup;
}

function createStateMessage(key, value) {
    const cleanKey = key === "Device_address_N" ? "bms_device_address" : key.replace(/_[A-Z]+$/, "").toLowerCase();
    return {
        topic: `${baseTopic}/control/${cleanKey}/state`,
        payload: formatBoolean(value),
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: msg.bus_id || "bus_1"
    };
}

// -----------------------------------------------------------------
// 4) Construction des messages
// -----------------------------------------------------------------
let outMsgs = [];
let hasChanges = false;
let keys = Object.keys(payload).sort();

// v4.2.80 - When returning from Active Polling, remove its two dedicated
// control discoveries once per full SETUP rediscovery.
if (multiPack && (!setupAlreadySent || forceRepublish)) {
    outMsgs.push(...createActivePollingControlCleanupMessages());
}

for (const key of keys) {
    const currentNormalized = normalizeValue(payload[key]);
    const previousNormalized = normalizeValue(lastSetup[key]);

    const keyWasKnown = Object.prototype.hasOwnProperty.call(lastSetup, key);
    const changed = !setupAlreadySent || forceRepublish || !keyWasKnown || currentNormalized !== previousNormalized;

    // Recréation config :
    // - au premier envoi
    // - en republish forcé
    // - si une nouvelle clé apparaît
    if (!setupAlreadySent || forceRepublish || !keyWasKnown) {
        const staleActivePollingSensor = createActivePollingSensorCleanupMessage(key);
        if (staleActivePollingSensor) outMsgs.push(staleActivePollingSensor);
        outMsgs.push(createConfigPayload(key));
    }

    // Publication d'état :
    // - au premier envoi
    // - en republish forcé
    // - si changement
    if (changed) {
        outMsgs.push(createStateMessage(key, payload[key]));
        lastSetup[key] = payload[key];
        hasChanges = true;
    }
}

// -----------------------------------------------------------------
// 5) Sauvegarde état / logs
// -----------------------------------------------------------------
if (!setupAlreadySent || forceRepublish || hasChanges) {
    flow.set(setupSentKey, true);
    flow.set(lastSetupKey, lastSetup);

    // On nettoie les flags de forçage une fois utilisés
    flow.set(forceKeyFlow, false);
    flow.set(forceAllKeyFlow, false);

    if (!setupAlreadySent) {
        node.warn(`✓ Setup INITIAL envoyé pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else if (forceRepublish) {
        node.warn(`↻ Setup FORCÉ renvoyé pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else {
        node.warn(`✓ Setup CHANGEMENTS détectés pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    }

    return [outMsgs];
} else {
    node.debug(`⊘ Setup: aucun changement pour BMS ${slaveIdStr}`);
    return null;
}

// Traitement des trames déjà extraites par le Framer Broadcast RS485
// Ce noeud NE reconstruit plus les trames
// Il reçoit des objets du type :
// {
//   topic: "broadcast/jkbms_reply" | "broadcast/modbus_poll",
//   payload: <Buffer>,
//   hex: "...",
//   slave: 2
// }

function normalizeToBuffer(value) {
    if (Buffer.isBuffer(value)) {
        return value;
    }
    if (value && value.type === "Buffer" && Array.isArray(value.data)) {
        return Buffer.from(value.data);
    }
    if (Array.isArray(value)) {
        return Buffer.from(value);
    }
    return null;
}

function normalizeBmsIdentifier(v) {
    if (v === null || v === undefined) return null;
    if (typeof v === "string") {
        const t = v.trim().toLowerCase();
        if (!t) return null;
        if (t === "master") return "master";
        const n = Number(t);
        if (Number.isFinite(n)) return n === 0 ? "master" : String(n);
        return t;
    }
    if (typeof v === "number") {
        if (!Number.isFinite(v)) return null;
        return v === 0 ? "master" : String(v);
    }
    return null;
}

function refreshDetectedBms(id, packId) {
    if (!id) return;

    const now = Date.now();
    const WINDOW_MS = 120 * 1000;
    const effectivePackId = packId || "pack_1";

    // Registre canonique broadcasting par pack.
    // "0" = master, "1".."15" = adresses Modbus.
    const registryKey = `broadcast_bms_registry_${effectivePackId}`;
    let registry = flow.get(registryKey) || {
        seen: {},
        ids: [],
        labels: [],
        count: 0,
        slave_count: 0,
        last_update: 0
    };

    let canonicalId = null;
    if (id === "master") {
        canonicalId = 0;
    } else {
        const n = Number(id);
        if (Number.isInteger(n) && n >= 0 && n <= 15) {
            canonicalId = n;
        }
    }

    if (canonicalId !== null) {
        registry.seen = registry.seen || {};
        registry.seen[String(canonicalId)] = now;

        for (const [k, ts] of Object.entries(registry.seen)) {
            if ((now - Number(ts || 0)) > WINDOW_MS) {
                delete registry.seen[k];
            }
        }

        const ids = Object.keys(registry.seen)
            .map(k => Number(k))
            .filter(n => Number.isInteger(n) && n >= 0 && n <= 15)
            .sort((a, b) => a - b);

        registry.ids = ids;
        registry.labels = ids.map(n => n === 0 ? "master" : String(n));
        registry.count = ids.length;
        registry.slave_count = ids.filter(n => n !== 0).length;
        registry.last_update = now;
        registry.window_ms = WINDOW_MS;

        flow.set(registryKey, registry);
    }

    // Conserver les champs historiques des diagnostics.
    const diagKey = `diag_serial_stats_${effectivePackId}`;
    let diag = flow.get(diagKey) || {};
    let seen = diag.detected_bms_seen || {};

    seen[id] = now;

    for (const [k, ts] of Object.entries(seen)) {
        if ((now - Number(ts || 0)) > WINDOW_MS) {
            delete seen[k];
        }
    }

    const list = Object.keys(seen).sort((a, b) => {
        if (a === "master") return -1;
        if (b === "master") return 1;
        const na = Number(a), nb = Number(b);
        if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
        return String(a).localeCompare(String(b));
    });

    diag.detected_bms_seen = seen;
    diag.detected_bms = list.length;
    diag.detected_bms_list = list.join(", ");
    flow.set(diagKey, diag);
}

// Le Framer met son objet dans msg.payload
const framed = msg.payload;

if (!framed || typeof framed !== "object" || !framed.topic || !framed.payload) {
    return null;
}

// Métadonnées Multi-Pack transportées avec chaque trame.
// Valeurs par défaut = comportement actuel sur le premier bus.
const packId = framed.pack_id || msg.pack_id || "pack_1";
const defs = global.get("jkbms_pack_defs") || {};
const def = defs[packId] || {};
const multiPack = global.get("multi_pack_enabled") === true;

const packName = framed.pack_name || msg.pack_name ||
    (multiPack ? (def.name || "Pack 1") : "Pack 1");

const busId = framed.bus_id || msg.bus_id ||
    (multiPack
        ? (def.bus_id || `tcp_${def.port || "gateway"}`)
        : `tcp_${global.get("legacy_gateway_port") || global.get("gateway_port") || "legacy"}`);

const transport = framed._transport || msg._transport || "unknown";

// La paire DATA -> SETUP doit rester strictement dans le même pack.
// Sans cette clé par pack, une DATA de pack_1 pourrait être associée
// à une SETUP de pack_2.
const pendingDataKey = `jkbms_pending_data_${packId}`;
let pendingData = context.get(pendingDataKey) || null;

// Si le contexte a restauré un objet sérialisé, normaliser le payload.
if (pendingData && pendingData.payload) {
    const normalizedPending = normalizeToBuffer(pendingData.payload);
    if (normalizedPending) {
        pendingData.payload = normalizedPending;
    } else {
        pendingData = null;
        context.set(pendingDataKey, null);
    }
}

const frame = normalizeToBuffer(framed.payload);

if (!frame) {
    return null;
}

function typeTrame(byte) {
    if (byte === 1) return "setup";
    if (byte === 2) return "data";
    return "autre";
}

let outputFrames = [];

// --------------------------------------------------
// 1) Requête Modbus courte
// --------------------------------------------------
if (framed.topic === "broadcast/modbus_poll") {
    let reqMsg = {
        payload: Buffer.from(frame),
        bms_adresse: frame[0],
        bms_type: "requete",
        _frameSource: "REQUETE",
        _frameLength: frame.length,
        _hex: framed.hex || frame.toString("hex"),
        pack_id: packId,
        pack_name: packName,
        bus_id: busId,
        _transport: transport
    };

    return reqMsg;
}

// --------------------------------------------------
// 2) Réponse JK-BMS
// --------------------------------------------------
if (framed.topic === "broadcast/jkbms_reply") {
    // Vérification minimale header
    if (
        frame.length < 6 ||
        frame[0] !== 0x55 ||
        frame[1] !== 0xAA ||
        frame[2] !== 0xEB ||
        frame[3] !== 0x90
    ) {
        return null;
    }

    const frameType = typeTrame(frame[4]);

    if (frameType === "data") {
        // On mémorise la data, en attente de la setup suivante
        pendingData = {
            payload: Buffer.from(frame),
            bms_adresse: framed.slave !== undefined ? framed.slave : "master",
            bms_type: "data",
            _frameSource: "JK-BMS",
            _frameLength: frame.length,
            _hex: framed.hex || frame.toString("hex"),
            pack_id: packId,
            pack_name: packName,
            bus_id: busId,
            _transport: transport
        };

        context.set(pendingDataKey, pendingData);
        return null;
    }

    if (frameType === "setup") {
        // Extraction du numéro pack à offset 270..273
        // seulement si la trame est assez longue
        let bmsNumber = null;

        if (frame.length > 273) {
            bmsNumber =
                frame[270] |
                (frame[271] << 8) |
                (frame[272] << 16) |
                (frame[273] << 24);
        }

        const normalizedId = normalizeBmsIdentifier(bmsNumber);
        if (normalizedId) {
            refreshDetectedBms(normalizedId, packId);
        }

        // Envoyer d'abord la DATA mémorisée avec le bon numéro
        if (pendingData) {
            pendingData.bms_numero = bmsNumber;
            // Compatibilité si une DATA a été mémorisée avant un redéploiement.
            pendingData.pack_id   = pendingData.pack_id   || packId;
            pendingData.pack_name = pendingData.pack_name || packName;
            pendingData.bus_id    = pendingData.bus_id    || busId;
            pendingData._transport = pendingData._transport || transport;
            outputFrames.push(pendingData);
            pendingData = null;
            context.set(pendingDataKey, null);
        }

        // Puis envoyer la SETUP
        let setupMsg = {
            payload: Buffer.from(frame),
            bms_adresse: framed.slave !== undefined ? framed.slave : "master",
            bms_type: "setup",
            bms_numero: bmsNumber,
            _frameSource: "JK-BMS",
            _frameLength: frame.length,
            _hex: framed.hex || frame.toString("hex"),
            pack_id: packId,
            pack_name: packName,
            bus_id: busId,
            _transport: transport
        };

        outputFrames.push(setupMsg);

        if (outputFrames.length === 1) {
            return outputFrames[0];
        }
        return [outputFrames];
    }

    return null;
}

return null;

// v4.2.97 - Legacy Broadcasting address mapping fix (#180).
// Multi-Pack and Active Polling behaviour is preserved unchanged.

let nb = Number(global.get("nb_jkbms")) || 1;
nb = Math.max(1, Math.floor(nb));

const multiPack = global.get("multi_pack_enabled") === true;
const legacyBroadcasting = global.get("bms_broadcasting") === true;
const activePolling = global.get("jkbms_active_polling_enabled") === true;

function legacyMemberInfo(totalBms, broadcasting) {
    if (!broadcasting) {
        return {
            ids: Array.from({ length: totalBms }, (_, i) => i + 1),
            source: "global.get('nb_jkbms')"
        };
    }

    const neededSlaves = Math.max(0, totalBms - 1);
    if (neededSlaves === 0) {
        return {
            ids: [],
            source: "master_only"
        };
    }

    // v4.2.97 / issue #180:
    // Legacy Broadcasting now follows the actual addresses observed on the bus.
    // The DEV flow already has a canonical registry, populated upstream by
    // "Type trames + adresse modbus", so no additional detection state is needed.
    const registry = flow.get("broadcast_bms_registry_pack_1") || {};
    const seen = registry.seen;

    if (seen && typeof seen === "object" && !Array.isArray(seen)) {
        const now = Date.now();
        const MAX_AGE_MS = Number(registry.window_ms) > 0
            ? Number(registry.window_ms)
            : 120 * 1000;

        const masterTs = Number(seen["0"]);
        const masterFresh =
            Number.isFinite(masterTs) &&
            (now - masterTs) <= MAX_AGE_MS;

        const candidates = Object.entries(seen)
            .filter(([id, ts]) => {
                const n = Number(id);
                const t = Number(ts);
                return Number.isInteger(n) && n >= 1 && n <= 15 &&
                    Number.isFinite(t) && (now - t) <= MAX_AGE_MS;
            })
            .map(([id, ts]) => ({ address: Number(id), ts: Number(ts) }))
            .sort((a, b) => b.ts - a.ts);

        if (masterFresh && candidates.length >= neededSlaves) {
            return {
                ids: candidates
                    .slice(0, neededSlaves)
                    .map(x => x.address)
                    .sort((a, b) => a - b),
                source: "broadcast_bms_registry_pack_1"
            };
        }
    }

    // Backward-compatible fallback: keep the historical DEV mapping
    // (master occupies slot 1; numeric addresses start at BMS_2)
    // until real Broadcasting addresses have been observed.
    return {
        ids: Array.from({ length: neededSlaves }, (_, i) => i + 2),
        source: "historical_legacy_fallback"
    };
}

function sanitizeIds(values, allowMaster) {
    return [...new Set(
        (Array.isArray(values) ? values : [])
            .map(Number)
            .filter(id =>
                Number.isInteger(id) &&
                id >= (allowMaster ? 0 : 1) &&
                id <= 15
            )
    )].sort((a, b) => a - b);
}

function getMembersForPack(packId) {
    if (activePolling) {
        const defs = global.get("jkbms_pack_defs") || {};
        const def = defs[packId] || {};
        const configuredIds = sanitizeIds(def.bms_addresses, true);

        if (configuredIds.length > 0) {
            return {
                ids: configuredIds,
                source: "active_polling_config",
                masterDetected: false
            };
        }

        const registry = flow.get(`broadcast_bms_registry_${packId}`) || {};
        return {
            ids: sanitizeIds(registry.ids, true),
            source: "active_polling_detected",
            masterDetected: false
        };
    }

    const registry = flow.get(`broadcast_bms_registry_${packId}`) || {};
    const detectedIds = sanitizeIds(registry.ids, true);
    const ids = detectedIds.filter(id => id >= 1);

    if (ids.length > 0) {
        return {
            ids,
            source: "detected",
            masterDetected: detectedIds.includes(0)
        };
    }

    if (detectedIds.includes(0)) {
        return {
            ids: [],
            source: "detected_master_only",
            masterDetected: true
        };
    }

    return {
        ids: [],
        source: "waiting_detection",
        masterDetected: false
    };
}

function formatMembers(info) {
    if (activePolling) {
        if (info.ids.length > 0) {
            return `${info.ids.length} BMS configured: ${info.ids.join(", ")}`;
        }
        return "Active Polling: BMS detection/configuration pending";
    }

    if (info.source === "detected_master_only") {
        return "1 BMS detected: master";
    }

    if (info.ids.length > 0) {
        const total = 1 + info.ids.length;
        return `${total} BMS detected: master, ${info.ids.join(", ")}`;
    }

    return "master detected; slave detection pending";
}

if (!multiPack) {
    const legacyInfo = legacyMemberInfo(nb, legacyBroadcasting);
    const legacyIds = legacyInfo.ids;

    if (legacyBroadcasting) {
        flow.set("discoverySent_BMS_master", false);
        flow.set("discoveredKeys_BMS_master", []);

        flow.set("discoverySent_ALARMS_BMS_master", false);
        flow.set("lastAlarmState_BMS_master", null);
    }

    for (const i of legacyIds) {
        flow.set(`discoverySent_BMS_${i}`, false);
        flow.set(`discoveredKeys_BMS_${i}`, []);

        flow.set(`discoverySent_ALARMS_BMS_${i}`, false);
        flow.set(`lastAlarmState_BMS_${i}`, null);
    }

    flow.set("discoverySent_GLOBAL_ALARM", false);
    flow.set("lastGlobalAlarmState", null);

    const membersText = legacyBroadcasting
        ? (legacyIds.length
            ? `${1 + legacyIds.length} BMS: master, ${legacyIds.join(", ")}`
            : "1 BMS: master")
        : `${legacyIds.length} BMS: ${legacyIds.join(", ")}`;

    node.warn(
        `Legacy Discovery reset done for DATA + ALARMS + GLOBAL -> ` +
        `${nb} BMS total (${membersText}).`
    );
    return msg;
}

let packIds = global.get("jkbms_pack_ids");
if (!Array.isArray(packIds) || packIds.length === 0) {
    packIds = ["pack_1"];
}

for (const packId of packIds) {
    const info = getMembersForPack(packId);

    // Historical Broadcasting path has an implicit master.
    if (!activePolling) {
        flow.set(`discoverySent_BMS_${packId}_master`, false);
        flow.set(`discoveredKeys_BMS_${packId}_master`, []);

        flow.set(`discoverySent_ALARMS_${packId}_BMS_master`, false);
        flow.set(`lastAlarmState_${packId}_BMS_master`, null);

        flow.set(`setupSent_${packId}_BMS_master`, false);
        flow.set(`lastSetup_${packId}_BMS_master`, {});
    }

    for (const i of info.ids) {
        flow.set(`discoverySent_BMS_${packId}_${i}`, false);
        flow.set(`discoveredKeys_BMS_${packId}_${i}`, []);

        flow.set(`discoverySent_ALARMS_${packId}_BMS_${i}`, false);
        flow.set(`lastAlarmState_${packId}_BMS_${i}`, null);

        // Preserve the historical SETUP context reset only for Broadcasting.
        // Active Polling SETUP has its own apSetup* context and is reset by the
        // dedicated reset node, avoiding an unnecessary second rediscovery.
        if (!activePolling) {
            flow.set(`setupSent_${packId}_BMS_${i}`, false);
            flow.set(`lastSetup_${packId}_BMS_${i}`, {});
        }
    }

    flow.set(`discoverySent_GLOBAL_ALARM_${packId}`, false);
    flow.set(`lastGlobalAlarmState_${packId}`, null);

    node.warn(
        `Multi-Pack Discovery reset [${packId}] ` +
        formatMembers(info)
    );
}

return msg;

var BMS = msg.payload["Device_address_N"];
// Pour debug, affichons la valeur BMS
node.warn(`BMS Nb:${BMS} is alive`);
return msg;

const errorList = [
    "Balancing resistance too high",               // bit 0
    "MOS over-temperature protection",             // bit 1
    "Number of cells does not match parameter",    // bit 2
    "Abnormal current sensor",                     // bit 3
    "Cell over-voltage protection",                // bit 4
    "Battery over-voltage protection",             // bit 5
    "Overcurrent charge protection",               // bit 6
    "Charge short-circuit protection",             // bit 7
    "Over-temperature charge protection",          // bit 8
    "Low temperature charge protection",           // bit 9
    "Internal communication anomaly",              // bit 10
    "Cell under-voltage protection",               // bit 11
    "Battery under-voltage protection",            // bit 12
    "Overcurrent discharge protection",            // bit 13
    "Discharge short-circuit protection",          // bit 14
    "Over-temperature discharge protection",       // bit 15
    "Charge MOS anomaly",                          // bit 16
    "Discharge MOS anomaly",                       // bit 17
    "GPS disconnected",                            // bit 18
    "Please modify the authorization password in time", // bit 19
    "Discharge activation failure",                // bit 20
    "Battery over-temperature alarm",              // bit 21
    "Temperature sensor anomaly",                  // bit 22
    "Parallel module anomaly",                     // bit 23
    "Erreur fictive Bit 24",
    "Erreur fictive Bit 25",
    "Erreur fictive Bit 26",
    "Erreur fictive Bit 27",
    "Erreur fictive Bit 28",
    "Erreur fictive Bit 29",
    "Erreur fictive Bit 30",
    "Erreur fictive Bit 31"
];

const buffer = msg.payload;
if (buffer.length <= 169) {
    msg.payload = { error: "Buffer too small to extract error code", bms_address: msg.bms_adresse };
    return msg;
}

// Swap bytes as requested
const swappedErrorCode =
    (buffer[169] << 24) |
    (buffer[168] << 16) |
    (buffer[167] << 8) |
    (buffer[166]);

const activeErrors = [];
for (let i = 0; i < errorList.length; i++) {
    if (swappedErrorCode & (1 << i)) {
        activeErrors.push(errorList[i]);
    }
}

// Construction du payload dans le format "référence"
// MODIFICATION: Ne pas inclure le préfixe "🚨 BMS Alarm Alert" dans le tableau errors
msg.payload = {
    bms_address: msg.bms_numero,
    error_code: swappedErrorCode,
    errors: activeErrors.length > 0 ? activeErrors : [],
    pack_id: msg.pack_id || "pack_1",
    pack_name: msg.pack_name || "Pack 1",
    bus_id: msg.bus_id || "bus_1"
};

return msg;

// ====== TRAITEMENT DES ALARMES - VERSION OPTIMISÉE / ROBUSTE ======

const p = msg.payload || {};

// ------------------------------------------------------------------
// MÉTADONNÉES MULTI-PACK
const multiPack = global.get("multi_pack_enabled") === true;
const packId = msg.pack_id || p.pack_id || "pack_1";
const packName = msg.pack_name || p.pack_name || "Pack 1";
const busId = msg.bus_id || p.bus_id || "bus_1";

msg.pack_id = packId;
msg.pack_name = packName;
msg.bus_id = busId;

// ------------------------------------------------------------------
// VALIDATION / NORMALISATION
const errorCode = Number(p.error_code);
if (!Number.isFinite(errorCode)) {
    node.error("Invalid payload: error_code missing");
    return [null, null];
}

let bmsNumeroRaw = msg.bms_numero;
let bmsId;
let bmsName;

if (typeof bmsNumeroRaw === "string" && bmsNumeroRaw.toLowerCase() === "master") {
    bmsId = 0;
    bmsName = "BMS_master";
} else if (!isNaN(Number(bmsNumeroRaw))) {
    bmsId = Number(bmsNumeroRaw);
    bmsName = (bmsId === 0 && !(global.get("multi_pack_enabled") === true && global.get("jkbms_active_polling_enabled") === true)) ? "BMS_master" : `BMS_${bmsId}`;
} else {
    node.error("Invalid message: bms_numero missing or invalid");
    return [null, null];
}

// ------------------------------------------------------------------
// CLÉS DE STOCKAGE POUR DÉTECTION DE CHANGEMENT
const discoveryKey = multiPack
    ? `discoverySent_ALARMS_${packId}_${bmsName}`
    : `discoverySent_ALARMS_${bmsName}`;

const lastAlarmStateKey = multiPack
    ? `lastAlarmState_${packId}_${bmsName}`
    : `lastAlarmState_${bmsName}`;

const discoveryAlreadySent = flow.get(discoveryKey) || false;
const lastAlarmState = flow.get(lastAlarmStateKey) || null;

// ------------------------------------------------------------------
// CONVERSION AU FORMAT INTERNE
const hasAlarms = errorCode !== 0;
const errorList = Array.isArray(p.errors) ? p.errors : [];
const alarmCount = hasAlarms ? errorList.length : 0;

const alarmData = {
    pack_id: packId,
    pack_name: packName,
    bus_id: busId,
    bms_id: bmsId,
    bms_name: bmsName,
    has_alarms: hasAlarms,
    alarm_count: alarmCount,
    active_alarms: hasAlarms ? errorList.map(e => ({ description: e })) : [],
    alarm_details: {
        status: hasAlarms ? "🚨 BMS Alarm Alert" : "No BMS alarms"
    }
};

// ------------------------------------------------------------------
// DÉTECTION DE CHANGEMENT
const currentStateSignature = JSON.stringify({
    error_code: errorCode,
    errors: errorList
});

const hasChanged = (lastAlarmState !== currentStateSignature);

// ------------------------------------------------------------------
// SI AUCUN CHANGEMENT ET DÉJÀ ENVOYÉ → ON SORT
msg.alarms = alarmData;
msg.bms_name = bmsName;
msg.bms_id = bmsId;

if (!hasChanged && discoveryAlreadySent) {
    node.debug(`⊘ Alarmes ${bmsName}: Aucun changement (error_code: ${errorCode})`);
    return [null, msg];
}

// ------------------------------------------------------------------
// IL Y A UN CHANGEMENT OU C'EST LE 1ER ENVOI
if (hasChanged) {
    if (lastAlarmState === null) {
        node.warn(`✓ Alarmes ${bmsName}: INITIAL (error_code: ${errorCode})`);
    } else {
        node.warn(`✓ Alarmes ${bmsName}: CHANGEMENT détecté ! (${errorCode === 0 ? 'Alarmes effacées' : alarmCount + ' alarme(s)'})`);
    }
}

flow.set(lastAlarmStateKey, currentStateSignature);

// ------------------------------------------------------------------
// DISCOVERY / MQTT : legacy strict ou Multi-Pack.
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");
const bmsSafe = bmsName.toLowerCase();

const baseTopic = multiPack
    ? `jkbms/${packId}/${bmsName}`
    : bmsName;

const discoveryPrefix = "homeassistant";

const deviceID = multiPack
    ? `${packSafe}_${bmsName}_device`
    : `${bmsName}_device`;

const entityPrefix = multiPack
    ? `${packSafe}_${bmsSafe}`
    : `${bmsSafe}_${bmsSafe}`;

const packBmsDeviceName = multiPack
    ? `${packName} - ${bmsName}`
    : bmsName;

function alarmDiscoveryTopic(domain, suffix) {
    if (multiPack) {
        return `${discoveryPrefix}/${domain}/${deviceID}/${suffix}/config`;
    }
    return `${discoveryPrefix}/${domain}/${bmsSafe}_${bmsSafe}_${suffix}/config`;
}

function buildDiscovery() {
    const m = [];

    m.push({
        topic: alarmDiscoveryTopic("binary_sensor", "alarm_active"),
        payload: {
            name: `${bmsName} Alarm Active`,
            unique_id: `${deviceID}_alarm_active_v2`,
            object_id: `${entityPrefix}_alarm_active`,
            default_entity_id: `binary_sensor.${entityPrefix}_alarm_active`,
            state_topic: `${baseTopic}/alarm/active`,
            payload_on: "ON",
            payload_off: "OFF",
            device_class: "problem",
            icon: "mdi:alert-circle",
            device: {
                identifiers: [deviceID],
                name: packBmsDeviceName
            }
        },
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    m.push({
        topic: alarmDiscoveryTopic("sensor", "visual_status"),
        payload: {
            name: `${bmsName} Visual Status`,
            unique_id: `${deviceID}_visual_status_v2`,
            object_id: `${entityPrefix}_visual_status`,
            default_entity_id: `sensor.${entityPrefix}_visual_status`,
            state_topic: `${baseTopic}/alarm/visual_status`,
            icon: "mdi:gauge",
            device: {
                identifiers: [deviceID],
                name: packBmsDeviceName
            }
        },
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    m.push({
        topic: alarmDiscoveryTopic("sensor", "alarm_status"),
        payload: {
            name: `${bmsName} Alarm Status`,
            unique_id: `${deviceID}_alarm_status_v2`,
            object_id: `${entityPrefix}_alarm_status`,
            default_entity_id: `sensor.${entityPrefix}_alarm_status`,
            state_topic: `${baseTopic}/alarm/status`,
            icon: "mdi:text-box-outline",
            device: {
                identifiers: [deviceID],
                name: packBmsDeviceName
            }
        },
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    m.push({
        topic: alarmDiscoveryTopic("sensor", "alarm_list"),
        payload: {
            name: `${bmsName} Alarm List`,
            unique_id: `${deviceID}_alarm_list_v2`,
            object_id: `${entityPrefix}_alarm_list`,
            default_entity_id: `sensor.${entityPrefix}_alarm_list`,
            state_topic: `${baseTopic}/alarm/list`,
            icon: "mdi:format-list-bulleted",
            device: {
                identifiers: [deviceID],
                name: packBmsDeviceName
            }
        },
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    return m;
}

function buildState() {
    const out = [];

    out.push({
        topic: `${baseTopic}/alarm/active`,
        payload: alarmData.has_alarms ? "ON" : "OFF",
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    out.push({
        topic: `${baseTopic}/alarm/visual_status`,
        payload: alarmData.has_alarms
            ? `🚨 ${alarmData.alarm_count} alarme(s)`
            : "✅ No alarm",
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    out.push({
        topic: `${baseTopic}/alarm/status`,
        payload: alarmData.alarm_details.status,
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    out.push({
        topic: `${baseTopic}/alarm/list`,
        payload: alarmData.active_alarms.length > 0
            ? alarmData.active_alarms.map(a => a.description).join(", ")
            : "No alarms",
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    return out;
}

// ------------------------------------------------------------------
// PRÉPARATION DES SORTIES
const mqttMsgs = [];

if (!discoveryAlreadySent) {
    mqttMsgs.push(...buildDiscovery());
    flow.set(discoveryKey, true);
}

mqttMsgs.push(...buildState());

// sortie 1 = MQTT
// sortie 2 = msg enrichi pour l’agrégation globale
return [mqttMsgs, msg];

// ===== GLOBAL ALARM AGGREGATION - OPTIMISED VERSION =====
// ✓ Sent at start-up
// ✓ Sent ONLY if global status changes
// ✓ Massive savings in MQTT messages

const alarmData = msg.alarms;
if (!alarmData || alarmData.bms_id === undefined || alarmData.bms_id === null) {
    return null;
}

const bmsId = alarmData.bms_id;
const multiPack = global.get("multi_pack_enabled") === true;
const packId = msg.pack_id || alarmData.pack_id || "pack_1";
const packName = msg.pack_name || alarmData.pack_name || "Pack 1";
const busId = msg.bus_id || alarmData.bus_id || "bus_1";
const now = Date.now();

msg.pack_id = packId;
msg.pack_name = packName;
msg.bus_id = busId;

// Legacy: JKBMS_COUNT is the TOTAL number of BMS on the bus.
// Active polling uses numeric IDs 1..N.
// Broadcasting represents slot 1 as "master", then slaves 2..N.
const TOTAL_BMS_LEGACY = Math.max(
    1,
    Math.floor(Number(global.get("nb_jkbms")) || 1)
);
const LEGACY_BROADCASTING = global.get("bms_broadcasting") === true;

// Multi-Pack: membres réellement détectés sur CE bus.
const DETECTED_WINDOW_MS = 120 * 1000;

// Durée max sans message d'alarme avant exclusion du calcul.
const TIMEOUT_MS = 15000;

function getDetectedPackIds() {
    if (!multiPack) {
        const legacyIds = [];

        if (LEGACY_BROADCASTING) {
            legacyIds.push(0); // master = slot 1
            for (let i = 2; i <= TOTAL_BMS_LEGACY; i++) {
                legacyIds.push(i);
            }
        } else {
            for (let i = 1; i <= TOTAL_BMS_LEGACY; i++) {
                legacyIds.push(i);
            }
        }

        return {
            ids: legacyIds,
            source: LEGACY_BROADCASTING
                ? "legacy_total_count_broadcast"
                : "legacy_total_count_active_polling"
        };
    }

    const registryKey = `broadcast_bms_registry_${packId}`;
    const registry = flow.get(registryKey) || {};
    const seen = registry.seen || {};
    const cleanedSeen = {};

    for (const [key, tsRaw] of Object.entries(seen)) {
        const id = Number(key);
        const ts = Number(tsRaw || 0);
        if (
            Number.isInteger(id) &&
            id >= 0 && id <= 15 &&
            ts > 0 &&
            (now - ts) <= DETECTED_WINDOW_MS
        ) {
            cleanedSeen[String(id)] = ts;
        }
    }

    const ids = Object.keys(cleanedSeen)
        .map(k => Number(k))
        .sort((a, b) => a - b);

    // Le BMS ayant produit le message courant doit toujours participer,
    // même pendant les toutes premières trames du démarrage.
    const currentId = Number(bmsId);
    if (
        Number.isInteger(currentId) &&
        currentId >= 0 && currentId <= 15 &&
        !ids.includes(currentId)
    ) {
        ids.push(currentId);
        ids.sort((a, b) => a - b);
    }

    const labels = ids.map(id => id === 0 ? "master" : String(id));
    flow.set(registryKey, {
        ...registry,
        seen: cleanedSeen,
        ids,
        labels,
        count: ids.length,
        slave_count: ids.filter(id => id !== 0).length,
        last_update: Number(registry.last_update || now),
        window_ms: DETECTED_WINDOW_MS
    });

    return {
        ids,
        source: Object.keys(cleanedSeen).length
            ? "broadcast_detected_registry"
            : "current_alarm_fallback"
    };
}

// ------------------------------------------------------------------
// ENREGISTREMENT ÉTAT + TIMESTAMP POUR CE BMS
const alarmStateKey = multiPack
    ? `bms_alarm_state_${packId}_${bmsId}`
    : `bms_alarm_state_${bmsId}`;

flow.set(alarmStateKey, {
    pack_id: packId,
    has_alarm: alarmData.has_alarms,
    alarm_count: alarmData.alarm_count,
    last_seen: now
});

// ------------------------------------------------------------------
// CALCUL ÉTAT GLOBAL
let globalHasAlarm = false;
let activeAlarmsList = [];

const memberInfo = getDetectedPackIds();
const memberIds = memberInfo.ids;

for (const i of memberIds) {
    const stateKey = multiPack
        ? `bms_alarm_state_${packId}_${i}`
        : `bms_alarm_state_${i}`;

    const s = flow.get(stateKey);
    if (!s) continue;

    // Ignore BMS muet depuis trop longtemps
    if ((now - Number(s.last_seen || 0)) > TIMEOUT_MS) continue;

    if (s.has_alarm) {
        globalHasAlarm = true;
        activeAlarmsList.push(`BMS_${i === 0 ? "master" : i}`);
    }
}

// ------------------------------------------------------------------
// DÉTECTION DE CHANGEMENT
const lastGlobalStateKey = multiPack
    ? `lastGlobalAlarmState_${packId}`
    : "lastGlobalAlarmState";
const lastGlobalState = flow.get(lastGlobalStateKey);

const currentGlobalState = globalHasAlarm ? "ON" : "OFF";
const hasChanged = (lastGlobalState !== currentGlobalState);

// ------------------------------------------------------------------
// SI AUCUN CHANGEMENT ET DÉJÀ ENVOYÉ → ON SORT
if (!hasChanged && lastGlobalState !== null) {
    node.debug(`⊘ GLOBAL alarm: No change (state: ${currentGlobalState})`);
    return null;
}

// ------------------------------------------------------------------
// IL Y A UN CHANGEMENT OU C'EST LE 1ER ENVOI
if (hasChanged) {
    if (lastGlobalState === null) {
        node.warn(
            multiPack
                ? `✓ [${packId}] GLOBAL alarm: INITIAL (${currentGlobalState}) members=${memberIds.map(i => i === 0 ? "master" : i).join(",") || "none"}`
                : `✓ GLOBAL alarm: INITIAL (${currentGlobalState})`
        );
    } else {
        if (globalHasAlarm) {
            node.warn(
                multiPack
                    ? `🚨 [${packId}] GLOBAL alarm: ON (BMS concerned: ${activeAlarmsList.join(", ")})`
                    : `🚨 GLOBAL alarm: ON (BMS concerned: ${activeAlarmsList.join(", ")})`
            );
        } else {
            node.warn(
                multiPack
                    ? `✅ [${packId}] GLOBAL alarm: OFF (all alarms cleared)`
                    : `✅ GLOBAL alarm: OFF (all alarms cleared)`
            );
        }
    }
}

// Sauvegarder le nouvel état
flow.set(lastGlobalStateKey, currentGlobalState);

// ------------------------------------------------------------------
// MQTT / HOME ASSISTANT
const discoveryPrefix = "homeassistant";
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");

const globalDeviceID = multiPack
    ? `${packSafe}_BMS_GLOBAL_device`
    : "BMS_GLOBAL_device";

const globalDeviceName = multiPack
    ? `${packName} - BMS Global`
    : "BMS Global";

const globalBaseTopic = multiPack
    ? `jkbms/${packId}/BMS_GLOBAL`
    : "BMS_GLOBAL";

const messages = [];

// ------------------------------------------------------------------
// DISCOVERY (une fois)
const globalDiscoveryKey = multiPack
    ? `discoverySent_GLOBAL_ALARM_${packId}`
    : "discoverySent_GLOBAL_ALARM";
if (!flow.get(globalDiscoveryKey)) {
    messages.push({
        topic: `${discoveryPrefix}/binary_sensor/${globalDeviceID}/alarm_active/config`,
        payload: {
            name: "BMS Global Alarm",
            unique_id: `${globalDeviceID}_alarm_active`,
            state_topic: `${globalBaseTopic}/alarm/state`,
            payload_on: "ON",
            payload_off: "OFF",
            device_class: "problem",
            icon: "mdi:battery-alert",
            device: {
                identifiers: [globalDeviceID],
                name: globalDeviceName
            }
        },
        retain: true,
        pack_id: packId,
        pack_name: packName,
        bus_id: busId
    });

    flow.set(globalDiscoveryKey, true);
    node.warn(
        multiPack
            ? `✓ [${packId}] Discovery GLOBAL ALARM sent`
            : "✓ Discovery GLOBAL ALARM sent"
    );
}

// ------------------------------------------------------------------
// PUBLICATION ÉTAT GLOBAL (only if changed)
messages.push({
    topic: `${globalBaseTopic}/alarm/state`,
    payload: currentGlobalState,
    retain: true,
    pack_id: packId,
    pack_name: packName,
    bus_id: busId
});

return [messages];

// ========== FILTRE DE VALIDATION BMS_NUMERO ==========
// À placer APRÈS buffer-parser, AVANT les nœuds de traitement
// Valide que msg.bms_numero est entre 0 et 15
// Bloque et signale toute valeur invalide

const bmsNumero = msg.bms_numero;

// ------------------------------------------------------------------
// VALIDATION TYPE
if (bmsNumero === undefined || bmsNumero === null) {
    node.error(`❌ BMS_NUMERO INVALIDE: valeur manquante (undefined/null)`, msg);
    node.warn(`Payload reçu: ${JSON.stringify(msg.payload)}`);
    return null; // Bloque le message
}

// Conversion en nombre si c'est une string
let bmsNum;
if (typeof bmsNumero === "string") {
    bmsNum = parseInt(bmsNumero, 10);
    if (isNaN(bmsNum)) {
        node.error(`❌ BMS_NUMERO INVALIDE: string non numérique "${bmsNumero}"`, msg);
        return null;
    }
    // Correction automatique
    msg.bms_numero = bmsNum;
    node.warn(`⚠️ BMS_NUMERO converti: "${bmsNumero}" → ${bmsNum}`);
} else if (typeof bmsNumero === "number") {
    if (isNaN(bmsNumero)) {
        node.error(`❌ BMS_NUMERO INVALIDE: NaN`, msg);
        return null;
    }
    bmsNum = bmsNumero;
} else {
    node.error(`❌ BMS_NUMERO INVALIDE: type incorrect (${typeof bmsNumero})`, msg);
    return null;
}

// ------------------------------------------------------------------
// VALIDATION PLAGE (0 à 15)
if (bmsNum < 0 || bmsNum > 15) {
    node.error(`❌ BMS_NUMERO HORS LIMITES: ${bmsNum} (attendu: 0-15)`, msg);
    node.warn(`Payload reçu: ${JSON.stringify(msg.payload)}`);
    return null; // Bloque le message
}

// ------------------------------------------------------------------
// VALIDATION ENTIER
if (!Number.isInteger(bmsNum)) {
    node.error(`❌ BMS_NUMERO INVALIDE: nombre décimal ${bmsNum} (attendu: entier)`, msg);
    return null;
}

// ------------------------------------------------------------------
// ✅ VALIDATION OK
// Compteur de validation (optionnel, pour statistiques)
const packId = msg.pack_id || "pack_1";
const validCountKey = `valid_bms_count_${packId}_${bmsNum}`;
let validCount = flow.get(validCountKey) || 0;
validCount++;
flow.set(validCountKey, validCount);

// Log détaillé toutes les 100 validations par BMS (pour ne pas polluer)
if (validCount % 100 === 0) {
    const bmsName = bmsNum === 0 ? "master" : bmsNum;
    node.debug(`✓ ${packId}/BMS_${bmsName}: ${validCount} messages validés`);
}

// Message valide, on le laisse passer
return msg;

// ========== FILTRE DE VALIDATION BMS_NUMERO ==========
// À placer APRÈS buffer-parser, AVANT les nœuds de traitement
// Valide que msg.bms_numero est entre 0 et 15
// Bloque et signale toute valeur invalide

const bmsNumero = msg.bms_numero;

// ------------------------------------------------------------------
// VALIDATION TYPE
if (bmsNumero === undefined || bmsNumero === null) {
    node.error(`❌ BMS_NUMERO INVALIDE: valeur manquante (undefined/null)`, msg);
    node.warn(`Payload reçu: ${JSON.stringify(msg.payload)}`);
    return null; // Bloque le message
}

// Conversion en nombre si c'est une string
let bmsNum;
if (typeof bmsNumero === "string") {
    bmsNum = parseInt(bmsNumero, 10);
    if (isNaN(bmsNum)) {
        node.error(`❌ BMS_NUMERO INVALIDE: string non numérique "${bmsNumero}"`, msg);
        return null;
    }
    // Correction automatique
    msg.bms_numero = bmsNum;
    node.warn(`⚠️ BMS_NUMERO converti: "${bmsNumero}" → ${bmsNum}`);
} else if (typeof bmsNumero === "number") {
    if (isNaN(bmsNumero)) {
        node.error(`❌ BMS_NUMERO INVALIDE: NaN`, msg);
        return null;
    }
    bmsNum = bmsNumero;
} else {
    node.error(`❌ BMS_NUMERO INVALIDE: type incorrect (${typeof bmsNumero})`, msg);
    return null;
}

// ------------------------------------------------------------------
// VALIDATION PLAGE (0 à 15)
if (bmsNum < 0 || bmsNum > 15) {
    node.error(`❌ BMS_NUMERO HORS LIMITES: ${bmsNum} (attendu: 0-15)`, msg);
    node.warn(`Payload reçu: ${JSON.stringify(msg.payload)}`);
    return null; // Bloque le message
}

// ------------------------------------------------------------------
// VALIDATION ENTIER
if (!Number.isInteger(bmsNum)) {
    node.error(`❌ BMS_NUMERO INVALIDE: nombre décimal ${bmsNum} (attendu: entier)`, msg);
    return null;
}

// ------------------------------------------------------------------
// v4.2.108 TEST - Multi-Pack signed battery power normalization
//
// The JK DATA frame exposes Puissance_Totale_W as an unsigned magnitude
// while Courant_total_A is signed. In Multi-Pack, normalize the power sign
// once here, before MQTT publication and Pack/Global aggregation, so every
// downstream consumer sees the same algebraic value.
//
// Legacy behavior is intentionally left untouched.
if (global.get("multi_pack_enabled") === true && msg.payload && typeof msg.payload === "object") {
    const currentA = Number(msg.payload.Courant_total_A);
    const rawPowerW = Number(msg.payload.Puissance_Totale_W);

    if (Number.isFinite(currentA) && Number.isFinite(rawPowerW)) {
        const magnitudeW = Math.abs(rawPowerW);

        if (currentA < 0) {
            msg.payload.Puissance_Totale_W = -magnitudeW;
        } else if (currentA > 0) {
            msg.payload.Puissance_Totale_W = magnitudeW;
        } else {
            msg.payload.Puissance_Totale_W = 0;
        }
    }
}

// ------------------------------------------------------------------
// ✅ VALIDATION OK
// Compteur de validation (optionnel, pour statistiques)
const packId = msg.pack_id || "pack_1";
const validCountKey = `valid_bms_count_${packId}_${bmsNum}`;
let validCount = flow.get(validCountKey) || 0;
validCount++;
flow.set(validCountKey, validCount);

// Log détaillé toutes les 100 validations par BMS (pour ne pas polluer)
if (validCount % 100 === 0) {
    const bmsName = bmsNum === 0 ? "master" : bmsNum;
    node.debug(`✓ ${packId}/BMS_${bmsName}: ${validCount} messages validés`);
}

// Message valide, on le laisse passer
return msg;

// =========================================================
// STEP 13E - MULTI-PACK PACK AGGREGATOR FOUNDATION
//
// Free Multi-Pack feature.
// One dynamic DATA frame updates the snapshot of one BMS.
// Fresh BMS snapshots are then aggregated by pack_id.
//
// IMPORTANT:
// - Legacy path: strictly untouched (node returns null).
// - No HA Discovery here yet.
// - No Recorder entities here yet.
// - One retained JSON topic per pack for validation:
//     jkbms/<pack_id>/aggregate
// - Existing BMS MQTT/governors are untouched.
// =========================================================

if (global.get("multi_pack_enabled") !== true) {
    return null;
}

const packId = String(msg.pack_id || "").trim();
if (!packId) return null;

const defs = global.get("jkbms_pack_defs") || {};
const packDef = defs[packId];
if (!packDef) return null;

const payload = msg.payload;
if (!payload || typeof payload !== "object") return null;

const now = Date.now();
const STALE_MS = 30000;
const MQTT_MIN_INTERVAL_MS = 2000;

function finiteNumber(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function validPositive(v) {
    const n = finiteNumber(v);
    return n !== null && n > 0 ? n : null;
}

function round(v, digits) {
    if (!Number.isFinite(v)) return null;
    const p = Math.pow(10, digits);
    return Math.round((v + Number.EPSILON) * p) / p;
}

function bmsKeyFromNumero(v) {
    if (typeof v === "string" && v.toLowerCase() === "master") {
        return "master";
    }
    const n = Number(v);
    if (!Number.isFinite(n)) return null;
    if (n === 0) return global.get("jkbms_active_polling_enabled") === true ? "0" : "master";
    if (!Number.isInteger(n) || n < 1 || n > 15) return null;
    return String(n);
}

function sortBmsKeys(keys) {
    return [...keys].sort((a, b) => {
        if (a === "master") return -1;
        if (b === "master") return 1;
        return Number(a) - Number(b);
    });
}

const bmsKey = bmsKeyFromNumero(msg.bms_numero);
if (!bmsKey) return null;

// ---------------------------------------------------------
// 1. Build/update one BMS snapshot from the DATA frame.
// ---------------------------------------------------------
const cells = [];
for (let i = 1; i <= 16; i++) {
    const v = finiteNumber(payload[`Cell_${i}_volt_V`]);
    // 0 is used as an invalid/unavailable value. Keep a deliberately
    // broad upper limit so the aggregator does not assume one chemistry.
    if (v !== null && v > 0 && v < 10) {
        cells.push({ index: i, voltage_v: v });
    }
}

const temperatures = [];
for (const key of [
    "Mos_temp_T",
    "Sonde_1_temp_T",
    "Sonde_2_temp_T",
    "Sonde_3_temp_T",
    "Sonde_4_temp_T"
]) {
    const v = finiteNumber(payload[key]);
    if (v !== null && v > -100 && v < 200) {
        temperatures.push({ sensor: key.replace(/_T$/, ""), value_c: v });
    }
}

const snapshot = {
    bms: bmsKey,
    ts: now,
    voltage_v: validPositive(payload.Tension_Totale_volt_V),
    current_a: finiteNumber(payload.Courant_total_A),
    power_w: finiteNumber(payload.Puissance_Totale_W),
    soc_pct: finiteNumber(payload.SOC_pourcentage_P),
    soh_pct: finiteNumber(payload.SOH_pourcentage_P),
    remaining_capacity_ah: finiteNumber(payload.Capacite_restante_Ah),
    nominal_capacity_ah: finiteNumber(payload.Capacite_batterie_Ah),

    // JK active-balancing telemetry. Keep the signed current exactly as
    // reported by the BMS; the sign is intentionally not reinterpreted.
    balance_current_a: finiteNumber(payload.Balance_courant_A),
    balance_active:
        (payload.Balance_Action_B !== undefined && payload.Balance_Action_B !== null)
            ? (payload.Balance_Action_B === true || Number(payload.Balance_Action_B) === 1)
            : (finiteNumber(payload.Balance_courant_A) !== null &&
                Math.abs(finiteNumber(payload.Balance_courant_A)) > 0.001),

    cells,
    temperatures
};

const snapshotsKey = "multi_pack_pack_aggregate_snapshots";
let allSnapshots = flow.get(snapshotsKey) || {};
if (!allSnapshots[packId] || typeof allSnapshots[packId] !== "object") {
    allSnapshots[packId] = {};
}
allSnapshots[packId][bmsKey] = snapshot;

// Remove snapshots that are no longer fresh. If one BMS disappears while
// others keep broadcasting, it automatically leaves the pack aggregate.
for (const [member, s] of Object.entries(allSnapshots[packId])) {
    if (!s || !Number(s.ts) || (now - Number(s.ts)) > STALE_MS) {
        delete allSnapshots[packId][member];
    }
}
flow.set(snapshotsKey, allSnapshots);

const fresh = allSnapshots[packId];
const members = sortBmsKeys(Object.keys(fresh));
if (members.length === 0) return null;

// ---------------------------------------------------------
// 2. Aggregate the fresh BMS snapshots for this pack.
// ---------------------------------------------------------
const voltages = [];
const currents = [];
const powers = [];
const socs = [];
const sohs = [];
const remainingCaps = [];
const nominalCaps = [];
const allCells = [];
const allTemps = [];
const balancingDetails = [];

for (const member of members) {
    const s = fresh[member];

    if (Number.isFinite(s.voltage_v)) voltages.push(s.voltage_v);
    if (Number.isFinite(s.current_a)) currents.push(s.current_a);
    if (Number.isFinite(s.power_w)) powers.push(s.power_w);
    if (Number.isFinite(s.soc_pct)) socs.push({ value: s.soc_pct, bms: member });
    if (Number.isFinite(s.soh_pct)) sohs.push({ value: s.soh_pct, bms: member });

    if (Number.isFinite(s.remaining_capacity_ah) && s.remaining_capacity_ah >= 0) {
        remainingCaps.push(s.remaining_capacity_ah);
    }
    if (Number.isFinite(s.nominal_capacity_ah) && s.nominal_capacity_ah > 0) {
        nominalCaps.push(s.nominal_capacity_ah);
    }

    const balanceCurrent = Number.isFinite(s.balance_current_a)
        ? round(s.balance_current_a, 3)
        : null;
    const balanceActive =
        s.balance_active === true ||
        (balanceCurrent !== null && Math.abs(balanceCurrent) > 0.001);

    balancingDetails.push({
        bms: member,
        active: balanceActive,
        current_a: balanceCurrent
    });

    for (const c of (s.cells || [])) {
        allCells.push({
            bms: member,
            cell: c.index,
            voltage_v: c.voltage_v
        });
    }

    for (const t of (s.temperatures || [])) {
        allTemps.push({
            bms: member,
            sensor: t.sensor,
            value_c: t.value_c
        });
    }
}

function sum(arr) {
    return arr.reduce((a, b) => a + b, 0);
}

function average(arr) {
    return arr.length ? sum(arr) / arr.length : null;
}

const totalRemainingAh = remainingCaps.length ? sum(remainingCaps) : null;
const totalNominalAh = nominalCaps.length ? sum(nominalCaps) : null;

// Capacity-weighted SOC is preferred when every fresh BMS contributes a
// usable nominal capacity. Otherwise fall back to the arithmetic SOC mean.
let weightedSoc = null;
let socMethod = "unavailable";
let weightedSocNumerator = 0;
let weightedSocDenominator = 0;
let weightedSocMembers = 0;

for (const member of members) {
    const s = fresh[member];
    if (
        Number.isFinite(s.soc_pct) &&
        Number.isFinite(s.nominal_capacity_ah) &&
        s.nominal_capacity_ah > 0
    ) {
        weightedSocNumerator += s.soc_pct * s.nominal_capacity_ah;
        weightedSocDenominator += s.nominal_capacity_ah;
        weightedSocMembers += 1;
    }
}

if (weightedSocDenominator > 0 && weightedSocMembers === members.length) {
    weightedSoc = weightedSocNumerator / weightedSocDenominator;
    socMethod = "capacity_weighted";
} else if (socs.length > 0) {
    weightedSoc = average(socs.map(x => x.value));
    socMethod = "arithmetic_mean_fallback";
}

let minCell = null;
let maxCell = null;
for (const c of allCells) {
    if (!minCell || c.voltage_v < minCell.voltage_v) minCell = c;
    if (!maxCell || c.voltage_v > maxCell.voltage_v) maxCell = c;
}

let maxTemp = null;
for (const t of allTemps) {
    if (!maxTemp || t.value_c > maxTemp.value_c) maxTemp = t;
}

const aggregate = {
    step: "13E",
    schema_version: 1,
    access: "free",
    ha_discovery: false,

    pack_id: packId,
    pack_name: packDef.name || msg.pack_name || packId,
    generated_at: new Date(now).toISOString(),
    stale_after_s: STALE_MS / 1000,

    bms_count: members.length,
    members,

    voltage_v: round(average(voltages), 3),
    current_total_a: round(currents.length ? sum(currents) : null, 3),
    power_total_w: round(powers.length ? sum(powers) : null, 1),

    remaining_capacity_total_ah: round(totalRemainingAh, 3),
    nominal_capacity_total_ah: round(totalNominalAh, 3),
    soc_pct: round(weightedSoc, 2),
    soc_method: socMethod,
    soc_lowest_pct: socs.length ? round(Math.min(...socs.map(x => x.value)), 2) : null,
    soc_highest_pct: socs.length ? round(Math.max(...socs.map(x => x.value)), 2) : null,

    soh_average_pct: sohs.length ? round(average(sohs.map(x => x.value)), 2) : null,

    // Active balancing status for the whole pack plus signed current per BMS.
    // Do not sum signed balancing currents: two BMS can legitimately report
    // opposite signs, and a net sum would hide useful information.
    balancing_active: balancingDetails.some(x => x.active === true),
    balancing_active_bms_count: balancingDetails.filter(x => x.active === true).length,
    balancing_details: balancingDetails,

    cell_min_voltage_v: minCell ? round(minCell.voltage_v, 3) : null,
    cell_min_source: minCell ? `BMS_${minCell.bms}/Cell_${minCell.cell}` : null,
    cell_max_voltage_v: maxCell ? round(maxCell.voltage_v, 3) : null,
    cell_max_source: maxCell ? `BMS_${maxCell.bms}/Cell_${maxCell.cell}` : null,
    cell_delta_v: minCell && maxCell
        ? round(maxCell.voltage_v - minCell.voltage_v, 3)
        : null,

    temperature_max_c: maxTemp ? round(maxTemp.value_c, 1) : null,
    temperature_max_source: maxTemp
        ? `BMS_${maxTemp.bms}/${maxTemp.sensor}`
        : null
};

// Keep the latest aggregate available to future Step 13F/13G logic.
let aggregateStore = global.get("jkbms_pack_aggregates") || {};
aggregateStore[packId] = aggregate;
global.set("jkbms_pack_aggregates", aggregateStore);

// ---------------------------------------------------------
// 3. Low-rate retained MQTT validation output.
// No HA Discovery => no Recorder impact.
// ---------------------------------------------------------
const lastPublishTsKey = `multi_pack_aggregate_last_publish_ts_${packId}`;
const previousTs = Number(flow.get(lastPublishTsKey) || 0);
if (previousTs > 0 && (now - previousTs) < MQTT_MIN_INTERVAL_MS) {
    node.status({
        fill: "green",
        shape: "ring",
        text: `${packId}: ${members.length} BMS / aggregate ready`
    });
    return null;
}

flow.set(lastPublishTsKey, now);

const firstLogKey = `multi_pack_aggregate_first_log_${packId}`;
if (flow.get(firstLogKey) !== true) {
