if (global.get("multi_pack_enabled") !== true) {
    return null;
}

const now = Date.now();
const GLOBAL_MQTT_MIN_INTERVAL_MS = 2000;
const DEFAULT_STALE_AFTER_MS = 30000;

function finiteNumber(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function round(v, digits) {
    if (!Number.isFinite(v)) return null;
    const p = Math.pow(10, digits);
    return Math.round((v + Number.EPSILON) * p) / p;
}

function sum(arr) {
    return arr.reduce((a, b) => a + b, 0);
}

function average(arr) {
    return arr.length ? sum(arr) / arr.length : null;
}

function packSort(a, b) {
    const na = Number(String(a).match(/(\d+)$/)?.[1] || 999);
    const nb = Number(String(b).match(/(\d+)$/)?.[1] || 999);
    return na - nb || String(a).localeCompare(String(b));
}

function generatedAtMs(aggregate) {
    const ts = Date.parse(String(aggregate?.generated_at || ""));
    return Number.isFinite(ts) ? ts : 0;
}

function staleAfterMs(aggregate) {
    const s = finiteNumber(aggregate?.stale_after_s);
    return s !== null && s > 0
        ? s * 1000
        : DEFAULT_STALE_AFTER_MS;
}

// ---------------------------------------------------------
// 1. Restrict aggregation to the current runtime topology.
// ---------------------------------------------------------
const runtimePackIdsRaw = global.get("jkbms_pack_ids");
const runtimePackIds = Array.isArray(runtimePackIdsRaw)
    ? [...new Set(runtimePackIdsRaw.map(v => String(v || "").trim()).filter(Boolean))].sort(packSort)
    : [];

if (runtimePackIds.length === 0) return null;

const defs = global.get("jkbms_pack_defs") || {};
const aggregateStore = global.get("jkbms_pack_aggregates") || {};

const online = [];
const offline = [];

for (const packId of runtimePackIds) {
    const a = aggregateStore[packId];
    const ts = generatedAtMs(a);
    const ageMs = ts > 0 ? (now - ts) : Number.POSITIVE_INFINITY;
    const isFresh =
        !!a &&
        a.pack_id === packId &&
        ts > 0 &&
        ageMs >= 0 &&
        ageMs <= staleAfterMs(a);

    if (isFresh) {
        online.push({
            id: packId,
            name: a.pack_name || defs[packId]?.name || packId,
            aggregate: a,
            age_ms: ageMs
        });
    } else {
        offline.push({
            id: packId,
            name: defs[packId]?.name || a?.pack_name || packId,
            last_generated_at: a?.generated_at || null,
            age_s: Number.isFinite(ageMs)
                ? round(ageMs / 1000, 1)
                : null
        });
    }
}

// ---------------------------------------------------------
// 2. Aggregate all ONLINE packs.
// ---------------------------------------------------------
let bmsCount = 0;
const currents = [];
const powers = [];
const remainingCaps = [];
const nominalCaps = [];
const socEntries = [];
const voltageEntries = [];
const cellMinEntries = [];
const cellMaxEntries = [];
const packDeltaEntries = [];
const temperatureEntries = [];

for (const p of online) {
    const a = p.aggregate;

    const count = finiteNumber(a.bms_count);
    if (count !== null && count >= 0) {
        bmsCount += count;
    }

    const current = finiteNumber(a.current_total_a);
    if (current !== null) currents.push(current);

    const power = finiteNumber(a.power_total_w);
    if (power !== null) powers.push(power);

    const remaining = finiteNumber(a.remaining_capacity_total_ah);
    if (remaining !== null && remaining >= 0) remainingCaps.push(remaining);

    const nominal = finiteNumber(a.nominal_capacity_total_ah);
    if (nominal !== null && nominal > 0) nominalCaps.push(nominal);

    const soc = finiteNumber(a.soc_pct);
    if (soc !== null) {
        socEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            soc_pct: soc,
            nominal_capacity_ah: nominal
        });
    }

    const voltage = finiteNumber(a.voltage_v);
    if (voltage !== null && voltage > 0) {
        voltageEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            voltage_v: voltage
        });
    }

    const cellMin = finiteNumber(a.cell_min_voltage_v);
    if (cellMin !== null && cellMin > 0) {
        cellMinEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            voltage_v: cellMin,
            source: a.cell_min_source || null
        });
    }

    const cellMax = finiteNumber(a.cell_max_voltage_v);
    if (cellMax !== null && cellMax > 0) {
        cellMaxEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            voltage_v: cellMax,
            source: a.cell_max_source || null
        });
    }

    const packDelta = finiteNumber(a.cell_delta_v);
    if (packDelta !== null && packDelta >= 0) {
        packDeltaEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            delta_v: packDelta
        });
    }

    const temperature = finiteNumber(a.temperature_max_c);
    if (temperature !== null) {
        temperatureEntries.push({
            pack_id: p.id,
            pack_name: p.name,
            temperature_c: temperature,
            source: a.temperature_max_source || null
        });
    }
}

function minBy(arr, field) {
    if (!arr.length) return null;
    return arr.reduce((best, cur) => cur[field] < best[field] ? cur : best);
}

function maxBy(arr, field) {
    if (!arr.length) return null;
    return arr.reduce((best, cur) => cur[field] > best[field] ? cur : best);
}

const lowestSoc = minBy(socEntries, "soc_pct");
const highestSoc = maxBy(socEntries, "soc_pct");
const lowestVoltage = minBy(voltageEntries, "voltage_v");
const highestVoltage = maxBy(voltageEntries, "voltage_v");
const globalMinCell = minBy(cellMinEntries, "voltage_v");
const globalMaxCell = maxBy(cellMaxEntries, "voltage_v");
const highestPackCellDelta = maxBy(packDeltaEntries, "delta_v");
const highestTemperature = maxBy(temperatureEntries, "temperature_c");

// Prefer capacity-weighted SOC across packs when every online pack with a SOC
// also provides a nominal capacity. Otherwise use the arithmetic mean.
let averageSoc = null;
let socMethod = "unavailable";

if (socEntries.length > 0) {
    const allWeighted = socEntries.every(
        x => Number.isFinite(x.nominal_capacity_ah) && x.nominal_capacity_ah > 0
    );

    if (allWeighted) {
        const denominator = sum(socEntries.map(x => x.nominal_capacity_ah));
        if (denominator > 0) {
            averageSoc = sum(
                socEntries.map(x => x.soc_pct * x.nominal_capacity_ah)
            ) / denominator;
            socMethod = "capacity_weighted";
        }
    }

    if (averageSoc === null) {
        averageSoc = average(socEntries.map(x => x.soc_pct));
        socMethod = "arithmetic_mean_fallback";
    }
}

function qualifySource(packEntry, source) {
    if (!packEntry) return null;
    return source
        ? `${packEntry.pack_id}/${source}`
        : packEntry.pack_id;
}

const globalAggregate = {
