    lowest_voltage_pack: lowestVoltage ? lowestVoltage.pack_id : null,
    highest_pack_voltage_v: highestVoltage ? round(highestVoltage.voltage_v, 3) : null,
    highest_voltage_pack: highestVoltage ? highestVoltage.pack_id : null,
    pack_voltage_delta_v: lowestVoltage && highestVoltage
        ? round(highestVoltage.voltage_v - lowestVoltage.voltage_v, 3)
        : null,

    global_min_cell_voltage_v: globalMinCell ? round(globalMinCell.voltage_v, 3) : null,
    global_min_cell_source: globalMinCell
        ? qualifySource(globalMinCell, globalMinCell.source)
        : null,
    global_max_cell_voltage_v: globalMaxCell ? round(globalMaxCell.voltage_v, 3) : null,
    global_max_cell_source: globalMaxCell
        ? qualifySource(globalMaxCell, globalMaxCell.source)
        : null,
    global_cell_delta_v: globalMinCell && globalMaxCell
        ? round(globalMaxCell.voltage_v - globalMinCell.voltage_v, 3)
        : null,

    highest_pack_cell_delta_v: highestPackCellDelta
        ? round(highestPackCellDelta.delta_v, 3)
        : null,
    highest_cell_delta_pack: highestPackCellDelta
        ? highestPackCellDelta.pack_id
        : null,

    temperature_max_c: highestTemperature
        ? round(highestTemperature.temperature_c, 1)
        : null,
    temperature_max_source: highestTemperature
        ? qualifySource(highestTemperature, highestTemperature.source)
        : null,

    pack_freshness: online.map(p => ({
        pack_id: p.id,
        age_s: round(p.age_ms / 1000, 1)
    })),
    offline_details: offline
};

// Latest global state for future Step 13G Premium diagnostics.
global.set("jkbms_global_aggregate", globalAggregate);

// ---------------------------------------------------------
