        `${bmsCount} BMS, SOC=${globalAggregate.average_soc_pct}%, ` +
        `I=${globalAggregate.total_current_a}A, ` +
        `P=${globalAggregate.total_power_w}W`
    );
}

node.status({
    fill: online.length === runtimePackIds.length ? "green" : "yellow",
    shape: "dot",
    text: `${online.length}/${runtimePackIds.length} packs / ${bmsCount} BMS`
