// via l'observateur brut 15 minutes retained, hors HA Discovery.

// ----------------------------------------------------------
// Step 12C.3 - statut compact de l'observateur brut 15 minutes
// ----------------------------------------------------------
const rawObserver15mKey = `mqtt_raw_observer_15m_${packId}`;
const rawObserver15m = flow.get(rawObserver15mKey) || {};
const rawObserverWindowStartTs = Number(rawObserver15m.window_start_ts || 0);
const rawObserverElapsedS = rawObserverWindowStartTs > 0
    ? Math.max(0, Number(((now - rawObserverWindowStartTs) / 1000).toFixed(1)))
    : 0;
const rawObserverBmsSeen = Object.keys(rawObserver15m.bms_seen || {}).sort((a, b) => {
    if (a === "master") return -1;
    if (b === "master") return 1;
    return Number(a) - Number(b);
});

function sumObserverPairs(rawMap) {
    return Object.values(rawMap || {}).reduce(
        (sum, raw) => sum + Number((raw || {}).pairs || 0),
        0
    );
}

const rawObserverCurrentPairs = sumObserverPairs(rawObserver15m.metrics || {});
const rawObserverCellRaw = (rawObserver15m.metrics || {}).Cell_voltage_all || {};

const isTcp = s.transport === "tcp";
const isSerial = s.transport === "serial";

let status = "starting";
let health_reason = "waiting_for_serial_data";
let health_flags = [];
let transport_info = [];

// ----------------------------------------------------------
// Fundamental traffic health
// ----------------------------------------------------------
if (serialAge !== null) {
    if (serialAge >= 30) {
        status = "no_serial_data";
        health_reason = "serial_timeout";
        health_flags.push("serial_stale");
    } else if (serialAge >= 10) {
        status = "degraded";
        health_reason = "serial_slow";
        health_flags.push("serial_slow");
    } else {
        status = "healthy";
        health_reason = "healthy";
    }

    // ------------------------------------------------------
    // TCP broadcasting: parser-aware interpretation.
    //
    // short buffers and concatenated buffers are NORMAL stream
    // properties when every byte is reconstructed into valid
    // protocol frames. They remain visible in transport_info.
    // ------------------------------------------------------
    if (isTcp) {
        if (Number(s.short_buffers_30s || 0) > 0) {
            transport_info.push("tcp_short_chunks_present");
        }

        if (
            Number(s.multi_header_buffers_30s || 0) > 0 ||
            coalescedBuffers > 0
        ) {
            transport_info.push("tcp_coalescing_present");
        }

        if (framesPerInputBuffer > 1) {
            transport_info.push("multiple_frames_per_input_buffer");
        }

        if (partialWaits > 0) {
            transport_info.push("tcp_fragmentation_reassembled");
        }

        // True parser failures.
        if (buffers30s > 0 && framesEmitted === 0) {
            if (status === "healthy") status = "degraded";
            health_reason = "no_valid_frames_emitted";
            health_flags.push("parser_no_output");
        }

        // Discarded bytes indicate resynchronisation. A tiny isolated amount
        // is reported; sustained loss degrades health.
        if (discardedBytes > 0) {
            if (discardedByteRatio >= 0.01 || discardedBytes >= 64) {
                if (status === "healthy") status = "degraded";
                health_reason = "stream_resynchronisation_loss";
                health_flags.push("discarded_stream_bytes");
            } else {
                transport_info.push("minor_stream_resynchronisation");
            }
        }

        // A large unconsumed tail is suspicious. A few bytes are normal when
        // the 30-second snapshot lands in the middle of a TCP frame.
        if (tailBytes >= 1024) {
            if (status === "healthy") status = "degraded";
            health_reason = "large_unparsed_tail";
            health_flags.push("large_unparsed_tail");
        } else if (tailBytes > 0) {
            transport_info.push("partial_frame_pending");
        }

        // If traffic is flowing but a significant portion of bytes has not
        // yet been emitted and this is not explained by the current tail,
        // mark it as suspicious. Allow generous tolerance for snapshot timing.
        const accountedBytes = emittedFrameBytes + tailBytes + discardedBytes;
        const accountingRatio = bytes30s > 0
            ? accountedBytes / bytes30s
            : 1;

        if (
            bytes30s >= 1000 &&
            framesEmitted > 0 &&
            accountingRatio < 0.95
        ) {
            if (status === "healthy") status = "degraded";
            health_reason = "unaccounted_stream_bytes";
            health_flags.push("unaccounted_stream_bytes");
        }
    } else {
        // --------------------------------------------------
        // Direct serial: retain the historical heuristics.
        // --------------------------------------------------
        const fullFrameSeen = (s.max_len_30s || 0) >= 300;
        const cleanFraming =
            framesEmitted > 0 &&
            frameYieldRatio >= 0.90 &&
            fullFrameSeen;

        if (
            buffers30s > 0 &&
            bytesPerBufferAvg < 35 &&
            !cleanFraming
        ) {
            if (status === "healthy") status = "degraded";
            health_reason = "excessive_fragmentation";
            health_flags.push("low_avg_buffer_len");
        }

        if (Number(s.frame_candidates_30s || 0) > 0 && framesEmitted === 0) {
            if (status === "healthy") status = "degraded";
            health_reason = "no_valid_frames_emitted";
            health_flags.push("parser_no_output");
        } else if (
            Number(s.frame_candidates_30s || 0) >= 10 &&
            frameYieldRatio < 0.50
        ) {
            if (status === "healthy") status = "degraded";
            health_reason = "low_frame_yield";
            health_flags.push("low_frame_yield");
        }

        if (Number(s.multi_header_buffers_30s || 0) > 40) {
            transport_info.push("serial_multi_header_buffers");
        }

        if (
            status === "healthy" &&
            Number(s.short_buffers_30s || 0) > 0 &&
            Number(s.short_buffers_30s || 0) >= Math.round(buffers30s * 0.75)
        ) {
            health_flags.push("many_short_buffers");
        }
    }

    // ------------------------------------------------------
    // Healthy broadcasting classification.
    // For TCP this depends on parser output and byte integrity,
    // not packet/chunk shape.
    // ------------------------------------------------------
    const tcpParserHealthy =
        !isTcp ||
        (
            framesEmitted > 0 &&
            discardedByteRatio < 0.01 &&
            discardedBytes < 64 &&
            tailBytes < 1024
        );

    if (
        status === "healthy" &&
        ["serial", "tcp"].includes(s.transport) &&
        buffers30s >= 10 &&
        framesEmitted > 0 &&
        serialAge < 0.5 &&
        tcpParserHealthy
    ) {
        if (s.detected_bms >= 2) {
            health_reason = "healthy_multi_bms_broadcast";
        } else if (s.detected_bms === 1) {
            health_reason = "healthy_single_bms_broadcast";
        } else {
            health_reason = "healthy_broadcast";
        }
    }
}

// ----------------------------------------------------------
// Score
// ----------------------------------------------------------
const monitoringUptimeS = Math.max(
    0,
    Math.round((now - Number(s.first_ts || now)) / 1000)
);

let healthScore = null;
let healthScoreLabel = "starting";

if (serialAge !== null) {
    healthScore = 100;

    if (serialAge >= 30) {
        healthScore = 10;
    } else if (serialAge >= 10) {
        healthScore -= 40;
    } else if (serialAge >= 0.5) {
        healthScore -= 10;
    }

    if (isTcp) {
        if (framesEmitted === 0 && buffers30s > 0) {
            healthScore -= 50;
        }

        if (discardedBytes > 0) {
            const discardPenalty =
                discardedByteRatio >= 0.05 ? 35 :
                discardedByteRatio >= 0.01 ? 20 :
                discardedBytes >= 64 ? 15 :
                0;
            healthScore -= discardPenalty;
        }

        if (tailBytes >= 4096) healthScore -= 30;
        else if (tailBytes >= 1024) healthScore -= 15;

        const accountedBytes = emittedFrameBytes + tailBytes + discardedBytes;
        const accountingRatio = bytes30s > 0
            ? accountedBytes / bytes30s
            : 1;

        if (bytes30s >= 1000 && framesEmitted > 0 && accountingRatio < 0.95) {
            healthScore -= Math.round((0.95 - accountingRatio) * 100);
        }
    } else {
        // Preserve historical serial score logic.
        if (Number(s.frame_candidates_30s || 0) > 0) {
            healthScore -= Math.round(
                Math.max(0, 0.90 - frameYieldRatio) * 60
            );
        }

        if (
            Number(s.frame_candidates_30s || 0) > 0 &&
            framesEmitted === 0
        ) {
            healthScore -= 50;
        }

        if ((s.max_len_30s || 0) < 300 && framesEmitted > 0) {
            healthScore -= 10;
        }
    }

    if (status === "no_serial_data") {
        healthScore = Math.min(healthScore, 20);
    }

    healthScore = Math.max(0, Math.min(100, Math.round(healthScore)));

    if (healthScore >= 95) healthScoreLabel = "excellent";
    else if (healthScore >= 90) healthScoreLabel = "good";
    else if (healthScore >= 70) healthScoreLabel = "degraded";
    else healthScoreLabel = "critical";
}

function buildScoreDetail() {
    const parts = [];

    if (serialAge !== null && serialAge >= 0.5) {
        parts.push(`traffic age reached ${serialAge} s`);
    }

    if (isTcp) {
        if (discardedBytes > 0) {
            parts.push(
                `${discardedBytes} stream byte(s) discarded ` +
                `(${(discardedByteRatio * 100).toFixed(2)}%)`
            );
        }

        if (tailBytes >= 1024) {
            parts.push(`${tailBytes} unparsed tail bytes pending`);
        }

        if (buffers30s > 0 && framesEmitted === 0) {
            parts.push("input traffic received but no valid protocol frame emitted");
        }

        if (health_flags.includes("unaccounted_stream_bytes")) {
            parts.push("some received stream bytes were not accounted for by frames/tail/resync");
        }
    } else {
        if (
            Number(s.frame_candidates_30s || 0) > 0 &&
            frameYieldRatio < 0.90
        ) {
            parts.push(`frame yield ratio ${frameYieldRatio}`);
        }

        if (
            Number(s.frame_candidates_30s || 0) > 0 &&
            framesEmitted === 0
        ) {
            parts.push("no valid JK-BMS frame emitted");
        }

        if ((s.max_len_30s || 0) < 300 && framesEmitted > 0) {
            parts.push(
                `no full 300+ byte frame seen; maximum ${s.max_len_30s || 0} bytes`
            );
        }
    }

    if (health_flags.length > 0) {
        parts.push(`flags: ${health_flags.join(", ")}`);
    }

    if (!parts.length && healthScore !== null && healthScore < 100) {
        parts.push(
            "minor transient penalty while broadcast communication remained healthy"
        );
    }

    if (!parts.length) {
        parts.push("no communication fault detected");
    }

    return parts.join("; ");
}

const currentScoreDetail = buildScoreDetail();

if (healthScore !== null) {
    if (s.worst_health_score === null) {
        s.worst_health_score = healthScore;
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    } else if (healthScore < s.worst_health_score) {
        s.worst_health_score = healthScore;
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    } else if (
        healthScore === s.worst_health_score &&
        status !== "healthy" &&
        health_reason !== s.worst_health_reason
    ) {
        s.worst_health_reason = health_reason;
        s.worst_health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
        s.worst_score_detail = currentScoreDetail;
        s.worst_health_ts = now;
    }
}

const previousWasHealthy = ["healthy", "starting"].includes(s.previous_health_status);
const currentIsIncident = !["healthy", "starting"].includes(status);
if (previousWasHealthy && currentIsIncident) {
    s.health_incident_count += 1;
}
s.previous_health_status = status;

const worstHealthAgeS = s.worst_health_ts
    ? Number(((now - s.worst_health_ts) / 1000).toFixed(1))
    : null;

const health_flags_text = health_flags.length ? health_flags.join(", ") : "none";
const healthReasonText = humanReason(health_reason);
const worstHealthReasonText = humanReason(s.worst_health_reason || health_reason);
const monitoringUptimeHuman = formatDuration(monitoringUptimeS);

msg.pack_id = packId;
msg.pack_name = packName;
msg.bus_id = busId;

msg.topic = multiPack
    ? `jkbms/${packId}/BMS_GLOBAL/health`
    : "BMS_GLOBAL/health";
msg.payload = {
    pack_id: packId,
    pack_name: packName,
    pack_slot: packSlot,
    bus_id: busId,
    gateway_endpoint: gatewayEndpoint,
    gateway_ip: multiPack ? (def.host || null) : (global.get("gateway_ip") || null),
    gateway_port: multiPack ? (def.port || null) : (global.get("gateway_port") || null),
    status,
    health_reason,
    health_reason_text: healthReasonText,
    health_flags,
    health_flags_text,
    serial_age_s: serialAge,
    buffers_30s: s.buffers_30s,
    frame_candidates_30s: s.frame_candidates_30s,
    frames_emitted_30s: framesEmitted,
    // Historical metric kept for compatibility. It can exceed 1 on TCP.
    frame_yield_ratio: frameYieldRatio,

    // Normalized transport metrics.
    frames_per_input_buffer: framesPerInputBuffer,
    parsed_byte_ratio: parsedByteRatio,
    discarded_byte_ratio: discardedByteRatio,
    short_buffer_ratio: shortBufferRatio,
    multi_header_buffer_ratio: multiHeaderRatio,
    coalesced_buffer_ratio: coalescedBufferRatio,
    transport_info,
    transport_info_text: transport_info.length
        ? transport_info.join(", ")
        : "none",

    short_buffers_30s: s.short_buffers_30s,
    multi_header_buffers_30s: s.multi_header_buffers_30s,
    last_len: s.last_len,
    avg_len_30s: avgLen,
    bytes_per_buffer_avg_30s: bytesPerBufferAvg,
    max_len_30s: s.max_len_30s,
    bytes_30s: s.bytes_30s,
    emitted_frame_bytes_30s: emittedFrameBytes,
    avg_frame_len_30s: avgFrameLen,

    // Stream-framer diagnostics
    framer_discarded_bytes_30s: Number(s.framer_discarded_bytes_30s || 0),
    framer_partial_waits_30s: Number(s.framer_partial_waits_30s || 0),
    framer_exact_308_frames_30s: Number(s.framer_exact_308_frames_30s || 0),
    framer_valid_jk_frames_30s: validJkFrames,
    framer_valid_modbus_polls_30s: validModbusPolls,
    framer_coalesced_buffers_30s: coalescedBuffers,
    framer_large_chunks_30s: Number(s.framer_large_chunks_30s || 0),
    framer_tail_bytes: Number(s.framer_tail_bytes || 0),
    framer_last_input_len: Number(s.framer_last_input_len || 0),
    framer_max_input_len: Number(s.framer_max_input_len || 0),

    transport: s.transport || "unknown",
    mode: "broadcast",
    detected_bms: s.detected_bms || 0,
    detected_bms_list: s.detected_bms_list || "",
    detected_bms_ids: detectedIds,
    detected_bms_slave_count: detectedIds.filter(n => n !== 0).length,
    detected_bms_source: detectedSource,

    // Recorder Protection / MQTT DATA publication
    mqtt_change_only_enabled:
        multiPack && global.get("bms_broadcasting") === true,
    mqtt_data_candidates_30s: mqttDataCandidates30s,
    mqtt_data_published_30s: mqttDataPublished30s,
    mqtt_data_suppressed_30s: mqttDataSuppressed30s,
    mqtt_data_throttled_30s: mqttDataThrottled30s,
    mqtt_data_deadband_held_30s: mqttDataDeadbandHeld30s,
    mqtt_data_deadband_published_30s: mqttDataDeadbandPublished30s,
    mqtt_data_midband_held_30s: mqttDataMidbandHeld30s,
    mqtt_data_midband_published_30s: mqttDataMidbandPublished30s,
    mqtt_data_forced_30s: mqttDataForced30s,
    mqtt_data_publish_ratio: mqttPublishRatio,
    mqtt_data_suppression_ratio: mqttSuppressionRatio,
    mqtt_data_throttle_ratio: mqttThrottleRatio,
    mqtt_data_deadband_hold_ratio: mqttDeadbandHoldRatio,
    mqtt_data_midband_hold_ratio: mqttMidbandHoldRatio,
    mqtt_data_reduction_ratio: mqttReductionRatio,
    mqtt_data_candidates_total: Number(publishStats.candidates_total || 0),
    mqtt_data_published_total: Number(publishStats.published_total || 0),
    mqtt_data_suppressed_total: Number(publishStats.suppressed_total || 0),
    mqtt_data_throttled_total: Number(publishStats.throttled_total || 0),
    mqtt_data_deadband_held_total: Number(publishStats.deadband_held_total || 0),
    mqtt_data_deadband_published_total: Number(publishStats.deadband_published_total || 0),
    mqtt_data_midband_held_total: Number(publishStats.midband_held_total || 0),
    mqtt_data_midband_published_total: Number(publishStats.midband_published_total || 0),
    mqtt_data_forced_total: Number(publishStats.forced_total || 0),

    mqtt_time_governor_enabled:
        multiPack && global.get("bms_broadcasting") === true,
    mqtt_time_governor_policy_s: {
        Total_runtime: 60,
        Total_runtime_formatted: 60,
        Cycle_Capacite_Ah: 30,
        Capacite_restante_Ah: 10,
        charge_status_time: 30,
        charge_status_time_formatted: 30,
        cell_voltage_min_number: 30,
        cell_voltage_max_number: 30
    },

    // Step 12C / 12D / 12E - politique hybride tensions cellules
    mqtt_cell_voltage_filter_enabled:
        multiPack && global.get("bms_broadcasting") === true,
    mqtt_cell_voltage_deadband_v: 0.002,
    mqtt_cell_voltage_immediate_threshold_v: 0.005,
    mqtt_cell_voltage_midband_min_interval_s: 5,
    mqtt_cell_voltage_max_interval_s: 30,
    mqtt_cell_voltage_delta_max_interval_s: 15,

    // Step 12F - production diagnostics cleanup
    mqtt_diagnostics_profile_mode: "production_compact",
    mqtt_detailed_30s_profiles_enabled: false,

    // Step 12C.3 / 12D / 12E / 12F - compact long raw observer status only. Detailed completed report
    // is retained on MQTT diagnostic topic and is intentionally not a HA entity.
    mqtt_raw_observer_15m_enabled:
        multiPack && global.get("bms_broadcasting") === true,
    mqtt_raw_observer_15m_basis:
        "consecutive_raw_data_values_before_mqtt_filters",
    mqtt_raw_observer_15m_window_s: 900,
    mqtt_raw_observer_15m_elapsed_s: rawObserverElapsedS,
    mqtt_raw_observer_15m_bms_seen: rawObserverBmsSeen,
    mqtt_raw_observer_15m_pairs_current: rawObserverCurrentPairs,
    mqtt_raw_observer_15m_cell_pairs_current:
        Number(rawObserverCellRaw.pairs || 0),
    mqtt_raw_observer_15m_cell_changed_current:
        Number(rawObserverCellRaw.changed || 0),
    mqtt_raw_observer_15m_last_complete_ts:
        Number(rawObserver15m.last_complete_ts || 0) || null,
    mqtt_raw_observer_15m_last_complete_topic:
        `jkbms/${packId}/diagnostics/raw_observer_15m`,

    health_score: healthScore,
    health_score_label: healthScoreLabel,
    worst_health_score: s.worst_health_score,
    worst_health_reason: s.worst_health_reason || "none",
    worst_health_reason_text: worstHealthReasonText,
    worst_health_flags_text: s.worst_health_flags_text || "none",
    worst_score_detail: s.worst_score_detail || "no communication fault detected",
    worst_health_age_s: worstHealthAgeS,
    health_incident_count: s.health_incident_count,
    monitoring_uptime_s: monitoringUptimeS,
    monitoring_uptime_human: monitoringUptimeHuman,
    total_timeouts: null,
    last_timeout_age_s: null,
    no_timeout_duration_s: null,
    per_bms_summary_markdown: null,

    // Explicitly clear active-polling-only attributes when the mode changes.
    configured_bms: null,
    configured_bms_list: null,
    responding_bms: null,
    responding_bms_list: null,
    missing_bms: null,
    missing_bms_list: null,
    polls_sent_30s: null,
    responses_received_30s: null,
    valid_responses_30s: null,
    timeouts_30s: null,
    invalid_responses_30s: null,
    response_success_ratio: null,
    avg_response_time_ms: null,
    max_response_time_ms: null,
    last_poll_age_s: null,
    last_response_age_s: null,
    last_valid_response_age_s: null,
    pending_transactions: null,

    ts: now
};

// Reset uniquement la fenêtre MQTT de 30 secondes.
// Les totaux cumulatifs restent disponibles pour les tests longs.
flow.set(publishStatsKey, {
    candidates_30s: 0,
    published_30s: 0,
    suppressed_30s: 0,
    throttled_30s: 0,
    deadband_held_30s: 0,
    deadband_published_30s: 0,
    midband_held_30s: 0,
    midband_published_30s: 0,
    forced_30s: 0,
    candidates_total: Number(publishStats.candidates_total || 0),
    published_total: Number(publishStats.published_total || 0),
    suppressed_total: Number(publishStats.suppressed_total || 0),
    throttled_total: Number(publishStats.throttled_total || 0),
    deadband_held_total: Number(publishStats.deadband_held_total || 0),
    deadband_published_total: Number(publishStats.deadband_published_total || 0),
    midband_held_total: Number(publishStats.midband_held_total || 0),
    midband_published_total: Number(publishStats.midband_published_total || 0),
    forced_total: Number(publishStats.forced_total || 0)
});

flow.set(diagKey, {
    first_ts: s.first_ts || now,
    last_serial_rx_ts: s.last_serial_rx_ts || 0,
    buffers_30s: 0,
    bytes_30s: 0,
    short_buffers_30s: 0,
    multi_header_buffers_30s: 0,
    frame_candidates_30s: 0,
    frames_emitted_30s: 0,
    emitted_frame_bytes_30s: 0,

    // Reset rolling framer counters while preserving instantaneous/max context.
    framer_discarded_bytes_30s: 0,
    framer_partial_waits_30s: 0,
    framer_exact_308_frames_30s: 0,
    framer_valid_jk_frames_30s: 0,
    framer_valid_modbus_polls_30s: 0,
    framer_coalesced_buffers_30s: 0,
    framer_large_chunks_30s: 0,
    framer_tail_bytes: Number(s.framer_tail_bytes || 0),
    framer_last_input_len: Number(s.framer_last_input_len || 0),
    framer_max_input_len: Number(s.framer_max_input_len || 0),

    last_len: s.last_len || 0,
    sum_len_30s: 0,
    max_len_30s: 0,
    transport: s.transport || "unknown",
    detected_bms_seen: seen,
    detected_bms: detectedList.length,
    detected_bms_list: detectedList.join(", "),
    worst_health_score: s.worst_health_score,
    worst_health_reason: s.worst_health_reason || "",
    worst_health_flags_text: s.worst_health_flags_text || "none",
    worst_score_detail: s.worst_score_detail || "",
    worst_health_ts: s.worst_health_ts || 0,
    health_incident_count: s.health_incident_count || 0,
    previous_health_status: s.previous_health_status || status
});

return msg;

const multiPack = global.get("multi_pack_enabled") === true;
const packId = msg.pack_id || "pack_1";

// Defensive Legacy guard: generic fan-out emits only pack_1 in Legacy.
if (!multiPack && packId !== "pack_1") {
    return null;
}

const defs = global.get("jkbms_pack_defs") || {};
const def = defs[packId] || {};
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");

if (!multiPack) {
    // v4.2.52 - Legacy cleanup of retained Multi-Pack Health entities.
    // A previous Multi-Pack run can leave pack_1..pack_5 Health Discovery
    // and retained Health states in MQTT. Remove them before publishing the
    // canonical Legacy BMS_GLOBAL Health entity.
    const out = [];

    for (let i = 1; i <= 5; i++) {
        const stalePackId = `pack_${i}`;
        const staleDeviceId = `${stalePackId}_BMS_GLOBAL_device`;

        out.push({
            topic: `homeassistant/sensor/${staleDeviceId}/health/config`,
            payload: "",
            retain: true
        });

        // Compact HA-facing Health state.
        out.push({
