function modbusCRC(buffer, start, length) {
    let crc = 0xFFFF;
    for (let i = start; i < start + length; i++) {
        crc ^= buffer[i];
        for (let j = 0; j < 8; j++) {
            if (crc & 0x0001) crc = (crc >> 1) ^ 0xA001;
            else crc >>= 1;
