    if (!(addr >= 1 && addr <= 15)) return false;
    if (buffer[pos + 1] !== 0x10) return false;
    if (buffer[pos + 2] !== 0x16) return false;
    if (!(buffer[pos + 3] === 0x20 || buffer[pos + 3] === 0x1E)) return false;
    if (buffer[pos + 4] !== 0x00 || buffer[pos + 5] !== 0x01) return false;
    if (buffer[pos + 6] !== 0x02) return false;
    if (buffer[pos + 7] !== 0x00 || buffer[pos + 8] !== 0x00) return false;

    const crc = modbusCRC(buffer, pos, 9);
    return (
        buffer[pos + 9] === (crc & 0xFF) &&
        buffer[pos + 10] === ((crc >> 8) & 0xFF)
