    if (remaining >= 5 && buffer[pos + 4] !== 0x00) return false;
    if (remaining >= 6 && buffer[pos + 5] !== 0x01) return false;
    if (remaining >= 7 && buffer[pos + 6] !== 0x02) return false;
    if (remaining >= 8 && buffer[pos + 7] !== 0x00) return false;
    if (remaining >= 9 && buffer[pos + 8] !== 0x00) return false;

    return true;
}

const JK_HEADER = [0x55, 0xAA, 0xEB, 0x90];

