        flow.set(`lastSetup_${packId}_BMS_master`, {});
        flow.set(`forceSetupRepublish_${packId}_BMS_master`, true);
    }

    for (const i of info.ids) {
        if (activePolling) {
            flow.set(`apSetupSent_${packId}_BMS_${i}`, false);
            flow.set(`apLastSetup_${packId}_BMS_${i}`, {});
        } else {
