//   when the runtime/license is not applicable.
// =========================================================

const TOPIC = "jkbms/global/premium_diagnostics";
const FEATURE = "multi_pack_diagnostics";
const STARTUP_GRACE_MS = 30000;

const THRESHOLDS = Object.freeze({
    cell_delta_high_v: 0.050,
    temperature_high_c: 50.0
});

function finiteNumber(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function round(v, digits) {
    if (!Number.isFinite(v)) return null;
    const p = Math.pow(10, digits);
    return Math.round((v + Number.EPSILON) * p) / p;
}

function parsePayload(payload) {
    if (payload && typeof payload === "object" && !Buffer.isBuffer(payload)) {
        return payload;
    }
    if (typeof payload === "string" && payload.trim()) {
        try {
            return JSON.parse(payload);
        } catch (e) {
            return null;
        }
    }
    return null;
}

function packSort(a, b) {
    const na = Number(String(a).match(/(\d+)$/)?.[1] || 999);
    const nb = Number(String(b).match(/(\d+)$/)?.[1] || 999);
    return na - nb || String(a).localeCompare(String(b));
}

function packName(packId) {
    const defs = global.get("jkbms_pack_defs") || {};
    return defs?.[packId]?.name || packId || null;
}

// ---------------------------------------------------------
// SCADA CENTRAL ALARM LIFECYCLE (dev53)
// Persisted in Node-RED global context (localfilesystem).
// ---------------------------------------------------------
const SCADA_HISTORY_MAX = 120;
const SCADA_HISTORY_EXPOSE = 40;

function scadaLifecycleRows(activeIssues) {
    const rows = [];
    for (const issue of activeIssues) {
        if (!issue || !issue.code) continue;
        if (issue.code === "PACK_OFFLINE") {
            for (const packId of (Array.isArray(issue.packs) ? issue.packs : [])) {
                rows.push({
                    key: `${packId}:PACK_OFFLINE`, code: "PACK_OFFLINE", severity: "ALARME",
                    category: "Communication", pack_id: packId, pack_name: packName(packId),
                    value: "OFFLINE", threshold: "Pack communicant requis",
                    message: `${packName(packId)} is offline or stale.`,
                    recommendation: `Check ${packName(packId)} TCP/RS485 transport, BMS power and telemetry freshness.`
                });
            }
        } else if (issue.code === "TEMPERATURE_HIGH") {
            const packId = issue.pack_id || null;
            rows.push({
                key: `${packId}:TEMPERATURE_HIGH`, code: "TEMPERATURE_HIGH", severity: "ATTENTION",
                category: "Température", pack_id: packId, pack_name: packName(packId),
                value: `${issue.value_c ?? "—"} °C`, threshold: `${issue.threshold_c ?? THRESHOLDS.temperature_high_c} °C`,
                message: issue.message || "High pack temperature.",
                recommendation: `Check load, cooling and BMS temperature sources on ${packName(packId)}.`
            });
        } else if (issue.code === "CELL_DELTA_HIGH") {
            const packId = issue.pack_id || null;
            rows.push({
                key: `${packId}:CELL_DELTA_HIGH`, code: "CELL_DELTA_HIGH", severity: "ATTENTION",
                category: "Cellules", pack_id: packId, pack_name: packName(packId),
                value: `${issue.value_mv ?? "—"} mV`, threshold: `${Math.round((issue.threshold_v ?? THRESHOLDS.cell_delta_high_v) * 1000)} mV`,
                message: issue.message || "High cell delta.",
                recommendation: `Check cell balance and individual cell voltages on ${packName(packId)}.`
            });
        }
    }
    return rows;
}

function syncScadaLifecycle(rows, now) {
    let store = global.get("jkbms_scada_alarm_lifecycle") || { active: {}, history: [] };
    if (!store || typeof store !== "object") store = { active: {}, history: [] };
    if (!store.active || typeof store.active !== "object" || Array.isArray(store.active)) store.active = {};
    if (!Array.isArray(store.history)) store.history = [];
    let ackMap = global.get("jkbms_scada_alarm_ack") || {};
    if (!ackMap || typeof ackMap !== "object" || Array.isArray(ackMap)) ackMap = {};

    const current = new Set();
    for (const row of rows) {
        const key = String(row.key || "");
        if (!key) continue;
        current.add(key);
        let ev = store.active[key];
        if (!ev) {
            ev = { id: `${key}:${now}`, key, first_seen: now, ack_at: null };
            store.active[key] = ev;
        }
        Object.assign(ev, row, { last_seen: now });
        if (ackMap[key] && Number.isFinite(Number(ackMap[key].at))) ev.ack_at = Number(ackMap[key].at);
    }

    for (const key of Object.keys(store.active)) {
        if (current.has(key)) continue;
        const ev = store.active[key];
        const clearedAt = now;
        const rec = { ...ev, cleared_at: clearedAt, ack_at: ev.ack_at || ackMap[key]?.at || null };
        if (!store.history.some(x => x && x.id === rec.id)) store.history.unshift(rec);
        delete store.active[key];
        delete ackMap[key];
    }

    store.history = store.history.slice(0, SCADA_HISTORY_MAX);
    global.set("jkbms_scada_alarm_lifecycle", store);
    global.set("jkbms_scada_alarm_ack", ackMap);

    return {
        source: "node_red",
        schema_version: 1,
        max_history: SCADA_HISTORY_MAX,
        history_count: store.history.length,
        active: Object.values(store.active).sort((a,b) => Number(a.first_seen||0) - Number(b.first_seen||0)),
        history: store.history.slice(0, SCADA_HISTORY_EXPOSE)
    };
}

// ---------------------------------------------------------
// 0. Canonical Premium gate + retained cleanup.
// ---------------------------------------------------------
const runtimeMode = String(
    global.get("premium.runtime_mode") ||
    global.get("jkbms_runtime_mode") ||
    "legacy"
).trim().toLowerCase();

const features = global.get("premium.features") || {};
const entitled = features[FEATURE] === true;
const applicable =
    runtimeMode === "multi_pack" &&
    global.get("premium.multi_pack_premium_available") === true;

const allowed = entitled && applicable;

if (!allowed) {
    node.status({
        fill: entitled ? "blue" : "grey",
        shape: "ring",
        text: entitled ? "not applicable" : "premium required"
    });

    // Startup-only retained cleanup: remove a diagnostic left by a previous
    // Premium Multi-Pack run when we are now Legacy or Free.
    if (msg && msg._step13g_startup_cleanup === true) {
        return {
            topic: TOPIC,
            payload: "",
            retain: true
        };
    }

    return null;
}

// While Premium Multi-Pack is active, the startup inject only clears an old
// retained diagnostic if this runtime has not produced a fresh diagnostic yet.
// It must never erase a diagnostic already published by the current runtime.
if (msg && msg._step13g_startup_cleanup === true) {
    if (flow.get("step13g_has_current_run_diagnostic") === true) {
        return null;
    }

    return {
        topic: TOPIC,
        payload: "",
        retain: true
    };
}

// ---------------------------------------------------------
// 1. Input: Step 13F aggregate (or canonical global fallback).
// ---------------------------------------------------------
let aggregate = parsePayload(msg.payload);
if (!aggregate || aggregate.step !== "13F") {
    aggregate = global.get("jkbms_global_aggregate") || null;
}

if (!aggregate || aggregate.step !== "13F") {
    node.status({ fill: "yellow", shape: "ring", text: "waiting for 13F" });
    return null;
}

const now = Date.now();
const packStore = global.get("jkbms_pack_aggregates") || {};
const onlinePackIds = Array.isArray(aggregate.online_packs)
    ? aggregate.online_packs.map(String).sort(packSort)
    : [];
const offlinePackIds = Array.isArray(aggregate.offline_packs)
    ? aggregate.offline_packs.map(String).sort(packSort)
    : [];

// ---------------------------------------------------------
// 1B. STARTUP STABILIZATION
//
// During the first 30 seconds of this Function runtime, do not turn an
// incomplete startup topology into PACK_OFFLINE. As soon as all configured
// packs are fresh, diagnostics are allowed immediately. If one or more packs
// are still missing after the grace period, PACK_OFFLINE becomes a real
// diagnostic.
//
// While waiting, clear a previous retained Premium diagnostic once so MQTT
// cannot expose stale information from the preceding runtime.
// ---------------------------------------------------------
const startupTs = Number(flow.get("step13g_start_ts") || now);
const startupElapsedMs = Math.max(0, now - startupTs);
const configuredPackCount = finiteNumber(aggregate.pack_count);

const allConfiguredPacksFresh =
    configuredPackCount !== null &&
    configuredPackCount > 0 &&
    onlinePackIds.length >= configuredPackCount &&
    offlinePackIds.length === 0;

if (
    !allConfiguredPacksFresh &&
    startupElapsedMs < STARTUP_GRACE_MS
) {
    const remainingS = Math.max(0, Math.ceil(
        (STARTUP_GRACE_MS - startupElapsedMs) / 1000
    ));

    node.status({
        fill: "blue",
        shape: "ring",
        text: `startup ${onlinePackIds.length}/${configuredPackCount ?? "?"} packs (${remainingS}s)`
    });

    if (flow.get("step13g_wait_cleanup_done") !== true) {
        flow.set("step13g_wait_cleanup_done", true);
        return {
            topic: TOPIC,
            payload: "",
            retain: true
        };
    }

    return null;
}

const activeIssues = [];

// ---------------------------------------------------------
// 2. PACK OFFLINE
// ---------------------------------------------------------
if (offlinePackIds.length > 0) {
    activeIssues.push({
        code: "PACK_OFFLINE",
        severity: "warning",
        packs: offlinePackIds,
        count: offlinePackIds.length,
        message: offlinePackIds.length === 1
            ? `${packName(offlinePackIds[0])} is offline or stale.`
            : `${offlinePackIds.length} packs are offline or stale.`
    });
}

// ---------------------------------------------------------
// 3. TEMPERATURE HIGH
// ---------------------------------------------------------
const maxTemp = finiteNumber(aggregate.temperature_max_c);
if (maxTemp !== null && maxTemp >= THRESHOLDS.temperature_high_c) {
    let sourcePack = String(aggregate.temperature_max_source || "").split("/")[0] || null;
    activeIssues.push({
        code: "TEMPERATURE_HIGH",
        severity: "warning",
        pack_id: sourcePack,
        value_c: round(maxTemp, 1),
        threshold_c: THRESHOLDS.temperature_high_c,
        source: aggregate.temperature_max_source || null,
        message: `${packName(sourcePack)} reached ${round(maxTemp, 1)} °C.`
    });
}

// ---------------------------------------------------------
// 4. INTERNAL PACK CELL DELTA HIGH
// ---------------------------------------------------------
const highestPackDelta = finiteNumber(aggregate.highest_pack_cell_delta_v);
if (
    highestPackDelta !== null &&
    highestPackDelta >= THRESHOLDS.cell_delta_high_v
) {
    const p = aggregate.highest_cell_delta_pack || null;
    activeIssues.push({
        code: "CELL_DELTA_HIGH",
        severity: "warning",
        pack_id: p,
        value_v: round(highestPackDelta, 3),
        value_mv: round(highestPackDelta * 1000, 0),
        threshold_v: THRESHOLDS.cell_delta_high_v,
        message: `${packName(p)} has an internal cell delta of ${round(highestPackDelta * 1000, 0)} mV.`
    });
}

// ---------------------------------------------------------
// 5. CROSS-PACK COMPARISONS ARE INFORMATIONAL ONLY
//
// Multi-Pack packs may belong to different physical sites, battery systems,
// chemistries or functions. A SOC or voltage difference between packs is
// therefore not an alarm by itself.
//
// Keep the values available for the optional Aggregation dashboard, but do
// not turn them into Premium diagnostic issues.
// ---------------------------------------------------------
const socDelta = finiteNumber(aggregate.soc_delta_pct);
const avgSoc = finiteNumber(aggregate.average_soc_pct);
const voltageDelta = finiteNumber(aggregate.pack_voltage_delta_v);

// ---------------------------------------------------------
// 7. Primary status / worst pack / recommended action.
// Priority is deliberate: availability and thermal/cell safety first,
// then state mismatch diagnostics.
// ---------------------------------------------------------
const priority = [
    "PACK_OFFLINE",
    "TEMPERATURE_HIGH",
    "CELL_DELTA_HIGH"
];

let primaryIssue = null;
for (const code of priority) {
    primaryIssue = activeIssues.find(x => x.code === code) || null;
    if (primaryIssue) break;
}

let status = "OK";
let worstPack = null;
let recommendedAction = "All online packs are within the current diagnostic thresholds.";

if (primaryIssue) {
    status = primaryIssue.code;

    if (status === "PACK_OFFLINE") {
        worstPack = primaryIssue.packs?.[0] || null;
        recommendedAction = primaryIssue.count === 1
            ? `${packName(worstPack)} is offline or stale. Check its TCP gateway and RS485 bus.`
            : `${primaryIssue.count} packs are offline or stale (${primaryIssue.packs.join(", ")}). Check their TCP gateways and RS485 buses.`;
    }
    else if (status === "TEMPERATURE_HIGH") {
        worstPack = primaryIssue.pack_id || null;
        recommendedAction = `${packName(worstPack)} reports ${primaryIssue.value_c} °C. Check load, cooling and BMS temperature sources.`;
    }
    else if (status === "CELL_DELTA_HIGH") {
        worstPack = primaryIssue.pack_id || null;
        recommendedAction = `${packName(worstPack)} has the highest internal cell delta (${primaryIssue.value_mv} mV). Check cell balance and individual cell voltages.`;
    }
}

const alarmLifecycle = syncScadaLifecycle(scadaLifecycleRows(activeIssues), now);

const diagnostic = {
    step: "13G",
    schema_version: 2,
    access: "premium",
    premium_feature: FEATURE,
    ha_discovery: false,

    generated_at: new Date(now).toISOString(),
    source_step: "13F",
    source_generated_at: aggregate.generated_at || null,

    status,
    issue_count: activeIssues.length,
    worst_pack: worstPack,
    worst_pack_name: worstPack ? packName(worstPack) : null,
    recommended_action: recommendedAction,

    thresholds: THRESHOLDS,
    active_issues: activeIssues,
    alarm_lifecycle: alarmLifecycle,

    // Informational only. These values are intentionally excluded from
    // active_issues because packs can represent unrelated physical systems.
    cross_pack_comparison_is_informational: true,

    pack_count: finiteNumber(aggregate.pack_count),
    online_pack_count: finiteNumber(aggregate.online_pack_count),
    offline_pack_count: finiteNumber(aggregate.offline_pack_count),
    bms_count: finiteNumber(aggregate.bms_count),

    average_soc_pct: avgSoc,
    soc_delta_pct: socDelta,
    pack_voltage_delta_v: voltageDelta,
    highest_pack_cell_delta_v: highestPackDelta,
    temperature_max_c: maxTemp
};

global.set("jkbms_premium_diagnostics", diagnostic);

// ---------------------------------------------------------
// 8. Low-rate/change-aware retained MQTT validation output.
// No HA Discovery => no Recorder impact.
// ---------------------------------------------------------
const signature = JSON.stringify({
    status: diagnostic.status,
    worst_pack: diagnostic.worst_pack,
    recommended_action: diagnostic.recommended_action,
    active_issues: diagnostic.active_issues,
    alarm_lifecycle: {
        active: (diagnostic.alarm_lifecycle?.active || []).map(x => [x.key, x.ack_at || null]),
        history_head: diagnostic.alarm_lifecycle?.history?.[0]?.id || null,
        history_count: diagnostic.alarm_lifecycle?.history_count || 0
    }
});

const lastSignature = flow.get("step13g_last_signature") || "";
const lastPublishTs = Number(flow.get("step13g_last_publish_ts") || 0);
const changed = signature !== lastSignature;
const refreshDue = lastPublishTs <= 0 || (now - lastPublishTs) >= 30000;

if (!changed && !refreshDue) {
    node.status({
        fill: status === "OK" ? "green" : "yellow",
        shape: "dot",
        text: `${status}${worstPack ? ` / ${worstPack}` : ""}`
    });
    return null;
}

flow.set("step13g_last_signature", signature);
flow.set("step13g_last_publish_ts", now);
flow.set("step13g_has_current_run_diagnostic", true);

if (flow.get("step13g_first_log_done") !== true) {
    flow.set("step13g_first_log_done", true);
    node.warn(
        `Step 13G premium diagnostics ready -> ` +
        `status=${status}, worst=${worstPack || "none"}, issues=${activeIssues.length}`
    );
}

node.status({
    fill: status === "OK" ? "green" : "yellow",
    shape: "dot",
    text: `${status}${worstPack ? ` / ${worstPack}` : ""}`
});

return {
    topic: TOPIC,
    payload: JSON.stringify(diagnostic),
    retain: true
};

initialize:
// Step 13G startup stabilization state.
// Reset on every deploy/start so persisted Node-RED context cannot make a
// previous runtime look like the current one.
flow.set("step13g_start_ts", Date.now());
flow.set("step13g_wait_cleanup_done", false);
flow.set("step13g_has_current_run_diagnostic", false);
flow.set("step13g_last_signature", "");
flow.set("step13g_last_publish_ts", 0);
flow.set("step13g_first_log_done", false);
global.set("jkbms_premium_diagnostics", null);

func:
// =========================================================
// STEP 13H - MULTI-PACK PREMIUM DASHBOARD DATA BRIDGE
//
// Purpose:
// - expose only a very small HA-facing summary model;
// - keep validated raw aggregates 13E/13F/13G untouched;
// - create max. 5 pack summary sensors + 1 global + 1 diagnostic;
// - force stable Home Assistant entity IDs with default_entity_id;
// - throttle HA state payloads to protect Recorder;
// - clean discovery/state topics when Premium Multi-Pack is unavailable.
//
// Dashboard entitlement uses the existing dashboard_premium feature.
// No new Premium SKU is introduced.
// =========================================================

const FEATURE = "dashboard_premium";
const STATE_MIN_INTERVAL_MS = 60000;
const EXPIRE_AFTER_S = 180;
const ALL_PACK_IDS = ["pack_1", "pack_2", "pack_3", "pack_4", "pack_5"];

function parsePayload(payload) {
    if (payload && typeof payload === "object" && !Buffer.isBuffer(payload)) {
        return payload;
    }
    if (typeof payload === "string" && payload.trim()) {
        try { return JSON.parse(payload); } catch (_) {}
    }
    return null;
}

function packSort(a, b) {
    const na = Number(String(a).match(/(\d+)$/)?.[1] || 999);
    const nb = Number(String(b).match(/(\d+)$/)?.[1] || 999);
    return na - nb || String(a).localeCompare(String(b));
}

function runtimePackIds() {
    const ids = global.get("jkbms_pack_ids");
    if (Array.isArray(ids) && ids.length) {
        return ids.map(String).filter(x => ALL_PACK_IDS.includes(x)).sort(packSort);
    }
    const defs = global.get("jkbms_pack_defs") || {};
    return Object.keys(defs).filter(x => ALL_PACK_IDS.includes(x)).sort(packSort);
}

function packName(packId) {
    const defs = global.get("jkbms_pack_defs") || {};
    return defs?.[packId]?.name || packId;
}

function packStateTopic(packId) {
    return `jkbms/ha/multipack/${packId}/summary`;
}

const ENTITY_PREFIX = "smartphoton_jk_bms_multi_pack";

function packObjectId(packId) {
    return `${ENTITY_PREFIX}_${packId}_summary`;
}

function packDiscoveryTopic(packId) {
    return `homeassistant/sensor/${packObjectId(packId)}/config`;
}

// v4.2.19 discovery topics are explicitly cleaned during migration.
function legacyPackDiscoveryTopic(packId) {
    return `homeassistant/sensor/smartphoton_multipack_${packId}_summary/config`;
}

const GLOBAL_STATE_TOPIC = "jkbms/ha/multipack/global/summary";
const GLOBAL_OBJECT_ID = `${ENTITY_PREFIX}_global_summary`;
const GLOBAL_DISCOVERY_TOPIC = `homeassistant/sensor/${GLOBAL_OBJECT_ID}/config`;
const LEGACY_GLOBAL_DISCOVERY_TOPIC = "homeassistant/sensor/smartphoton_multipack_global_summary/config";

const DIAG_STATE_TOPIC = "jkbms/ha/multipack/global/premium_diagnostics";
const DIAG_OBJECT_ID = `${ENTITY_PREFIX}_diagnostics`;
const DIAG_DISCOVERY_TOPIC = `homeassistant/sensor/${DIAG_OBJECT_ID}/config`;
const LEGACY_DIAG_DISCOVERY_TOPIC = "homeassistant/sensor/smartphoton_multipack_diagnostics/config";

function mqtt(topic, payload) {
    return {
        topic,
        payload: typeof payload === "string" ? payload : JSON.stringify(payload),
        retain: true
    };
}

function emptyRetained(topic) {
    return { topic, payload: "", retain: true };
}

function packDiscovery(packId) {
    const objectId = packObjectId(packId);
    const stateTopic = packStateTopic(packId);
    const cfg = {
        name: "Summary",
        unique_id: objectId,
        object_id: objectId,
        default_entity_id: `sensor.${objectId}`,
        state_topic: stateTopic,
        value_template: "{{ value_json.soc_pct }}",
        json_attributes_topic: stateTopic,
        unit_of_measurement: "%",
        device_class: "battery",
        suggested_display_precision: 1,
        expire_after: EXPIRE_AFTER_S,
        icon: "mdi:battery-medium",
        device: {
            identifiers: [`smartphoton_multipack_${packId}`],
            name: packName(packId),
            manufacturer: "SmartPhoton",
            model: "JK-BMS Multi-Pack Aggregate"
        }
    };
    return cfg;
}

function globalDiscovery() {
    const objectId = GLOBAL_OBJECT_ID;
    const cfg = {
        name: "Global Summary",
        unique_id: objectId,
        object_id: objectId,
        default_entity_id: `sensor.${objectId}`,
        state_topic: GLOBAL_STATE_TOPIC,
        value_template: "{{ value_json.average_soc_pct }}",
        json_attributes_topic: GLOBAL_STATE_TOPIC,
        unit_of_measurement: "%",
        device_class: "battery",
        suggested_display_precision: 1,
        expire_after: EXPIRE_AFTER_S,
        icon: "mdi:battery-sync",
        device: {
            identifiers: ["smartphoton_multipack_global"],
            name: "SmartPhoton JK-BMS Multi-Pack",
            manufacturer: "SmartPhoton",
            model: "JK-BMS Multi-Pack Premium"
        }
    };
    return cfg;
}

function diagnosticDiscovery() {
    const objectId = DIAG_OBJECT_ID;
    return {
        name: "Diagnostics",
        unique_id: objectId,
        object_id: objectId,
        default_entity_id: `sensor.${objectId}`,
        state_topic: DIAG_STATE_TOPIC,
        value_template: "{{ value_json.status }}",
        json_attributes_topic: DIAG_STATE_TOPIC,
        expire_after: 60,
        icon: "mdi:stethoscope",
        device: {
            identifiers: ["smartphoton_multipack_global"],
            name: "SmartPhoton JK-BMS Multi-Pack",
            manufacturer: "SmartPhoton",
            model: "JK-BMS Multi-Pack Premium"
        }
    };
}

function sanitizePack(a) {
    return {
        pack_id: a.pack_id ?? null,
        pack_name: a.pack_name ?? null,
        bms_count: a.bms_count ?? null,
        members: Array.isArray(a.members) ? a.members : [],
        soc_pct: a.soc_pct ?? null,
        soc_lowest_pct: a.soc_lowest_pct ?? null,
        soc_highest_pct: a.soc_highest_pct ?? null,
        soh_average_pct: a.soh_average_pct ?? null,
        voltage_v: a.voltage_v ?? null,
        current_total_a: a.current_total_a ?? null,
        power_total_w: a.power_total_w ?? null,
        remaining_capacity_total_ah: a.remaining_capacity_total_ah ?? null,
        nominal_capacity_total_ah: a.nominal_capacity_total_ah ?? null,
        balancing_active: a.balancing_active === true,
        balancing_active_bms_count: a.balancing_active_bms_count ?? 0,
        balancing_details: Array.isArray(a.balancing_details) ? a.balancing_details : [],
        cell_min_voltage_v: a.cell_min_voltage_v ?? null,
        cell_min_source: a.cell_min_source ?? null,
        cell_max_voltage_v: a.cell_max_voltage_v ?? null,
        cell_max_source: a.cell_max_source ?? null,
        cell_delta_v: a.cell_delta_v ?? null,
        temperature_max_c: a.temperature_max_c ?? null,
        temperature_max_source: a.temperature_max_source ?? null
    };
}

function sanitizeGlobal(a) {
    return {
        pack_count: a.pack_count ?? null,
        online_pack_count: a.online_pack_count ?? null,
        offline_pack_count: a.offline_pack_count ?? null,
        online_packs: Array.isArray(a.online_packs) ? a.online_packs : [],
        offline_packs: Array.isArray(a.offline_packs) ? a.offline_packs : [],
        bms_count: a.bms_count ?? null,
        total_current_a: a.total_current_a ?? null,
        total_power_w: a.total_power_w ?? null,
        total_remaining_capacity_ah: a.total_remaining_capacity_ah ?? null,
        total_nominal_capacity_ah: a.total_nominal_capacity_ah ?? null,
        average_soc_pct: a.average_soc_pct ?? null,
        lowest_soc_pct: a.lowest_soc_pct ?? null,
