function sanitizeDiagnostic(a) {
    // HA Recorder hard limit is 16384 bytes for state attributes.
    // Keep bounded health counters; detailed audits remain in Node-RED global
    // context and on jkbms/scada/audit/snapshot, outside HA Discovery.
    const ca=global.get("jkbms_scada_command_audit")||{};
    const ah=Array.isArray(ca.history)?ca.history:[];
    const al=(a.alarm_lifecycle&&typeof a.alarm_lifecycle==='object')?a.alarm_lifecycle:{};
    const brief=v=>v==null?null:String(v).slice(0,200);
    return {
        status:brief(a.status)??"UNKNOWN",
        issue_count:a.issue_count??0,
        worst_pack:brief(a.worst_pack),worst_pack_name:brief(a.worst_pack_name),
        recommended_action:brief(a.recommended_action),
