            active_count:Array.isArray(al.active)?al.active.length:0},
        command_audit:{source:"node_red",schema_version:3,max_history:240,
            history_count:ah.length,history:[]},
        audit_detail_topic:"jkbms/scada/audit/snapshot",
        pack_count:a.pack_count??null,
        online_pack_count:a.online_pack_count??null,
        offline_pack_count:a.offline_pack_count??null,
        bms_count:a.bms_count??null,
        average_soc_pct:a.average_soc_pct??null,
        soc_delta_pct:a.soc_delta_pct??null,
        pack_voltage_delta_v:a.pack_voltage_delta_v??null,
        highest_pack_cell_delta_v:a.highest_pack_cell_delta_v??null,
        temperature_max_c:a.temperature_max_c??null
    };
}


function publishDue(key, signature, forceStructural) {
    const now = Date.now();
    const lastTs = Number(flow.get(`${key}_ts`) || 0);
    const lastStructural = flow.get(`${key}_structural`) || "";
    const structuralChanged = forceStructural !== undefined &&
        String(forceStructural) !== String(lastStructural);

    if (structuralChanged) {
        flow.set(`${key}_structural`, String(forceStructural));
    }

    if (lastTs <= 0 || structuralChanged || (now - lastTs) >= STATE_MIN_INTERVAL_MS) {
        flow.set(`${key}_ts`, now);
        if (signature !== undefined) flow.set(`${key}_signature`, String(signature));
        return true;
    }
    return false;
}

// ---------------------------------------------------------
// Premium/runtime gate
// ---------------------------------------------------------
const runtimeMode = String(
    global.get("premium.runtime_mode") ||
    global.get("jkbms_runtime_mode") ||
