).trim().toLowerCase();

const features = global.get("premium.features") || {};
const allowed =
    runtimeMode === "multi_pack" &&
    global.get("premium.multi_pack_premium_available") === true &&
    features[FEATURE] === true;

const packIds = runtimePackIds();

// ---------------------------------------------------------
// Startup init / cleanup
// ---------------------------------------------------------
if (msg && msg._step13h_init === true) {
    const out = [];

    // Always remove stale discovery/state for every possible pack first.
    // Also remove the v4.2.19 discovery topics so Home Assistant drops
    // the entities whose IDs were derived from device names.
    for (const packId of ALL_PACK_IDS) {
        out.push(emptyRetained(legacyPackDiscoveryTopic(packId)));
        out.push(emptyRetained(packDiscoveryTopic(packId)));
        out.push(emptyRetained(packStateTopic(packId)));
    }
    out.push(emptyRetained(LEGACY_GLOBAL_DISCOVERY_TOPIC));
    out.push(emptyRetained(GLOBAL_DISCOVERY_TOPIC));
    out.push(emptyRetained(GLOBAL_STATE_TOPIC));
    out.push(emptyRetained(LEGACY_DIAG_DISCOVERY_TOPIC));
    out.push(emptyRetained(DIAG_DISCOVERY_TOPIC));
    out.push(emptyRetained(DIAG_STATE_TOPIC));

    if (!allowed) {
        node.status({
            fill: features[FEATURE] === true ? "blue" : "grey",
            shape: "ring",
            text: features[FEATURE] === true ? "not applicable" : "premium required"
        });
        return [out];
    }

    // Recreate discovery only for active runtime packs.
    for (const packId of packIds) {
        out.push(mqtt(packDiscoveryTopic(packId), packDiscovery(packId)));
    }
    out.push(mqtt(GLOBAL_DISCOVERY_TOPIC, globalDiscovery()));
    out.push(mqtt(DIAG_DISCOVERY_TOPIC, diagnosticDiscovery()));

    // Republish current canonical snapshots immediately after cleanup.
    const packStore = global.get("jkbms_pack_aggregates") || {};
    const now = Date.now();

    for (const packId of packIds) {
        const a = packStore[packId];
        if (a && a.step === "13E") {
            out.push(mqtt(packStateTopic(packId), sanitizePack(a)));
            flow.set(`step13h_pack_${packId}_ts`, now);
            flow.set(
                `step13h_pack_${packId}_structural`,
                JSON.stringify([a.bms_count, a.members || []])
            );
        } else {
            flow.set(`step13h_pack_${packId}_ts`, 0);
        }
    }

    const g = global.get("jkbms_global_aggregate");
    if (g && g.step === "13F") {
        out.push(mqtt(GLOBAL_STATE_TOPIC, sanitizeGlobal(g)));
        flow.set("step13h_global_ts", now);
        flow.set(
            "step13h_global_structural",
            JSON.stringify([g.online_pack_count, g.offline_pack_count, g.bms_count])
        );
    } else {
        flow.set("step13h_global_ts", 0);
    }

    const d = global.get("jkbms_premium_diagnostics");
    if (d && d.step === "13G") {
        out.push(mqtt(DIAG_STATE_TOPIC, sanitizeDiagnostic(d)));
        flow.set("step13h_diag_ts", now);
        flow.set("step13h_diag_signature", JSON.stringify([
            d.status,
            d.worst_pack,
            (Array.isArray(d.active_issues) ? d.active_issues : [])
                .map(i => `${i?.code || "UNKNOWN"}:${i?.pack_id || ""}`)
                .sort(),
            (d.alarm_lifecycle?.active || []).map(x => `${x?.key || ""}:${x?.ack_at || ""}`).sort(),
            d.alarm_lifecycle?.history?.[0]?.id || null,
            d.alarm_lifecycle?.history_count || 0
        ]));
    } else {
        flow.set("step13h_diag_ts", 0);
    }

    if (flow.get("step13h_discovery_log_done") !== true) {
        flow.set("step13h_discovery_log_done", true);
        node.warn(
            `Step 13H HA Discovery ready -> ${packIds.length} pack summaries + global + diagnostics`
        );
    }

    node.status({
        fill: "green",
        shape: "dot",
        text: `${packIds.length} packs / HA summary`
    });

    return [out];
}

if (!allowed) return null;

// ---------------------------------------------------------
// Normal stream from 13E / 13F / 13G
// ---------------------------------------------------------
const data = parsePayload(msg.payload);
if (!data || !data.step) return null;

if (data.step === "13E") {
    const packId = String(data.pack_id || "");
    if (!packIds.includes(packId)) return null;

    const structural = JSON.stringify([data.bms_count, data.members || []]);
    if (!publishDue(`step13h_pack_${packId}`, null, structural)) return null;

    return mqtt(packStateTopic(packId), sanitizePack(data));
}

if (data.step === "13F") {
    const structural = JSON.stringify([
        data.online_pack_count,
        data.offline_pack_count,
        data.bms_count,
        data.online_packs || [],
        data.offline_packs || []
    ]);

    if (!publishDue("step13h_global", null, structural)) return null;
    return mqtt(GLOBAL_STATE_TOPIC, sanitizeGlobal(data));
}

if (data.step === "13G") {
    // Immediate publish only when the diagnostic nature changes.
    // Numeric wording in recommended_action must not bypass the 60s governor.
    const issueSignature = (Array.isArray(data.active_issues) ? data.active_issues : [])
        .map(i => `${i?.code || "UNKNOWN"}:${i?.pack_id || ""}`)
        .sort();

    const signature = JSON.stringify([
        data.status,
        data.worst_pack,
        issueSignature,
        (data.alarm_lifecycle?.active || []).map(x => `${x?.key || ""}:${x?.ack_at || ""}`).sort(),
        data.alarm_lifecycle?.history?.[0]?.id || null,
        data.alarm_lifecycle?.history_count || 0
    ]);

    const lastSignature = flow.get("step13h_diag_signature") || "";
    const changed = signature !== lastSignature;
    const now = Date.now();
    const lastTs = Number(flow.get("step13h_diag_ts") || 0);

    if (!changed && lastTs > 0 && (now - lastTs) < STATE_MIN_INTERVAL_MS) {
        return null;
    }

    flow.set("step13h_diag_signature", signature);
    flow.set("step13h_diag_ts", now);
    return mqtt(DIAG_STATE_TOPIC, sanitizeDiagnostic(data));
}

return null;

