    p.status ?? null,
    p.health_reason ?? null,
    Array.isArray(p.health_flags) ? p.health_flags : [],
    p.detected_bms ?? null,
    p.detected_bms_list ?? null
]);

const importantChanged = importantSignature !== lastSignature;
const due = lastTs <= 0 || importantChanged || (now - lastTs) >= SNAPSHOT_INTERVAL_MS;

