const out={payload:e.payload,pack_id:e.pack_id,pack_name:def.name,bus_id:def.bus_id,_transport:def.transport||e._transport||'tcp',bms_numero:e.bms_numero,bms_adresse:e.bms_numero,bms_type:e.register===0x161e?'setup':e.register===0x161c?'static':'data'};
