   }
   mqtt.push({topic:topic+'/state',payload:String(x.value),retain:true});
   mqtt.push({topic:topic+'/attributes',payload:JSON.stringify({
    ...x.attrs,source:'STATIC',register:'0x161C',frame_type:'0x03',read_only:true,
