   const domain=isSelect?'select':'number';
   const ctlId=`${stableId}_active_polling`;
   const ctlTopic=`${base}/BMS_${e.bms_numero}/control/${x.key}`;
   const sourceCode=x.key.startsWith('dry1')?dry1Code:dry2Code;
   const attrs={source:'STATIC',source_code:sourceCode,raw_code:isSelect?x.attrs.raw_code:undefined,observed_at:now,semantic_unit:!isSelect&&sourceCode===8?'°C':'brut',read_only:false};
   const dc={name:x.label+' config',unique_id:ctlId,default_entity_id:`${domain}.${ctlId}`,state_topic:ctlTopic+'/state',command_topic:ctlTopic+'/set',json_attributes_topic:ctlTopic+'/attributes',optimistic:false,retain:false,entity_category:'config',availability_topic:base+'/active_polling/availability',device:{identifiers:[deviceID],name:`${def.name} - BMS_${e.bms_numero}`}};
