// 0x1114 controls are decoded directly from the fresh SETUP word;
// charge/discharge/balance are 32-bit 0/1 SETUP fields.
const word=e.payload.readUInt16LE(282), mqtt=[];
const deviceID=`${e.pack_id}_BMS_${e.bms_numero}_device`;
const switchSpecs=[
 {control:'display_always_on_switch',label:'LCD always on',value:()=>Boolean(word&0x0010)},
 {control:'heating_switch',label:'Heating enable',value:()=>Boolean(word&0x0001)},
 {control:'charging_switch',label:'Charging switch',value:()=>e.payload.readInt32LE(118)!==0},
