// ========== ACTIVE POLLING SETUP DISCOVERY - DEV73 physical BMS 0 identity ==========
// Buts :
// - Publier au premier passage
// - Republier si une valeur change
// - Republier si forçage demandé
// - Recréer les entités HA si elles ont disparu
// - Supporter l'apparition de nouvelles clés sans bloquer

// -----------------------------------------------------------------
// 1) Identification du BMS
// -----------------------------------------------------------------
// In Multi-Pack Active Polling, address 0 is a physical JK UART1 address.
// Only the historical Legacy/Broadcasting path uses the virtual "master" ID.
const multiPack = global.get("multi_pack_enabled") === true;
const activePollingMode = multiPack && global.get("jkbms_active_polling_enabled") === true;
const bmsAdresse = Number(msg.bms_numero);
const slaveIdStr = bmsAdresse === 0 && !activePollingMode ? "master" : String(bmsAdresse);

if (!msg.payload || typeof msg.payload !== "object" || Array.isArray(msg.payload)) {
    node.warn(`Setup To MQTT ignoré: payload invalide pour BMS ${slaveIdStr}`);
    return null;
}

const payload = msg.payload;

// -----------------------------------------------------------------
// MQTT / HA identity : legacy strict ou Multi-Pack.
const packId = msg.pack_id || "pack_1";
const packName = msg.pack_name || "Pack 1";
const packSafe = String(packId).toLowerCase().replace(/[^a-z0-9_]+/g, "_");

const baseTopic = multiPack
    ? `jkbms/${packId}/BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

const discoveryPrefix = "homeassistant";

const deviceName = multiPack
    ? `${packName} - BMS_${slaveIdStr}`
    : `BMS_${slaveIdStr}`;

const deviceID = multiPack
    ? `${packSafe}_BMS_${slaveIdStr}_device`
    : `${baseTopic}_device`;

const entityPrefix = multiPack
    ? `${packSafe}_bms_${slaveIdStr}`
    : baseTopic.toLowerCase();

// -----------------------------------------------------------------
// 2) Clés de contexte
// -----------------------------------------------------------------
const setupSentKey = multiPack
    ? `apSetupSent_${packId}_BMS_${slaveIdStr}`
    : `apSetupSent_BMS_${slaveIdStr}`;

const lastSetupKey = multiPack
    ? `apLastSetup_${packId}_BMS_${slaveIdStr}`
    : `apLastSetup_BMS_${slaveIdStr}`;

const forceKeyFlow = multiPack
    ? `forceSetupRepublish_${packId}_BMS_${slaveIdStr}`
    : `forceSetupRepublish_BMS_${slaveIdStr}`;

const forceAllKeyFlow = multiPack
    ? `forceSetupRepublishAll_${packId}`
    : "forceSetupRepublishAll";

let setupAlreadySent = !!flow.get(setupSentKey);
let lastSetup = flow.get(lastSetupKey) || {};

const forceRepublish =
    msg.force_setup_republish === true ||
    flow.get(forceKeyFlow) === true ||
    flow.get(forceAllKeyFlow) === true ||
    global.get(forceKeyFlow) === true ||
    global.get(forceAllKeyFlow) === true;

// v4.2.88 migration cleanup is intentionally one-shot per BMS, but it is
// allowed to run only after the MQTT broker has positively reported CONNECTED.
// v4.2.81 could emit retained-delete messages while the MQTT node was still
// disconnected, then mark cleanup complete even though those deletes had not
// reached the broker. Versioning the flag forces one clean retry in v4.2.89.
const migrationCleanupKey = `apMigrationCleanup_v4_2_89_${packId}_BMS_${slaveIdStr}`;
const migrationCleanupNeeded = activePollingMode && flow.get(migrationCleanupKey) !== true;
const migrationCleanupCanRun =
    migrationCleanupNeeded && global.get("jkbms_mqtt_connected") === true;

// Writable numeric SETUP controls in Active Polling v4.2.89.
// v4.2.84-v4.2.87 validated 29 numeric controls end-to-end.
// v4.2.88 added dedicated writable switches.
// v4.2.89 promotes Smart Sleep Voltage using the existing Legacy 0x1000 writer range.
// Keys are the exact names emitted by the SETUP buffer-parser. The MQTT
// control name is derived by the same cleanKey rule already used by Legacy.
const ACTIVE_POLLING_WRITABLE_NUMBERS = Object.freeze({
    // v4.2.84 - validated end-to-end
    max_charge_current_A: { unit: "A", min: 0, max: 150, step: 1 },
    max_discharge_current_S: { unit: "A", min: 0, max: 150, step: 1 },
    total_battery_capacity_Ah: { unit: "Ah", min: 1, max: 2000, step: 1 },
    balance_trigger_voltage_V: { unit: "V", min: 0.003, max: 1, step: 0.001 },
    balance_starting_voltage_V: { unit: "V", min: 1.2, max: 4.25, step: 0.01 },

    // v4.2.85 - second validation batch. Ranges intentionally follow the
    // existing Legacy write functions rather than broadening Legacy behavior.
    cell_voltage_undervoltage_protection_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_voltage_undervoltage_recovery_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_voltage_overvoltage_protection_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_voltage_overvoltage_recovery_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_soc100_voltage_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_soc0_voltage_V: { unit: "V", min: 2.5, max: 4.5, step: 0.001 },
    cell_request_charge_voltage_V: { unit: "V", min: 2.5, max: 4.5, step: 0.01 },
    cell_request_float_voltage_V: { unit: "V", min: 2.5, max: 4.5, step: 0.01 },
    power_off_voltage_V: { unit: "V", min: 1.8, max: 3.0, step: 0.01 },

    // v4.2.86 - third validation batch. Keep the ranges aligned with the
    // existing Legacy discovery/write paths.
    charge_overcurrent_protection_delay_S: { unit: "s", min: 2, max: 600, step: 1 },
    charge_overcurrent_protection_recovery_time_S: { unit: "s", min: 2, max: 3600, step: 1 },
    discharge_overcurrent_protection_delay_S: { unit: "s", min: 2, max: 600, step: 1 },
    discharge_overcurrent_protection_recovery_time_S: { unit: "s", min: 2, max: 3600, step: 1 },
    short_circuit_protection_recovery_time_S: { unit: "s", min: 2, max: 600, step: 1 },
    max_balance_current_A: { unit: "A", min: 0, max: 2, step: 0.1 },
    short_circuit_protection_delay_S: { unit: "s", min: 0, max: 5000, step: 1 },

    // v4.2.87 - fourth validation batch: thermal protection thresholds.
    // Signed protocol values use 0.1 °C; HA keeps the Legacy 0.5 °C step.
    charge_overtemperature_protection_T: { unit: "°C", min: -40, max: 150, step: 0.5 },
    charge_overtemperature_protection_recovery_T: { unit: "°C", min: -40, max: 150, step: 0.5 },
    discharge_overtemperature_protection_T: { unit: "°C", min: -40, max: 150, step: 0.5 },
    discharge_overtemperature_protection_recovery_T: { unit: "°C", min: -40, max: 150, step: 0.5 },
    charge_undertemperature_protection_T: { unit: "°C", min: -40, max: 50, step: 0.5 },
    charge_undertemperature_protection_recovery_T: { unit: "°C", min: -40, max: 50, step: 0.5 },
    power_tube_overtemperature_protection_T: { unit: "°C", min: 30, max: 100, step: 0.5 },
    power_tube_overtemperature_protection_recovery_T: { unit: "°C", min: 30, max: 100, step: 0.5 },

    // v4.2.89 - final low-risk SETUP numeric for this tranche. The Legacy
    // write function accepts 2.5..4.5 V at register 0x1000 (millivolt encoding).
    smart_sleep_voltage_V: { unit: "V", min: 2.5, max: 4.5, step: 0.01 }
