// -----------------------------------------------------------------
// 4) Construction des messages
// -----------------------------------------------------------------
// These values have dedicated writable Active Polling switches and must not
// be duplicated as read-only SETUP sensors.
const ACTIVE_POLLING_CONTROL_KEYS = new Set([
    // Depending on the SETUP parser path the historical type suffix may
    // already have been stripped. Accept both spellings so dedicated
    // writable controls are never recreated as read-only sensors.
    "display_always_on_switch", "display_always_on_switch_B",
    "heating_switch", "heating_switch_B",
    "charging_switch", "charging_switch_B",
    "discharging_switch", "discharging_switch_B",
    "balance_switch", "balance_switch_B",
    "smart_sleep_switch", "smart_sleep_switch_B",
    "disable_pcl_module_switch", "disable_pcl_module_switch_B",
    "timed_stored_data_switch", "timed_stored_data_switch_B",
    "charging_floating_mode", "Charging_Floating_Mode_B"
]);

let outMsgs = [];
let hasChanges = false;
let keys = Object.keys(payload).sort();

for (const key of keys) {
    const currentNormalized = normalizeValue(payload[key]);
    const previousNormalized = normalizeValue(lastSetup[key]);

    const keyWasKnown = Object.prototype.hasOwnProperty.call(lastSetup, key);
    const changed = !setupAlreadySent || forceRepublish || !keyWasKnown || currentNormalized !== previousNormalized;

    if (ACTIVE_POLLING_CONTROL_KEYS.has(key)) {
        // Dedicated writable Active Polling switches own these controls.
        // v4.2.89 removes stale retained SETUP entities only once and only
        // while MQTT is confirmed connected. This includes the obsolete
        // read-only LCD/heating sensors created by earlier Active Polling builds.
        if (migrationCleanupCanRun) {
            outMsgs.push(...createLegacySetupDiscoveryCleanupMessages(key));
            const obsoleteSensor = createObsoleteActivePollingSensorCleanupMessage(key);
            if (obsoleteSensor) outMsgs.push(obsoleteSensor);
        }
        lastSetup[key] = payload[key];
        continue;
    }

    const writableNumber = Object.prototype.hasOwnProperty.call(ACTIVE_POLLING_WRITABLE_NUMBERS, key);

    // One-shot migration cleanup. Read-only values stay sensors and therefore
    // remove historical number/switch discoveries. Writable Active Polling controls
    // move in the opposite direction: remove the old AP sensor and any stale
    // generic switch, then publish the writable number discovery below.
    if (migrationCleanupCanRun) {
        if (writableNumber) {
            const obsoleteSensor = createObsoleteActivePollingSensorCleanupMessage(key);
            if (obsoleteSensor) outMsgs.push(obsoleteSensor);
            const staleSwitch = createLegacySetupSwitchCleanupMessage(key);
            if (staleSwitch) outMsgs.push(staleSwitch);
        } else {
            outMsgs.push(...createLegacySetupDiscoveryCleanupMessages(key));
        }
    }

    // Recréation config :
    // - au premier envoi
    // - en republish forcé (startup / MQTT reconnect)
    // - si une nouvelle clé apparaît
    // - pendant la migration v4.2.89, pour garantir que le nouveau domaine
    //   (sensor ou number) est annoncé juste après le cleanup retained.
    if (!setupAlreadySent || forceRepublish || !keyWasKnown || migrationCleanupCanRun) {
        outMsgs.push(createConfigPayload(key));
    }

    // Publication d'état :
    // - au premier envoi
    // - en republish forcé
    // - si changement
    if (changed) {
        outMsgs.push(createStateMessage(key, payload[key]));
        lastSetup[key] = payload[key];
        hasChanges = true;
    }
}

// -----------------------------------------------------------------
// 5) Sauvegarde état / logs
// -----------------------------------------------------------------
if (!setupAlreadySent || forceRepublish || hasChanges || migrationCleanupCanRun) {
    flow.set(setupSentKey, true);
    flow.set(lastSetupKey, lastSetup);

    if (migrationCleanupCanRun) {
        flow.set(migrationCleanupKey, true);
    }

    // On nettoie les flags de forçage une fois utilisés.
    // Global flags are used by the MQTT reconnect watcher (different flow tab).
    flow.set(forceKeyFlow, false);
    flow.set(forceAllKeyFlow, false);
    global.set(forceKeyFlow, false);
    global.set(forceAllKeyFlow, false);

    if (!setupAlreadySent) {
        node.warn(`✓ Setup INITIAL envoyé pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else if (forceRepublish) {
        node.warn(`↻ Setup FORCÉ renvoyé pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else if (hasChanges) {
        node.warn(`✓ Setup CHANGEMENTS détectés pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    } else {
        node.warn(`✓ Setup MIGRATION cleanup v4.2.89 pour BMS ${slaveIdStr} (${outMsgs.length} messages)`);
    }

    return [outMsgs];
} else {
    node.debug(`⊘ Setup: aucun changement pour BMS ${slaveIdStr}`);
    return null;
}

