const inputEnv = msg.payload.toString().trim();

let configPath;
let statusColor;
let bip;

switch(inputEnv) {
    case 'HAOS':
        configPath = '/data/options.json';
        msg.environment = 'Home Assistant OS';
        bip = 1;
        statusColor = 'green';
        break;
    case 'Docker':
        configPath = '/data/options.json';
        msg.environment = 'Docker (autre)';
        bip = 2;
        statusColor = 'blue';
        break;
    case 'Linux':
        configPath = '/data/options.json';
        msg.environment = 'Linux barebone';
        bip = 3;
        statusColor = 'yellow';
        break;
    case 'Windows':
        configPath = 'C:\\data\\options.json';
        msg.environment = 'Windows';
        bip = 4;
        statusColor = 'purple';
        break;
    default:
        configPath = './data/options.json';
        msg.environment = 'Inconnu';
        bip = 5;
        statusColor = 'red';
}

// 2ème digit : premium actif ou non
const premium = global.get('premium') || {};
const premiumDigit = (premium.status === 'active') ? '1' : '0';

msg.filename = configPath;
msg.payload = {
    "bip": String(bip) + premiumDigit,  // historique: ex. "11", "10", "21"...
    "mode": "multi_pack",
    "multi_pack": true
};
msg.headers = { "Content-Type": "application/json" };
node.status({fill: statusColor, shape: "dot", text: msg.environment});
return msg;

const code = Number(msg.statusCode || 0);

if (code >= 200 && code < 300) {
    return null;
}

if (code > 0) {
    node.warn(`⚠️ BIP server returned HTTP ${code}`);
} else {
    node.warn("⚠️ BIP server returned an invalid or unavailable response");
}

return null;

const feature = String(
    msg.premium_feature || "dashboard_premium"
).trim();

const features = global.get("premium.features") || {};
const premium = global.get("premium") || {};

const runtimeMode = String(
    global.get("premium.runtime_mode") ||
    global.get("jkbms_runtime_mode") ||
    "legacy"
).trim().toLowerCase();

// ---------------------------------------------------------
// 1. ENTITLEMENT
// La licence donne-t-elle droit à cette feature ?
// ---------------------------------------------------------
const entitled = features[feature] === true;

// ---------------------------------------------------------
// 2. RUNTIME APPLICABILITY
// La feature a-t-elle un sens dans le runtime courant ?
// ---------------------------------------------------------
let applicable = true;
let reason = entitled ? "allowed" : "premium_required";

// Le dashboard Premium actuel utilise les sensors Legacy.
// Il ne doit jamais être généré en Multi-Pack.
if (
    feature === "dashboard_premium" &&
    runtimeMode !== "legacy"
) {
    applicable = false;
    reason = "not_applicable_in_multi_pack";
}

const allowed =
    entitled === true &&
    applicable === true;

msg.premium_access = {
    feature,
    entitled,
    applicable,
    allowed,
    runtime_mode: runtimeMode,
    bundle:
        premium.bundle ||
        (global.get("premium.active") === true
            ? "premium"
            : "free"),
    status:
        premium.validation_status ||
        global.get("premium.status") ||
        "unknown",
    reason
};

// ---------------------------------------------------------
// AUTORISÉ
// ---------------------------------------------------------
if (allowed) {
    node.status({
        fill: "green",
        shape: "dot",
        text: `${feature}: allowed (${runtimeMode})`
    });

    return [msg, null];
}

// ---------------------------------------------------------
// REFUSÉ : licence absente
// ---------------------------------------------------------
if (!entitled) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: `${feature}: premium required`
    });

    return [null, msg];
}

// ---------------------------------------------------------
// REFUSÉ : feature Premium valide mais non applicable
// au runtime courant.
// ---------------------------------------------------------
node.status({
    fill: "blue",
    shape: "ring",
    text: `${feature}: not applicable (${runtimeMode})`
});

return [null, msg];

