// Latest 13E aggregate store is used only to know which BMS cards must be
// instantiated in the generated dashboard. Runtime values still come from
// the throttled Step 13H HA summary sensor attributes.
const packAggregateStore = global.get("jkbms_pack_aggregates") || {};

function sortBmsMembers(a, b) {
    if (a === "master") return b === "master" ? 0 : -1;
    if (b === "master") return 1;
    const na = Number(a);
    const nb = Number(b);
    if (Number.isFinite(na) && Number.isFinite(nb)) return na - nb;
    return String(a).localeCompare(String(b));
}

function packMembersForDashboard(packId) {
    const aggregate = packAggregateStore?.[packId] || {};
    const members = Array.isArray(aggregate.members)
        ? aggregate.members.map(String)
        : [];
    return [...new Set(members)].sort(sortBmsMembers);
}

function bmsDisplayName(bms) {
    return bms === "master" ? "master" : `BMS ${bms}`;
}

function balanceActionEntity(packId, bms) {
    return `binary_sensor.${packId}_bms_${bms}_balance_action`;
}

function balanceCurrentEntity(packId, bms) {
    return `sensor.${packId}_bms_${bms}_balance_courant`;
}

function mushroomBalanceCard(packId, bms) {
    const actionEntity = balanceActionEntity(packId, bms);
    const currentEntity = balanceCurrentEntity(packId, bms);
    const label = bmsDisplayName(bms);

    // Use the existing per-BMS balance current sensor directly. This makes the
    // visual current more responsive than the throttled Step 13H summary.
    const currentBlock = `{% set c = states('${currentEntity}') | float(0) %}`;
    const secondary = currentBlock +
        `{% if c > 0 %}+{% endif %}{{ c | round(3) }} A`;

    const icon = currentBlock +
        `{% if c > 0 %}mdi:arrow-up-bold` +
        `{% elif c < 0 %}mdi:arrow-down-bold` +
        `{% else %}mdi:arrow-right-bold{% endif %}`;

    // Negative balancing current is deliberately blue, not red: the sign is
    // directional information, not an alarm condition.
    const iconColor = currentBlock +
        `{% if c > 0 %}green` +
        `{% elif c < 0 %}blue` +
        `{% else %}grey{% endif %}`;

    return {
        type: "custom:mushroom-template-card",
        entity: currentEntity,
        primary: `${txt.balancing} · ${label}`,
        secondary,
        icon,
        icon_color: iconColor,
        tap_action: { action: "more-info" }
    };
}

function activeBalanceCondition(packId, bms) {
    const currentEntity = balanceCurrentEntity(packId, bms);

    // STEP 13H v4.2.27 / Recorder Protection 13I-A+B
    // Use the actual signed balancing current as the activity criterion.
    // Some JK-BMS firmwares can report Balance_Action_B=0 while a real
    // balancing current is flowing. This mirrors the validated Step 13E
    // fallback: |Balance_courant_A| > 0.001 A means balancing is active.
    return {
        condition: "or",
        conditions: [
            {
                condition: "numeric_state",
                entity: currentEntity,
                above: 0.001
            },
            {
                condition: "numeric_state",
                entity: currentEntity,
                below: -0.001
            }
        ]
    };
}

function mushroomBalanceGrid(packId) {
    if (!customCardsInstalled) return null;
    const members = packMembersForDashboard(packId);
    if (!members.length) return null;

    // The whole balance area disappears when no BMS is actively balancing.
    // Each individual Mushroom card is also conditional, so only active BMS
    // consume dashboard space. No additional HA entity is required.
    return {
        type: "conditional",
        conditions: [{
            condition: "or",
            conditions: members.map(bms => activeBalanceCondition(packId, bms))
        }],
        card: {
            type: "grid",
            columns: members.length === 1 ? 1 : 2,
            square: false,
            cards: members.map(bms => ({
                type: "conditional",
                conditions: [activeBalanceCondition(packId, bms)],
                card: mushroomBalanceCard(packId, bms)
            }))
        }
    };
}

function balancingLineJinja() {
    return `**${txt.balancing}:** {% if state_attr(e, 'balancing_active') %}**${txt.active}**{% set bd = state_attr(e, 'balancing_details') or [] %}{% for b in bd %}{% if b.active %}{% set c = b.current_a | float(0) %} · {{ 'master' if b.bms == 'master' else 'BMS ' ~ b.bms }}: {% if c > 0 %}+{% endif %}{{ c | round(3) }} A{% endif %}{% endfor %}{% else %}${txt.inactive}{% endif %}`;
}

function packOverviewCard(packId) {
    const entity = packEntity(packId);
    const name = packName(packId);
    const members = packMembersForDashboard(packId);
    const activeExpr = members.length
        ? members.map(bms => `(states('${balanceCurrentEntity(packId, bms)}') | float(0) | abs) > 0.001`).join(' or ')
        : 'false';

    // With Mushroom enabled, keep just one compact inactive indication inside
    // the pack summary. As soon as any BMS starts balancing this line vanishes
    // and the per-BMS Mushroom cards appear below the pack automatically.
    const nativeBalancingLine = customCardsInstalled
        ? `{% if not (${activeExpr}) %}**${txt.balancing}:** ${txt.inactive}  \n{% endif %}`
        : `${balancingLineJinja()}  \n`;

    const content = `## ${name}
{% set e = '${entity}' %}
{% if states(e) not in ['unknown','unavailable'] %}
# {{ states(e) }} %
**${txt.voltage}:** {{ state_attr(e, 'voltage_v') }} V  ·  **${txt.current}:** {{ state_attr(e, 'current_total_a') }} A  ·  **${txt.power}:** {{ ((state_attr(e, 'power_total_w') or 0) / 1000) | round(2) }} kW  
**${txt.cellDelta}:** {{ ((state_attr(e, 'cell_delta_v') or 0) * 1000) | round(0) }} mV  ·  **${txt.temp}:** {{ state_attr(e, 'temperature_max_c') }} °C  ·  **${txt.bms}:** {{ state_attr(e, 'bms_count') }}  
${nativeBalancingLine}**${txt.capacity}:** {{ (state_attr(e, 'remaining_capacity_total_ah') or 0) | round(1) }} / {{ (state_attr(e, 'nominal_capacity_total_ah') or 0) | round(1) }} Ah
{% else %}
_${txt.unavailable}_
{% endif %}`;

    const summary = {
        type: "markdown",
        content
    };

    const balanceGrid = mushroomBalanceGrid(packId);
    if (!balanceGrid) return summary;

    return {
        type: "vertical-stack",
        cards: [summary, balanceGrid]
    };
}
