// =========================================================
// STEP 13J-D - DYNAMIC PACK / BMS DRILL-DOWN
//
// The Pack 5 design validated in 13J-C is now instantiated for every runtime
// pack. Pack tabs come from jkbms_pack_ids; BMS tabs/subviews come from the
// latest Step 13E aggregate members. A configured pack with no member snapshot
// yet receives a safe Master-only fallback view so it is never omitted from
// the dashboard. No new Home Assistant entity is created.
// =========================================================
function dashboardPathForPack(packId) {
    return String(packId).replace(/_/g, "-");
}

function bmsSlug(bms) {
    return String(bms).toLowerCase().replace(/[^a-z0-9]+/g, "-");
}

function bmsEntityPrefix(packId, bms) {
    return `${packId}_bms_${String(bms).toLowerCase()}`;
}

function bmsSensor(packId, bms, metric) {
    return `sensor.${bmsEntityPrefix(packId, bms)}_${metric}`;
}

function bmsBinary(packId, bms, metric) {
    return `binary_sensor.${bmsEntityPrefix(packId, bms)}_${metric}`;
}

function bmsDetailPath(packId, bms, defaultBms) {
    // v1.0.0-dev6: every BMS has its own hidden subview.
    // The pack base path is reserved for the Pack -> BMS overview.
    const base = dashboardPathForPack(packId);
    return `${base}-bms-${bmsSlug(bms)}`;
}

function dashboardNavigatePath(path) {
    return `/${DASHBOARD_URL_PATH}/${path}`;
}

function bmsTitle(bms) {
    return bms === "master" ? "Master" : `BMS ${bms}`;
}

function templateState(entity, suffix = "", precision = null) {
    const roundPart = precision === null ? "" : ` | float(0) | round(${precision})`;
    return `{% set v = states('${entity}') %}{% if v not in ['unknown','unavailable','none',''] %}{{ v${roundPart} }}${suffix}{% else %}-${suffix ? ` ${suffix.trim()}` : ""}{% endif %}`;
}

