    return {
        type: "vertical-stack",
        cards: [
            smartPhotonSectionTitle(null, `${packName(packId)} · ${bmsTitle(bms)}`, "38,166,154"),
            {
                type: "grid",
                columns: 4,
                square: false,
                cards: [
                    metricCard(power, txt.power, `{% set p=states('${power}')|float(0) %}{% if p|abs >= 1000 %}{{ (p/1000)|round(2) }} kW{% else %}{{ p|round(0) }} W{% endif %}`, "mdi:flash", "amber", "power"),
                    metricCard(voltage, txt.voltage, `{{ states('${voltage}') }} V`, "mdi:sine-wave", "green", "voltage"),
                    metricCard(delta, txt.cellDelta, `{{ ((states('${delta}')|float(0))*1000)|round(0) }} mV`, "mdi:delta",
                        `{% set d=((states('${delta}')|float(0))*1000) %}{% if d >= 50 %}red{% elif d >= 20 %}amber{% else %}green{% endif %}`, "delta"),
                    metricCard(current, txt.current, `{{ states('${current}') }} A`, "mdi:current-dc", "blue", "current"),
                    metricCard(mos, txt.temp, tempSecondary, "mdi:thermometer",
                        `{% set t=[states('${mos}')|float(-999),states('${s1}')|float(-999),states('${s2}')|float(-999)]|max %}{% if t >= 50 %}red{% elif t >= 40 %}amber{% else %}blue{% endif %}`),
                    metricCard(soc, "SOC", `{{ states('${soc}') }} %`, "mdi:battery-high", "blue", "soc"),
                    metricCard(remaining, txt.capacity, `{{ states('${remaining}') }} / {{ states('${nominal}') }} Ah`, "mdi:battery-charging-80", "green", "capacity"),
                    metricCard(balance, txt.balancing,
                        `{% set c=states('${balance}')|float(0) %}{% if c|abs > 0.001 %}${txt.active} · {% if c > 0 %}+{% endif %}{{ c|round(3) }} A{% else %}${txt.inactive}{% endif %}`,
                        "mdi:scale-balance",
                        `{% if (states('${balance}')|float(0)|abs) > 0.001 %}blue{% else %}grey{% endif %}`)
                ]
            }
        ]
    };
}

function packComparisonCard(packId, members, selectedBms, defaultBms) {
    if (!members.length) return null;

    if (!customCardsInstalled) {
        const preamble = [];
        const rows = [];
        for (const bms of members) {
            const key = bmsSlug(bms).replace(/-/g, "_");
            const soc = bmsSensor(packId, bms, "soc_pourcentage");
            const v = bmsSensor(packId, bms, "tension_totale_volt");
            const a = bmsSensor(packId, bms, "courant_total");
            const p = bmsSensor(packId, bms, "puissance_totale");
            const d = bmsSensor(packId, bms, "cell_voltage_delta");
            const bal = bmsSensor(packId, bms, "balance_courant");
            const alarm = bmsBinary(packId, bms, "alarm_active");
            const temps = [
                bmsSensor(packId, bms, "mos_temp"),
                bmsSensor(packId, bms, "sonde_1_temp"),
                bmsSensor(packId, bms, "sonde_2_temp")
            ];
            preamble.push(`{% set t_${key} = [states('${temps[0]}')|float(-999), states('${temps[1]}')|float(-999), states('${temps[2]}')|float(-999)] | max %}`);
            preamble.push(`{% set b_${key} = states('${bal}') | float(0) %}`);
            rows.push(`| **${bmsTitle(bms)}** | {{ states('${soc}') if states('${soc}') not in ['unknown','unavailable'] else '-' }} % | {{ states('${v}') if states('${v}') not in ['unknown','unavailable'] else '-' }} V | {{ states('${a}') if states('${a}') not in ['unknown','unavailable'] else '-' }} A | {{ ((states('${p}')|float(0))/1000) | round(2) }} kW | {{ ((states('${d}')|float(0))*1000) | round(0) }} mV | {% if t_${key} > -900 %}{{ t_${key} | round(1) }} °C{% else %}-{% endif %} | {% if b_${key}|abs > 0.001 %}{{ b_${key} | round(3) }} A{% else %}—{% endif %} | {% if is_state('${alarm}','on') %}**ALARM**{% else %}${txt.normalLabel}{% endif %} |`);
        }
        return {
            type: "markdown",
            content: `## ${txt.bmsComparison}\n${preamble.join("\n")}\n| BMS | SOC | ${txt.voltage} | ${txt.current} | ${txt.power} | Δ cell | ${txt.temp} | ${txt.balancing} | ${txt.alarm} |\n|---|---:|---:|---:|---:|---:|---:|---:|---|\n${rows.join("\n")}`
        };
    }

    const cards = members.map(bms => {
        const soc = bmsSensor(packId, bms, "soc_pourcentage");
        const v = bmsSensor(packId, bms, "tension_totale_volt");
        const a = bmsSensor(packId, bms, "courant_total");
        const p = bmsSensor(packId, bms, "puissance_totale");
        const d = bmsSensor(packId, bms, "cell_voltage_delta");
        const bal = bmsSensor(packId, bms, "balance_courant");
        const alarm = bmsBinary(packId, bms, "alarm_active");
        const mos = bmsSensor(packId, bms, "mos_temp");
        const s1 = bmsSensor(packId, bms, "sonde_1_temp");
        const s2 = bmsSensor(packId, bms, "sonde_2_temp");
        const selected = String(bms) === String(selectedBms);
        const selectedLiteral = selected ? "true" : "false";

        return {
            type: "custom:mushroom-template-card",
            entity: v,
            primary: selected ? `${bmsTitle(bms)} · ${txt.selected}` : bmsTitle(bms),
            secondary: `{% set vv=states('${v}') %}{% set aa=states('${a}') %}{% set pp=states('${p}')|float(0) %}{% set dd=(states('${d}')|float(0))*1000 %}{% set bb=states('${bal}')|float(0) %}{% set tt=[states('${mos}')|float(-999),states('${s1}')|float(-999),states('${s2}')|float(-999)]|max %}SOC {{ states('${soc}') }} % · {{ vv }} V · {{ aa }} A · {{ (pp/1000)|round(2) }} kW\nΔ {{ dd|round(0) }} mV · {% if tt > -900 %}{{ tt|round(1) }} °C{% else %}- °C{% endif %} · ${txt.balancing}: {% if bb|abs > 0.001 %}{{ bb|round(3) }} A{% else %}—{% endif %} · ${txt.alarm}: {% if is_state('${alarm}','on') %}ALARM{% else %}${txt.normalLabel}{% endif %}`,
            multiline_secondary: true,
            icon: `{% if is_state('${alarm}','on') %}mdi:alert-circle{% elif (states('${bal}')|float(0)|abs) > 0.001 %}mdi:battery-sync{% elif ${selectedLiteral} %}mdi:battery-check{% else %}mdi:battery{% endif %}`,
            icon_color: `{% if is_state('${alarm}','on') %}red{% elif (states('${bal}')|float(0)|abs) > 0.001 %}blue{% elif ${selectedLiteral} %}green{% else %}grey{% endif %}`,
            card_mod: smartPhotonGlow("126,87,194", 0.38, 0.10),
            ...(selected ? { badge_icon: "mdi:check", badge_color: "green" } : {}),
            fill_container: true,
            tap_action: {
                action: "navigate",
                navigation_path: dashboardNavigatePath(bmsDetailPath(packId, bms, defaultBms))
            }
        };
    });

    return {
        type: "vertical-stack",
        cards: [
            smartPhotonSectionTitle(null, txt.bmsComparison, "126,87,194"),
            {
                type: "grid",
                columns: Math.min(4, Math.max(1, members.length)),
                square: false,
                cards
            }
        ]
    };
}

function bmsSelectorCard(packId, members, selectedBms, defaultBms) {
    if (!members.length) return null;

    if (customCardsInstalled) {
        const columns = Math.min(4, Math.max(1, members.length));
        const selectorCards = members.map(bms => {
            const selected = String(bms) === String(selectedBms);
            const voltage = bmsSensor(packId, bms, "tension_totale_volt");
            return {
                type: "custom:button-card",
                template: "smartphoton_bms_selector",
                entity: voltage,
                name: bmsTitle(bms),
                label: selected
                    ? (lang === "fr" ? "✓ Sélectionné" : "✓ Selected")
                    : (lang === "fr" ? "Ouvrir" : "Open"),
                styles: selected ? {
                    card: [
                        { border: "1px solid rgba(57,230,107,.90)" },
                        { "box-shadow": "0 0 14px rgba(57,230,107,.20), inset 0 0 18px rgba(57,230,107,.06)" }
                    ],
                    name: [{ color: "#dfffe8" }],
                    label: [{ color: "#66f28d" }]
                } : {},
                tap_action: {
                    action: "navigate",
                    navigation_path: dashboardNavigatePath(bmsDetailPath(packId, bms, defaultBms))
                }
            };
        });

        // DEV28: keep the BMS selector visually grouped and slightly tighter.  The standard grid
        // used to stretch two BMS over the whole page, making them look like
        // unrelated status cards rather than one selector control.
        return {
            type: "custom:button-card",
            show_name: false,
            show_icon: false,
            show_state: false,
            tap_action: { action: "none" },
            styles: {
                card: [
                    { background: "transparent" },
                    { border: "0" },
                    { "box-shadow": "none" },
                    { padding: "0" }
                ],
                grid: [
                    { "grid-template-areas": '"selector"' },
                    { "grid-template-columns": "1fr" }
                ],
                custom_fields: {
                    selector: [
                        { "grid-area": "selector" },
                        { "justify-self": "center" },
                        { width: `min(${columns * 180}px, 100%)` },
                        { "min-width": "0" }
                    ]
                }
            },
            custom_fields: {
                selector: {
                    card: {
                        type: "grid",
                        columns,
                        square: false,
                        cards: selectorCards
                    }
                }
            }
        };
    }

    return {
        type: "grid",
        columns: Math.min(4, Math.max(1, members.length)),
        square: false,
        cards: members.map(bms => {
            const selected = String(bms) === String(selectedBms);
            const voltage = bmsSensor(packId, bms, "tension_totale_volt");
            return {
                type: "tile",
                entity: voltage,
                name: bmsTitle(bms),
                icon: selected ? "mdi:battery-check" : "mdi:battery",
                vertical: false,
                hide_state: false,
                tap_action: {
                    action: "navigate",
                    navigation_path: dashboardNavigatePath(bmsDetailPath(packId, bms, defaultBms))
                }
            };
        })
    };
}

