function bmsProgressCardMod(packId, bms, entity, kind, rgb = "41,182,246") {
    let prelude = "";
    let left = "0";
    let width = "{{ sp_pct }}";
    let barBackground = `linear-gradient(90deg, rgba(${rgb},.70), rgba(${rgb},1))`;

    if (kind === "power" || kind === "current") {
        const maxCharge = setupNumberEntity(packId, bms, "max_charge_current");
        const maxDischarge = setupNumberEntity(packId, bms, "max_discharge_current");
        const voltage = bmsSensor(packId, bms, "tension_totale_volt");
        prelude = `{% set sp_v=states('${entity}')|float(0) %}{% if sp_v >= 0 %}{% set sp_lim=states('${maxCharge}')|float(150) %}{% else %}{% set sp_lim=states('${maxDischarge}')|float(150) %}{% endif %}{% if sp_lim <= 0 %}{% set sp_lim=150 %}{% endif %}`;
        if (kind === "power") {
            prelude += `{% set sp_volt=states('${voltage}')|float(55) %}{% set sp_den=(sp_volt*sp_lim) %}{% if sp_den > 0 %}{% set sp_span=(sp_v|abs/sp_den*50) %}{% else %}{% set sp_span=0 %}{% endif %}`;
        } else {
            prelude += `{% set sp_span=(sp_v|abs/sp_lim*50) %}`;
        }
        prelude += `{% if sp_span > 50 %}{% set sp_span=50 %}{% endif %}{% if sp_v < 0 %}{% set sp_left=50-sp_span %}{% else %}{% set sp_left=50 %}{% endif %}`;
        left = "{{ sp_left }}";
        width = "{{ sp_span }}";
        barBackground = `{% if sp_v < 0 %}linear-gradient(90deg, rgba(41,182,246,.98), rgba(3,169,244,.72)){% else %}linear-gradient(90deg, rgba(57,230,107,.72), rgba(38,198,218,.98)){% endif %}`;
    } else if (kind === "voltage") {
        const cells = bmsSensor(packId, bms, "cell_count_used");
        prelude = `{% set sp_v=states('${entity}')|float(0) %}{% set sp_n=states('${cells}')|int(16) %}{% if sp_n <= 0 %}{% set sp_n=16 %}{% endif %}{% set sp_lo=sp_n*2.5 %}{% set sp_hi=sp_n*3.65 %}{% set sp_pct=((sp_v-sp_lo)/(sp_hi-sp_lo)*100) %}{% if sp_pct < 0 %}{% set sp_pct=0 %}{% elif sp_pct > 100 %}{% set sp_pct=100 %}{% endif %}`;
        barBackground = "linear-gradient(90deg, rgba(46,204,113,.82), rgba(41,182,246,.98))";
    } else if (kind === "delta") {
        prelude = `{% set sp_mv=(states('${entity}')|float(0)*1000) %}{% set sp_pct=sp_mv %}{% if sp_pct < 0 %}{% set sp_pct=0 %}{% elif sp_pct > 100 %}{% set sp_pct=100 %}{% endif %}`;
        barBackground = `{% if sp_mv >= 50 %}linear-gradient(90deg, rgba(255,167,38,.85), rgba(239,83,80,.98)){% elif sp_mv >= 20 %}linear-gradient(90deg, rgba(102,187,106,.75), rgba(255,167,38,.98)){% else %}linear-gradient(90deg, rgba(57,230,107,.72), rgba(38,198,218,.92)){% endif %}`;
    } else if (kind === "temperature") {
        prelude = `{% set sp_t=states('${entity}')|float(0) %}{% set sp_pct=(sp_t/60*100) %}{% if sp_pct < 0 %}{% set sp_pct=0 %}{% elif sp_pct > 100 %}{% set sp_pct=100 %}{% endif %}`;
        barBackground = `{% if sp_t >= 50 %}linear-gradient(90deg, rgba(255,167,38,.82), rgba(239,83,80,.98)){% elif sp_t >= 40 %}linear-gradient(90deg, rgba(41,182,246,.75), rgba(255,167,38,.98)){% else %}linear-gradient(90deg, rgba(41,182,246,.72), rgba(38,198,218,.98)){% endif %}`;
    } else if (kind === "capacity") {
        const nominal = bmsSensor(packId, bms, "capacite_batterie_ah");
        prelude = `{% set sp_r=states('${entity}')|float(0) %}{% set sp_n=states('${nominal}')|float(0) %}{% if sp_n > 0 %}{% set sp_pct=(sp_r/sp_n*100) %}{% else %}{% set sp_pct=0 %}{% endif %}{% if sp_pct < 0 %}{% set sp_pct=0 %}{% elif sp_pct > 100 %}{% set sp_pct=100 %}{% endif %}`;
        barBackground = "linear-gradient(90deg, rgba(57,230,107,.78), rgba(38,198,218,.98))";
    } else if (kind === "soc") {
        prelude = `{% set sp_pct=states('${entity}')|float(0) %}{% if sp_pct < 0 %}{% set sp_pct=0 %}{% elif sp_pct > 100 %}{% set sp_pct=100 %}{% endif %}`;
        barBackground = "linear-gradient(90deg, rgba(57,230,107,.82), rgba(38,198,218,.98))";
    } else {
        return smartPhotonGlow(rgb, 0.42, 0.11);
    }

    const signedBar = (kind === "power" || kind === "current");
    const trackBackground = signedBar
        ? "linear-gradient(90deg, rgba(41,182,246,.12) 0 49.72%, rgba(255,255,255,.58) 49.72% 50.28%, rgba(57,230,107,.12) 50.28% 100%)"
        : "rgba(255,255,255,.075)";
    const trackHeight = signedBar ? 4 : 3;

    return {
        style: `${prelude}
ha-card {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(${rgb}, 0.44);
  box-shadow:
    0 0 11px rgba(${rgb}, 0.12),
    inset 0 0 0 1px rgba(${rgb}, 0.07),
    inset 0 18px 40px rgba(24,119,190,0.035);
  border-radius: 12px;
  background:
    radial-gradient(circle at 8% 0%, rgba(${rgb}, 0.10), transparent 34%),
    linear-gradient(145deg, rgba(8,27,47,0.96), rgba(5,16,30,0.96)) !important;
}
ha-card::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: ${trackHeight}px;
  background: ${trackBackground};
}
ha-card::after {
  content: "";
  position: absolute;
  left: ${left}%;
  bottom: 0;
  width: ${width}%;
  height: ${trackHeight}px;
  background: ${barBackground};
  box-shadow: 0 0 8px rgba(${rgb},.42);
  transition: left .25s ease, width .25s ease;
}`
    };
}

function bmsMetricCard(packId, bms, label, metric, unit, icon, color, precision = null, barKind = null) {
    const entity = bmsSensor(packId, bms, metric);
    const value = precision === null
        ? `{{ states('${entity}') }}${unit ? ` ${unit}` : ""}`
        : `{{ states('${entity}') | float(0) | round(${precision}) }}${unit ? ` ${unit}` : ""}`;

    if (!customCardsInstalled) {
        return {
            type: "entity",
            entity,
            name: label
        };
    }

    return {
        type: "custom:mushroom-template-card",
        entity,
        primary: label,
        secondary: value,
        icon,
        icon_color: color,
        layout: "horizontal",
        multiline_secondary: false,
        card_mod: barKind
            ? bmsProgressCardMod(packId, bms, entity, barKind, barKind === "power" ? "255,193,7" : barKind === "current" ? "41,182,246" : "76,175,80")
            : smartPhotonGlow("76,175,80", 0.42, 0.11),
        fill_container: true,
        tap_action: { action: "more-info" }
    };
}

function remainingCapacityCard(packId, bms) {
    const remaining = bmsSensor(packId, bms, "capacite_restante_ah");
    const nominal = bmsSensor(packId, bms, "capacite_batterie_ah");

    if (!customCardsInstalled) {
        return { type: "entity", entity: remaining, name: txt.remaining };
