    return {
        type: "custom:mushroom-template-card",
        entity: remaining,
        primary: txt.remaining,
        secondary: `{% set r=states('${remaining}') %}{% set n=states('${nominal}') %}{% if r not in ['unknown','unavailable','none',''] %}{{ r|float(0)|round(1) }} Ah{% if n not in ['unknown','unavailable','none',''] and (n|float(0)) > 0 %} · {{ ((r|float(0))/(n|float(0))*100) | round(1) }} %{% endif %}{% else %}-{% endif %}`,
        icon: "mdi:battery-charging-80",
        icon_color: "green",
        layout: "horizontal",
        multiline_secondary: false,
        card_mod: bmsProgressCardMod(packId, bms, remaining, "capacity", "76,175,80"),
        fill_container: true,
        tap_action: { action: "more-info" }
    };
}

