        ]
    };
}

function cellSummaryCard(entity, primary, secondary, icon, iconColor) {
    if (!customCardsInstalled) {
        // Native Home Assistant fallback.
        // A plain entity card would display the raw bound cell entity state and
        // ignore the calculated template (which caused Min/Avg/Max/Delta cards
        // to show individual cell voltages instead of the computed values).
        return {
            type: "markdown",
            content: `**${primary}**  \\n${secondary}`
        };
    }
    return {
        type: "custom:mushroom-template-card",
        entity,
        primary,
        secondary,
        icon,
        icon_color: iconColor,
        layout: "horizontal",
        multiline_secondary: false,
        fill_container: true,
        tap_action: { action: "more-info" }
    };
}

function cellEntities(packId, bms) {
    return Array.from({ length: 16 }, (_, i) => bmsSensor(packId, bms, `cell_${i + 1}_volt`));
}

function cellSnapshotJinja(packId, bms) {
    const entities = cellEntities(packId, bms);
    const entityList = `[${entities.map(e => `'${e}'`).join(",")}]`;
    return `{% set ns=namespace(count=0,total=0.0,minv=999.0,maxv=-999.0,mini=0,maxi=0) %}{% for ce in ${entityList} %}{% set sv=states(ce) %}{% if sv not in ['unknown','unavailable','none',''] %}{% set cv=sv|float(0) %}{% set ns.count=ns.count+1 %}{% set ns.total=ns.total+cv %}{% if cv < ns.minv %}{% set ns.minv=cv %}{% set ns.mini=loop.index %}{% endif %}{% if cv > ns.maxv %}{% set ns.maxv=cv %}{% set ns.maxi=loop.index %}{% endif %}{% endif %}{% endfor %}{% if ns.count > 0 %}{% set cellavg=ns.total/ns.count %}{% set celldelta=ns.maxv-ns.minv %}{% else %}{% set cellavg=0.0 %}{% set celldelta=0.0 %}{% endif %}`;
}

function cellCard(packId, bms, index) {
    const entity = bmsSensor(packId, bms, `cell_${index}_volt`);
    const snapshot = cellSnapshotJinja(packId, bms);

    if (!customCardsInstalled) {
        return { type: "entity", entity, name: `#${index}` };
    }

    return {
        type: "custom:mushroom-template-card",
        entity,
        primary: `${snapshot}{% set vv=states('${entity}') %}{% if vv not in ['unknown','unavailable','none',''] %}#${index} · {{ ((vv|float(0))*1000)|round(0) }} mV{% else %}#${index} · -{% endif %}`,
        icon: "mdi:battery-medium",
        icon_color: `${snapshot}{% set vv=states('${entity}') %}{% if vv in ['unknown','unavailable','none',''] %}grey{% elif ns.count > 0 %}{% set ad=((((vv|float(0))-cellavg)*1000)|abs) %}{% if ad >= 50 %}red{% elif ad >= 20 %}orange{% elif ns.mini == ${index} %}blue{% elif ns.maxi == ${index} %}orange{% else %}green{% endif %}{% else %}grey{% endif %}`,
        badge_icon: `${snapshot}{% if ns.maxi == ${index} %}mdi:arrow-up-bold{% elif ns.mini == ${index} %}mdi:arrow-down-bold{% endif %}`,
        badge_color: `${snapshot}{% if ns.maxi == ${index} %}orange{% elif ns.mini == ${index} %}blue{% endif %}`,
        layout: "horizontal",
        multiline_secondary: false,
        card_mod: {
            style: `${snapshot}
ha-card {
  border: 1px solid rgba(41, 182, 246, 0.55);
  box-shadow:
    0 0 8px rgba(41, 182, 246, 0.20),
    inset 0 0 0 1px rgba(41, 182, 246, 0.10);
  border-radius: 12px;
  background: linear-gradient(
    145deg,
    rgba(41, 182, 246, 0.055),
    rgba(255, 255, 255, 0.012)
  );
  transition: box-shadow 0.20s ease, border-color 0.20s ease, transform 0.20s ease;
}
ha-card:hover {
  border-color: rgba(41, 182, 246, 0.90);
  box-shadow:
    0 0 12px rgba(41, 182, 246, 0.32),
    inset 0 0 0 1px rgba(41, 182, 246, 0.16);
}
{% if ns.maxi == ${index} %}
ha-card {
  border-color: rgba(255, 152, 0, 0.90);
  box-shadow:
    0 0 10px rgba(255, 152, 0, 0.28),
    inset 0 0 0 1px rgba(255, 152, 0, 0.14);
}
{% elif ns.mini == ${index} %}
ha-card {
  border-color: rgba(33, 150, 243, 0.90);
  box-shadow:
    0 0 10px rgba(33, 150, 243, 0.28),
    inset 0 0 0 1px rgba(33, 150, 243, 0.14);
}
{% endif %}`
        },
        fill_container: true,
        tap_action: { action: "more-info" }
    };
}

