            glowMetricCard(delta, txt.cellDelta, `{{ ((states('${delta}')|float(0))*1000)|round(0) }} mV`, "mdi:delta",
                `{% set d=((states('${delta}')|float(0))*1000) %}{% if d >= 50 %}red{% elif d >= 20 %}amber{% else %}green{% endif %}`,
