                { action: "navigate", navigation_path: path }),
            glowMetricCard(current, txt.current, `{{ states('${current}') }} A`, "mdi:current-dc", "blue", "41,182,246", { action: "navigate", navigation_path: path }),
            glowMetricCard(mos, txt.temp, tempTemplate, "mdi:thermometer",
                `{% set t=[states('${mos}')|float(-999),states('${probe1}')|float(-999),states('${probe2}')|float(-999)]|max %}{% if t >= 50 %}red{% elif t >= 40 %}amber{% else %}blue{% endif %}`,
                "41,182,246",
                { action: "navigate", navigation_path: path }),
            glowMetricCard(remaining, txt.capacity, capacityTemplate, "mdi:battery-charging-80", "green", "57,230,107", { action: "navigate", navigation_path: path })
        ]
    };

    const chips = {
        type: "custom:mushroom-chips-card",
        alignment: "start",
        chips: [
            {
                type: "template",
                entity: balance,
                content: `{% set c=states('${balance}')|float(0) %}{% if c|abs > 0.001 %}${txt.balancing}: ${txt.active} · {% if c > 0 %}+{% endif %}{{ c|round(3) }} A{% else %}${txt.balancing}: ${txt.inactive}{% endif %}`,
