                icon_color: `{% if (states('${balance}')|float(0)|abs) > 0.001 %}blue{% else %}grey{% endif %}`,
                tap_action: { action: "navigate", navigation_path: path }
            },
            {
                type: "template",
                entity: alarm,
                content: `{% if is_state('${alarm}','on') %}ALARM{% else %}${txt.noAlarmLabel}{% endif %}`,
                icon: `{% if is_state('${alarm}','on') %}mdi:alert-circle{% else %}mdi:check-circle{% endif %}`,
                icon_color: `{% if is_state('${alarm}','on') %}red{% else %}green{% endif %}`,
                tap_action: { action: "navigate", navigation_path: path }
            }
        ]
    };

    return {
        type: "custom:stack-in-card",
        mode: "vertical",
        keep: {
            background: true,
            border_radius: true,
            box_shadow: true,
            margin: false
        },
        cards: [
            header,
            {
                type: "horizontal-stack",
                cards: [
                    {
                        type: "horizontal-stack",
                        cards: [devicePicture, socVisual]
                    },
                    metrics
                ]
            },
            chips
