        card_mod: {
            style: `{% set d=((states('${delta}')|float(0))*1000) %}{% set t=[states('${mos}')|float(-999),states('${probe1}')|float(-999),states('${probe2}')|float(-999)]|max %}{% set a=is_state('${alarm}','on') %}{% if a or d >= 50 or t >= 50 %}{% set rgb='239,83,80' %}{% elif d >= 20 or t >= 40 %}{% set rgb='255,167,38' %}{% elif (states('${balance}')|float(0)|abs) > 0.001 %}{% set rgb='41,182,246' %}{% else %}{% set rgb='38,166,154' %}{% endif %}
ha-card {
