function setupNumberEntity(packId, bms, key) {
    return `number.${bmsEntityPrefix(packId,bms)}_bms_${key}`;
}
function setupSensorEntity(packId, bms, key) {
    return `sensor.${bmsEntityPrefix(packId,bms)}_bms_${key}`;
}
function setupSwitchEntity(packId, bms, key) {
    const mode = communicationModeInfo();
    const activePolling = mode.mode === "ACTIVE POLLING";
    return activePolling
        ? `switch.${bmsEntityPrefix(packId,bms)}_${key}_active_polling`
        : `switch.${bmsEntityPrefix(packId,bms)}_bms_${key}`;
}

function parameterReadOnlyCard(entity, label, icon = "mdi:tune") {
    if (!customCardsInstalled) return { type: "entity", entity, name: label };
    return {
        type: "custom:mushroom-template-card",
        entity,
        primary: label,
        secondary: `{{ states('${entity}') }}`,
        icon,
        icon_color: "blue",
        tap_action: { action: "none" },
        card_mod: smartPhotonGlow("41,182,246", .34, .09)
    };
}

function parameterGroupCard(packId, bms, title, rgb, defsList, writable) {
    const entities = defsList.map(d => ({ entity: setupNumberEntity(packId,bms,d[0]), name: lang === "fr" ? d[2] : d[1] }));
    if (writable) {
        return {
            type: "vertical-stack",
            cards: [
                smartPhotonSectionTitle(null, title, rgb),
                {
                    type: "entities",
                    show_header_toggle: false,
                    state_color: true,
                    entities,
                    card_mod: smartPhotonGlow(rgb, .46, .12)
                }
            ]
        };
    }

    const rows = defsList.map(d => {
        const entity = setupNumberEntity(packId,bms,d[0]);
        const label = lang === "fr" ? d[2] : d[1];
        return `**${label} :** {{ states('${entity}') }}`;
    }).join("  \\n");

    return {
        type: "vertical-stack",
