function resistanceEntities(packId, bms) {
    return Array.from({ length: 16 }, (_, i) => bmsSensor(packId, bms, `cell_${i + 1}_ohm`));
}

function resistanceSnapshotJinja(packId, bms) {
    const entities = resistanceEntities(packId, bms);
    const entityList = `[${entities.map(e => `'${e}'`).join(",")}]`;
    return `{% set ns=namespace(count=0,total=0.0,minv=999999.0,maxv=-999999.0,mini=0,maxi=0) %}{% for re in ${entityList} %}{% set sv=states(re) %}{% if sv not in ['unknown','unavailable','none',''] %}{% set rv=(sv|float(0))*1000 %}{% set ns.count=ns.count+1 %}{% set ns.total=ns.total+rv %}{% if rv < ns.minv %}{% set ns.minv=rv %}{% set ns.mini=loop.index %}{% endif %}{% if rv > ns.maxv %}{% set ns.maxv=rv %}{% set ns.maxi=loop.index %}{% endif %}{% endif %}{% endfor %}{% if ns.count > 0 %}{% set ravg=ns.total/ns.count %}{% set rdelta=ns.maxv-ns.minv %}{% else %}{% set ravg=0.0 %}{% set rdelta=0.0 %}{% endif %}`;
}

function bmsVoltageDiagnosticSection(packId, bms) {
    const snapshot = cellSnapshotJinja(packId, bms);
    const cell1 = bmsSensor(packId, bms, "cell_1_volt");
    const cell9 = bmsSensor(packId, bms, "cell_9_volt");

    const summary = [
        cellSummaryCard(cell1, "Min", `${snapshot}{% if ns.count > 0 %}{{ ns.minv|round(3) }} V · #{{ ns.mini }}{% else %}-{% endif %}`, "mdi:arrow-down-bold", "blue"),
        cellSummaryCard(cell1, lang === "fr" ? "Moyenne" : "Average", `${snapshot}{% if ns.count > 0 %}{{ cellavg|round(3) }} V{% else %}-{% endif %}`, "mdi:approximately-equal", "green"),
        cellSummaryCard(cell9, "Max", `${snapshot}{% if ns.count > 0 %}{{ ns.maxv|round(3) }} V · #{{ ns.maxi }}{% else %}-{% endif %}`, "mdi:arrow-up-bold", "orange"),
        cellSummaryCard(cell9, "Delta", `${snapshot}{% if ns.count > 0 %}{{ (celldelta*1000)|round(0) }} mV{% else %}-{% endif %}`, "mdi:delta", `${snapshot}{% set d=celldelta*1000 %}{% if d >= 50 %}red{% elif d >= 20 %}amber{% else %}green{% endif %}`)
    ];

    return {
        type:"vertical-stack",
        cards:[
            smartPhotonSectionTitle(null,txt.completeCellDetails,"41,182,246"),
            {type:"grid",columns:4,square:false,cards:summary},
