        type:"custom:mushroom-template-card",
        entity,
        primary:`{% set rv=states('${entity}') %}{% if rv not in ['unknown','unavailable','none',''] %}#${index} · {{ ((rv|float(0))*1000)|round(0) }} mΩ{% else %}#${index} · -{% endif %}`,
        icon:"mdi:resistor-nodes",
