function buildDynamicPackViews() {
    const views = [];

    for (const packId of packIds) {
        let members = packMembersForDashboard(packId);

        if (!members.length) {
            members = ["master"];
            node.warn(`Step 13J-D: ${packId} has no 13E member snapshot yet; generating Master-only fallback view.`);
        }

        const defaultBms = members.includes("master") ? "master" : members[0];
        const bmsColumns = members.length <= 1 ? 1 : 2;

        views.push({
            type: "panel",
            path: dashboardPathForPack(packId),
            title: packName(packId),
            subview: true,
            icon: "mdi:battery-multiple",
            cards: [{
                type: "vertical-stack",
                cards: [
                    packHeaderGrid(packId),
                    smartPhotonSectionTitle(null, lang === "fr" ? "BMS du pack" : "Pack BMS", "126,87,194"),
                    {
                        type: "grid",
                        columns: bmsColumns,
                        square: false,
                        cards: members.map(bms => bmsOverviewVisualCard(packId, bms, defaultBms))
                    },
                    { type: "markdown", content: `_${txt.refreshNote}_` }
                ]
            }]
        });

        for (const bms of members) {
            let detailArea;
            if (customCardsInstalled) {
                detailArea = {
                    type: "custom:button-card",
                    show_name: false,
                    show_icon: false,
                    show_state: false,
                    tap_action: { action: "none" },
                    styles: {
                        card: [
                            { background: "linear-gradient(145deg, rgba(4,18,34,.98), rgba(3,12,25,.98))" },
                            { border: "1px solid rgba(41,182,246,.18)" },
                            { "box-shadow": "0 0 24px rgba(41,182,246,.09), inset 0 0 45px rgba(15,86,135,.035)" },
                            { "border-radius": "14px" },
                            { padding: "4px" }
                        ],
                        grid: [
                            // DEV33: widen the visual breathing column between the two Live domains.
                            // Energy stays on the left; thermal/BMS state stays on the right.
                            { "grid-template-areas": '"energy . right"' },
                            { "grid-template-columns": "minmax(0, 1fr) clamp(58px, 4vw, 72px) minmax(0, 1fr)" },
                            { gap: "0" },
                            { "align-items": "start" }
                        ],
                        custom_fields: {
                            energy: [{ "grid-area": "energy" }, { "min-width": "0" }, { "align-self": "start" }],
                            right: [{ "grid-area": "right" }, { "min-width": "0" }, { "align-self": "start" }]
                        }
                    },
                    custom_fields: {
                        energy: { card: bmsEnergyColumn(packId, bms) },
                        right: { card: bmsRightColumn(packId, bms) }
                    },
                    extra_styles: `
@media (max-width: 980px) {
  #container {
    grid-template-areas: "energy" "right" !important;
    grid-template-columns: 1fr !important;
    row-gap: 10px !important;
  }
}`
                };
            } else {
                detailArea = {
                    type: "vertical-stack",
                    cards: [
                        { type: "grid", columns: 2, square: false, cards: [bmsEnergyColumn(packId,bms), bmsRightColumn(packId,bms)] }
                    ]
                };
            }

            const liveTop = [
                bmsHeaderGrid(packId,bms),
                bmsSelectorCard(packId,members,bms,defaultBms)
            ].filter(Boolean);
            const compactTop = [
                bmsSelectorCard(packId,members,bms,defaultBms)
            ].filter(Boolean);

            views.push({
                type:"panel",
                path:bmsTabPath(packId,bms,"live"),
                title:`${packName(packId)} · ${bmsTitle(bms)}`,
                subview:true,
                icon:"mdi:battery-medium",
                cards:[{type:"vertical-stack",cards:[
                    ...liveTop,
                    bmsPremiumNavCard(packId,bms,"live"),
                    detailArea,
                    bmsHistoryGrid(packId,bms),
                    {type:"markdown",content:`_${txt.refreshNote}_`}
                ]}]
            });

            views.push({
                type:"panel",
                path:bmsTabPath(packId,bms,"parameters"),
                title:`${packName(packId)} · ${bmsTitle(bms)} · ${txt.parameters}`,
                subview:true,
                icon:"mdi:tune-variant",
                cards:[{type:"vertical-stack",cards:[
                    ...compactTop,
                    bmsPremiumNavCard(packId,bms,"parameters"),
                    bmsParametersTab(packId,bms)
                ]}]
            });

            views.push({
                type:"panel",
                path:bmsTabPath(packId,bms,"diagnostic"),
                title:`${packName(packId)} · ${bmsTitle(bms)} · ${txt.diagnostic}`,
                subview:true,
                icon:"mdi:chart-box-outline",
                cards:[{type:"vertical-stack",cards:[
                    ...compactTop,
                    bmsPremiumNavCard(packId,bms,"diagnostic"),
                    bmsDiagnosticTab(packId,bms)
                ]}]
            });

            views.push({
                type:"panel",
                path:bmsTabPath(packId,bms,"alarms"),
                title:`${packName(packId)} · ${bmsTitle(bms)} · ${txt.alarms}`,
                subview:true,
                icon:"mdi:alarm-light-outline",
                cards:[{type:"vertical-stack",cards:[
                    ...compactTop,
                    bmsPremiumNavCard(packId,bms,"alarms"),
                    bmsAlarmsTab(packId,bms)
                ]}]
            });
        }
    }

    return views;
}

// =========================================================
// STEP 13J-J - OVERVIEW PACK ROW SPACING
//
// Overview pack cards now expose their actual BMS topology as clickable
// Mushroom chips. Each chip navigates directly to the selected BMS subview.
// Pack summary lines are also slightly more spaced for readability.
// Pack/BMS detail pages and Diagnostics remain unchanged.
//
// =========================================================
// STEP 13J-G - FINAL OVERVIEW + DIAGNOSTICS VISUAL PASS
//
// Pack pages are intentionally left untouched. This pass modernises only
// Overview and Diagnostics, makes pack cards navigable, cleans technical
// source labels, and lets the diagnostic summary reuse retained attributes
// when the MQTT diagnostic state has just expired.
// =========================================================
function jinjaSafeText(value) {
    return String(value ?? "").replace(/\\/g, "\\\\").replace(/'/g, "\\'");
}

function packNameMapLiteral() {
    const pairs = packIds.map(packId =>
        `'${jinjaSafeText(packId)}':'${jinjaSafeText(packName(packId))}'`
    );
    return `{${pairs.join(',')}}`;
}

function readablePackExpr(expr) {
    return `{% set pn=${packNameMapLiteral()} %}{{ pn.get(${expr}, ${expr} or '-') }}`;
}

function readableSourceExpr(attrName, entityVar = "e") {
    let expr = `(state_attr(${entityVar}, '${attrName}') or '-')`;
    for (const packId of packIds) {
        expr += ` | replace('${jinjaSafeText(packId)}','${jinjaSafeText(packName(packId))}')`;
    }
    expr += ` | replace('BMS_master','Master')`;
    expr += ` | replace('BMS_','BMS ')`;
    expr += ` | replace('Cell_','Cell ')`;
    expr += ` | replace('Mos_temp','MOS')`;
    expr += ` | replace('Sonde_1_temp','Battery 1')`;
    expr += ` | replace('Sonde_2_temp','Battery 2')`;
    expr += ` | replace('/',' · ')`;
    return `{{ ${expr} }}`;
}

function diagnosticAvailableTest(entityExpr = "e") {
    return `(state_attr(${entityExpr}, 'status') or states(${entityExpr})) not in ['unknown','unavailable','none','']`;
}

function compactMetricCard(entity, primary, secondary, icon, iconColor = "blue", tapAction = null) {
    if (!customCardsInstalled) {
        return {
            type: "markdown",
            content: `**${primary}**  \n${secondary}`
        };
    }
    return {
        type: "custom:mushroom-template-card",
        entity,
        primary,
        secondary,
        icon,
        icon_color: iconColor,
        layout: "horizontal",
        multiline_secondary: true,
        fill_container: true,
        tap_action: tapAction || { action: "more-info" }
    };
}

// Larger-reading variant used only by Overview + Diagnostics.
// The dynamic value is deliberately placed in Mushroom's primary line,
// which is rendered larger than secondary text without requiring card-mod.
function readableMetricCard(entity, label, value, icon, iconColor = "blue", tapAction = null, extra = "") {
    if (!customCardsInstalled) {
