function packTransportLabel(packId) {
    const defs = global.get("jkbms_pack_defs") || global.get("jkbms_pack_defs_configured") || {};
    const def = defs && defs[packId] ? defs[packId] : null;
    const transport = String(def && def.transport ? def.transport : "").toLowerCase();
    if (transport === "serial") return "USB/RS485";
    if (transport === "tcp") return "TCP/IP";
    return lang === "fr" ? "Transport inconnu" : "Unknown transport";
}

function communicationModeInfo() {
    const broadcasting = global.get("bms_broadcasting") === true;
    const activePolling = global.get("jkbms_active_polling_enabled") === true;
    const settingsAllowed = global.get("Authorize_Modify_Settings") === true;

    if (broadcasting) {
        return {
            mode: "BROADCASTING",
            detail: lang === "fr" ? "Paramètres verrouillés" : "Settings locked",
            icon: "mdi:lock",
            color: "amber"
        };
    }
    if (activePolling) {
        return {
            mode: "ACTIVE POLLING",
            detail: settingsAllowed
                ? (lang === "fr" ? "Paramètres accessibles" : "Settings available")
                : (lang === "fr" ? "Lecture seule" : "Read only"),
            icon: settingsAllowed ? "mdi:lock-open-variant" : "mdi:eye",
            color: settingsAllowed ? "green" : "blue"
        };
    }
    return {
        mode: lang === "fr" ? "MODE INCONNU" : "UNKNOWN MODE",
        detail: lang === "fr" ? "Vérifier la configuration" : "Check configuration",
        icon: "mdi:help-circle",
        color: "grey"
    };
}

