return [msg, null];

const value = msg.payload;
if (value && typeof value === "object" && Object.prototype.hasOwnProperty.call(value,"code")) {
    if (value.code !== 0) node.warn("Dashboard sync: command failed (exit " + String(value.code).slice(0,12) + ")");
    return null;
}
let result;
try { result = JSON.parse(Buffer.isBuffer(value) ? value.toString() : String(value)); }
catch (_) { if (String(value || "").trim()) node.warn("Dashboard sync: non-JSON output; inspect command in Node-RED"); return null; }
const action = result.action === "delete" ? "delete" : result.action === "upsert" ? "upsert" : "command";
const allowed = ["smart-jkbms-multipack", "smart-jkbms-scada", "smart-jkbms-glow"];
const target = allowed.includes(result.dashboard) ? result.dashboard : "unspecified";
if (result.ok === true) node.log("Dashboard sync: " + action + " " + target + " OK");
else node.warn("Dashboard sync: " + action + " " + target + " FAILED (check HA connection, credentials and dashboard file)");
return null;

// =========================================================
// DEV66 - SMARTPHOTON INDUSTRIAL SCADA MENU
//
// IMPORTANT:
// - Does NOT modify the existing Premium Multi-Pack Lovelace dashboard.
// - Creates a second Home Assistant sidebar dashboard only when
//   Premium + Multi-Pack is valid.
