const FEATURE = "dashboard_premium";
const DASHBOARD_FILE = "/config/dashboards/smart_jkbms_scada.json";
const DASHBOARD_URL_PATH = "smart-jkbms-scada";

const runtimeMode = String(
    global.get("premium.runtime_mode") ||
    global.get("jkbms_runtime_mode") ||
    "legacy"
).trim().toLowerCase();

const features = global.get("premium.features") || {};
const allowed =
    runtimeMode === "multi_pack" &&
    global.get("premium.multi_pack_premium_available") === true &&
    features[FEATURE] === true;

const activePolling = global.get("jkbmsActiveRequested") === true;
const broadcasting = global.get("bms_broadcasting") === true;
const commMode = activePolling ? "active_polling" : (broadcasting ? "broadcasting" : "standard");

if (!allowed) {
    node.status({
        fill: features[FEATURE] === true ? "blue" : "grey",
        shape: "ring",
        text: features[FEATURE] === true ? "SCADA not applicable" : "SCADA: Premium required"
    });
    msg.filename = DASHBOARD_FILE;
    return [null, msg];
}

const dashboard = {
    dashboard_meta: {
        url_path: DASHBOARD_URL_PATH,
        title: "JK-BMS SCADA",
